// THE CLIENT'S OWN WORDS REACH THE DRAFTER. Until this, `createDocument` received
// `brief` and used it for `makeTitle` alone, so the original named a FILE and the
// drafter read Gemini's compression of it. Measured consequence: the brief said
// "in about a minute" and ten of twelve headlines said "in 60 seconds", a phrase
// present in no input at all.
test('briefBlock labels the brief as authoritative and demotes the two derived sources', () => {
  const { briefBlock } = require('../src/services/gemini');
  const block = briefBlock('Runs in about a minute. Ops persona, Q3.').join('\n');

  assert.match(block, /AUTHORITATIVE/, 'the brief outranks the paraphrases');
  assert.match(block, /the client's own words, verbatim/);
  assert.match(block, /Where it and the\s*\n?\s*summary below differ, follow the brief/,
    'precedence is stated, not implied by ordering');
  assert.ok(block.includes('Runs in about a minute. Ops persona, Q3.'), 'verbatim, not summarised');

  // The other two are still present and still labelled by WHAT THEY ARE. Three
  // sources with equal billing invite the model to reconcile them and prefer the
  // shortest; naming the derivation is the whole point of keeping them.
  const { derivedCampaignLines } = require('../src/services/gemini');
  const derived = derivedCampaignLines('S', 'W', false).join('\n');
  assert.match(derived, /Creative direction \(a directive extracted from the brief\): W/);
  assert.match(derived, /Campaign summary \(a read of the ask — the brief above is the source\): S/);

  // BOTH draft builders, identically — a field rescued out of a failed batch must
  // not be told a different story about which source wins. The two lines moved
  // into derivedCampaignLines when they gained a second wording, so the pairing
  // that has to hold is briefBlock and derivedCampaignLines called together,
  // twice, with the SAME enrichment flag.
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  assert.strictEqual(
    (src.match(/\.\.\.briefBlock\(brief, enrichedFromReferences\)/g) || []).length, 2, 'both draft prompts'
  );
  assert.strictEqual(
    (src.match(/\.\.\.derivedCampaignLines\(summary, writerPrompt, enrichedFromReferences\)/g) || []).length, 2
  );
});

test('the brief block and the derived labels tell the truth on the REFERENCE path', () => {
  const { briefBlock, derivedCampaignLines } = require('../src/services/gemini');

  // THE BUG THIS FIXES. enrichWithReferences REWRITES summary and writerPrompt
  // from the reference content and both adapters overwrite the originals, so on
  // this path the summary can carry a statistic or a persona the brief does not.
  // "Where it and the summary below differ, follow the brief" told the model to
  // throw exactly that away.
  const enriched = briefBlock('Runs in about a minute.', true).join('\n');
  assert.ok(
    !/Where it and the\s*\n?\s*summary below differ, follow the brief\./.test(enriched),
    'the unconditional precedence sentence is gone on this path'
  );
  assert.match(enriched, /reference material/, 'the model is TOLD which case it is in');
  assert.match(enriched, /keep them/, 'reference-derived specifics survive');
  // The brief still wins where they genuinely conflict — demoted, not dethroned.
  assert.match(enriched, /AUTHORITATIVE/);
  assert.match(enriched, /conflict about what the campaign IS or how it is worded,\s*\n?\s*follow the brief/);

  // The labels move WITH it: saying the summary came from the linked material and
  // then calling it "a read of the ask — the brief above is the source" two lines
  // later would re-open the contradiction.
  const derived = derivedCampaignLines('S', 'W', true).join('\n');
  assert.match(derived, /Creative direction \(a directive extracted from the brief and the linked reference material\)/);
  assert.match(derived, /Campaign summary \(a read of the brief and the linked reference material\)/);
  assert.ok(!/a read of the ask/.test(derived));

  // AND THE COMMON PATH DOES NOT MOVE. A brief that linked nothing gets the exact
  // bytes it got before this change.
  assert.strictEqual(
    briefBlock('Runs in about a minute.', false).join('\n'),
    briefBlock('Runs in about a minute.').join('\n'),
    'omitted flag === false'
  );
  assert.match(briefBlock('x', false).join('\n'), /Where it and the\s*\n?\s*summary below differ, follow the brief\./);
});

test('funnel stage: ONE definition, reached by both the draft and review prompts', () => {
  const {
    FUNNEL_STAGE_INFERENCE, FUNNEL_STAGE_FOR_DRAFT, FUNNEL_STAGE_FOR_REVIEW, buildVariantReviewPrompt,
  } = require('../src/services/gemini');

  // The DEFINITION is what must never drift. Two prompts carrying their own
  // wording for top- and bottom-of-funnel leaves a future reader with two
  // answers and no way to tell which is current — so there is one array and
  // both sides splat it. A literal re-typed into either prompt fails here.
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  assert.strictEqual(
    (src.match(/Infer the FUNNEL STAGE from the asset type \+ brief/g) || []).length, 1,
    'the definition is written exactly once'
  );
  assert.strictEqual((src.match(/\.\.\.FUNNEL_STAGE_INFERENCE/g) || []).length, 3,
    'both draft builders and the review prompt reach for it');

  // The CONSEQUENCE clause is per-prompt on purpose: "which doorway fits" means
  // nothing where doorways do not exist, and the draft prompts have no such
  // concept. A dangling term is worse than none.
  assert.match(FUNNEL_STAGE_FOR_REVIEW, /doorway/);
  assert.ok(!/doorway/i.test(FUNNEL_STAGE_FOR_DRAFT), 'the draft clause names no review concept');

  // The review prompt still says it, via the shared constant.
  const prompt = buildVariantReviewPrompt({
    assetType: 'Organic Social — LinkedIn', fieldName: 'Post Copy', charMax: 200,
    variations: [{ doorway: 'Contrast', copy: 'a' }],
  });
  for (const line of FUNNEL_STAGE_INFERENCE) assert.ok(prompt.includes(line));
  assert.ok(prompt.includes(FUNNEL_STAGE_FOR_REVIEW));
});

test('funnel stage: the draft prompts infer it, and a stored value still wins', async () => {
  const { FUNNEL_STAGE_INFERENCE, FUNNEL_STAGE_FOR_DRAFT } = require('../src/services/gemini');
  const field = { assetType: 'Organic Social — LinkedIn', fieldName: 'Post Copy', charMax: 200, summary: 'S', writerPrompt: 'W' };

  const inferred = (await geminiWith(() => 'Short line.', (g) => g.generateFieldDraft(field))).prompts[0];
  for (const line of FUNNEL_STAGE_INFERENCE) assert.ok(inferred.includes(line), 'inference reaches the drafter');
  assert.ok(inferred.includes(FUNNEL_STAGE_FOR_DRAFT));
  // It sits BELOW the campaign context it tells the model to read.
  assert.ok(
    inferred.indexOf('Campaign summary') < inferred.indexOf('Infer the FUNNEL STAGE'),
    'the evidence is above the instruction to read it'
  );

  // A STORED stage still wins. Nothing writes one today, but a column or a
  // per-brief value would, and an inference must not talk over it.
  const stored = (await geminiWith(
    () => 'Short line.',
    (g) => g.generateFieldDraft({ ...field, funnelStage: 'consideration' })
  )).prompts[0];
  assert.ok(stored.includes('Funnel stage: consideration'));
  assert.ok(!stored.includes('Infer the FUNNEL STAGE'), 'no inference when a value was set');

  // The BATCH builder says it too — it is the path that drafts most copy.
  const batch = (await geminiWith(
    () => '{"Post Copy":"Short line."}',
    (g) => g.generateAssetDrafts({ ...field, fields: [{ fieldName: 'Post Copy', charMax: 200 }] })
  )).prompts[0];
  for (const line of FUNNEL_STAGE_INFERENCE) assert.ok(batch.includes(line), 'and the batch prompt');
});

test('the funnelInference control suppresses the block on EVERY call, rescue included', async () => {
  // scripts/funnelAB.js's BEFORE arm is only a control if it holds for the whole
  // asset. The rescue reaches generateFieldDraft separately, and the first
  // version of this did NOT thread the flag — so a batch that dropped one field
  // put the inference block back for that field, and the arm measured a mixture
  // while reporting a control. Found by running the script against a stubbed
  // transport, which is the only reason it is a test rather than a bad number.
  const args = {
    assetType: 'Organic Social — LinkedIn', summary: 'S', writerPrompt: 'W', funnelInference: false,
    fields: [{ fieldName: 'Post Copy', charMax: 200 }],
  };

  // Batch parses cleanly: one call, no block.
  const clean = await geminiWith(() => '{"Post Copy":"Short line."}', (g) => g.generateAssetDrafts(args));
  assert.strictEqual(clean.prompts.length, 1);

  // Batch fails to parse: the rescue runs, and it must be suppressed too.
  const failed = await geminiWith(
    (_p, n) => (n === 1 ? 'not json' : 'Short line.'),
    (g) => g.generateAssetDrafts(args)
  );
  assert.strictEqual(failed.prompts.length, 2, 'the rescue ran');
  for (const p of [...clean.prompts, ...failed.prompts]) {
    assert.ok(!/Infer the FUNNEL STAGE/.test(p), 'no call in the arm carries the block');
  }

  // And the default is ON — omitting the flag is production behaviour, so a
  // caller that never heard of it is unaffected.
  const dflt = await geminiWith(
    (_p, n) => (n === 1 ? 'not json' : 'Short line.'),
    (g) => g.generateAssetDrafts({ ...args, funnelInference: undefined })
  );
  assert.strictEqual(dflt.prompts.length, 2);
  for (const p of dflt.prompts) assert.match(p, /Infer the FUNNEL STAGE/);
});

test('reference stats reach BOTH draft builders, and the rescue too', async () => {
  const stats = [{ text: '4 hours saved per week', source: 'Ops Benchmark 2026' }];
  const args = {
    assetType: 'Organic Social — LinkedIn', summary: 'S', writerPrompt: 'W',
    brief: 'Runs in about a minute.', enrichedFromReferences: true, referenceStats: stats,
  };

  const single = (await geminiWith(
    () => 'Short line.',
    (g) => g.generateFieldDraft({ ...args, fieldName: 'Post Copy', charMax: 200 })
  )).prompts[0];
  assert.match(single, /FIGURES REPORTED IN THE LINKED MATERIAL/);
  assert.match(single, /^- 4 hours saved per week$/m, 'the figure, without its source');
  // The relabelled campaign lines travel with them — same enrichment flag.
  assert.match(single, /Campaign summary \(a read of the brief and the linked reference material\)/);

  // THE RESCUE. A batch that fails to parse sends every field to the single-field
  // generator; a rescued field must not be the ONE field in the asset drafted
  // without the figures, or told a different story about where its direction
  // came from. Same rule the brief already follows.
  const { prompts } = await geminiWith(
    (p, n) => (n === 1 ? 'not json at all' : 'Short line.'),
    (g) => g.generateAssetDrafts({ ...args, fields: [{ fieldName: 'Post Copy', charMax: 200 }] })
  );
  assert.strictEqual(prompts.length, 2, 'the batch failed and the rescue ran');
  assert.ok(isBatchPrompt(prompts[0]) && !isBatchPrompt(prompts[1]));
  for (const p of prompts) {
    assert.match(p, /FIGURES REPORTED IN THE LINKED MATERIAL/);
    assert.match(p, /^- 4 hours saved per week$/m);
    assert.ok(!p.includes('Ops Benchmark 2026'), 'no source name on any call in the asset');
    assert.match(p, /a read of the brief and the linked reference material/);
  }
});

test('reference stats reach the prompt as ATTRIBUTED, never as verified', () => {
  const { referenceStatsBlock, MAX_REFERENCE_STATS } = require('../src/services/gemini');

  assert.deepStrictEqual(referenceStatsBlock([]), [], 'no stats, no block');
  assert.deepStrictEqual(referenceStatsBlock(undefined), []);
  assert.deepStrictEqual(referenceStatsBlock([{ text: '   ', source: 'X' }]), [], 'blank rows drop');

  const block = referenceStatsBlock([
    { text: '4 hours saved per week', source: 'Ops Benchmark 2026' },
    { text: '38% faster onboarding', source: null },
  ]).join('\n');

  // THE SOURCE NAME NEVER REACHES THE PROMPT. Sending it turned the source into
  // a lead magnet the client was offering: five of five Offer 2 bodies pitched a
  // report Quillio does not have, and a source hostname appeared by name in
  // customer-facing copy. craft.md's always-injected CTA library has a
  // "Gated content (whitepaper, report, guide)" destination and says the CTA
  // must match the destination, so a named report in the prompt is an offer the
  // model is correct to reach for. The fix is to remove the object, not to
  // prohibit it — a prohibition would have to beat a rule that is right.
  assert.ok(!block.includes('Ops Benchmark 2026'), 'the source name is withheld');
  assert.ok(!/2026/.test(block), 'and so is anything inside it');
  assert.match(block, /^- 4 hours saved per week$/m, 'the figure goes, bare');

  // The clause that caused the attribution leak is gone. It was written to
  // constrain how a figure was asserted; read as copy direction it says
  // attribute this in the copy.
  assert.ok(!/that source's claim/.test(block), 'no instruction to attribute');
  // What still needs saying without names.
  assert.match(block, /do NOT combine two of them\s*\n?\s*into a single figure/);

  // THE FRAMING IS ATTRIBUTION, NOT TRUTH. There is no validator possible: the
  // raw reference text is capped at 6000 chars per source, used once for the
  // enrich call, and never persisted — so by draft time there is nothing left to
  // check a figure against. Calling these "verbatim" would assert a guarantee
  // nothing in the system provides, on the one output class where being wrong is
  // a false factual claim rather than a weak headline.
  assert.match(block, /REPORTED, not verified/);
  assert.ok(!/verbatim/i.test(block), 'never claims verbatim — nothing checked it');
  assert.match(block, /^- 38% faster onboarding$/m, 'a sourceless figure still lists, without a dangling dash');

  // The two prohibitions earn their lines from the measured failure: with no
  // figures available the drafter invented "in 60 seconds" from a brief that
  // said "about a minute". Handing it real ones risks sharpening, not ignoring.
  assert.match(block, /Do NOT invent a figure/);
  assert.match(block, /do NOT round\s*\n?\s*or sharpen one of these/);

  // Capped, and the cap is not silent.
  const many = Array.from({ length: MAX_REFERENCE_STATS + 5 }, (_, i) => ({ text: `stat ${i}`, source: 's' }));
  const rows = referenceStatsBlock(many).filter((l) => l.startsWith('- '));
  assert.strictEqual(rows.length, MAX_REFERENCE_STATS);
});

test('parseDoc recovers reference STATS from the doc, and never key messages', () => {
  const { parseDoc } = require('../src/destinations/googleDocs');

  function makeDoc(paras) {
    let idx = 1;
    return { body: { content: paras.map((para) => {
      const raw = (para.text || '') + '\n';
      const startIndex = idx; const endIndex = idx + raw.length; idx = endIndex;
      return { startIndex, endIndex, paragraph: {
        paragraphStyle: para.style ? { namedStyleType: para.style } : {},
        elements: [{ textRun: { content: raw, textStyle: { bold: !!para.bold, italic: !!para.italic } } }],
      } };
    }) } };
  }

  // The layout appendBody emits: a From: line per source, then labelled runs.
  const doc = makeDoc([
    { text: 'Campaign Summary', style: 'HEADING_2' },
    { text: 'the summary', italic: true },
    { text: 'Writer Direction', style: 'HEADING_2' },
    { text: 'the direction', italic: true },
    { text: 'Reference Insights', style: 'HEADING_2' },
    { text: 'From: Ops Benchmark 2026 (pdf)', italic: true },
    { text: 'Stats:', italic: true },
    { text: '4 hours saved per week' },
    { text: '38% faster onboarding' },
    { text: 'Key messages:', italic: true },
    { text: 'The fastest way to ship briefs' },
    { text: '' },
    { text: 'From: competitor.example (external)', italic: true },
    { text: 'Key messages:', italic: true },
    { text: 'Built for teams that move' },
    { text: '' },
    { text: 'Reference Materials', style: 'HEADING_2' },
    { text: 'Ops Benchmark 2026' },
    { text: 'LinkedIn Single Image Ad', style: 'HEADING_3' },
    { text: 'Headline [50]', bold: true },
    { text: '' },
  ]);

  const { summary, writerPrompt, assets, referenceStats, enrichedFromReferences } = parseDoc(doc);

  // The section's presence is the signal that summary/writerPrompt were written
  // from linked material — which is what briefBlock's conditional turns on.
  assert.strictEqual(enrichedFromReferences, true);
  assert.deepStrictEqual(referenceStats, [
    { text: '4 hours saved per week', source: 'Ops Benchmark 2026' },
    { text: '38% faster onboarding', source: 'Ops Benchmark 2026' },
  ]);

  // KEY MESSAGES ARE DELIBERATELY NOT COLLECTED. A source's positioning at
  // headline length, handed to a model whose job is to write a headline — and
  // for the competitor row above, that is the competitor's own copy. The enrich
  // pass already made its considered extract into the writer direction's
  // "Competitive Framing:" line; this would be the uncontrolled one beside it.
  const flat = JSON.stringify(referenceStats);
  assert.ok(!flat.includes('Built for teams that move'), "a competitor's positioning stays out of the prompt");
  assert.ok(!flat.includes('fastest way to ship briefs'));

  // And the section leaks into nothing else: the field scan and the two campaign
  // values are exactly what they were.
  assert.strictEqual(summary, 'the summary');
  assert.strictEqual(writerPrompt, 'the direction');
  assert.strictEqual(assets.length, 1);
  assert.deepStrictEqual(assets[0].fields.map((f) => f.fieldName), ['Headline']);

  // A doc with no such section: empty, false, and every prompt below unmoved.
  const plain = parseDoc(makeDoc([
    { text: 'Campaign Summary', style: 'HEADING_2' },
    { text: 'the summary', italic: true },
    { text: 'LinkedIn Single Image Ad', style: 'HEADING_3' },
    { text: 'Headline [50]', bold: true },
    { text: '' },
  ]));
  assert.deepStrictEqual(plain.referenceStats, []);
  assert.strictEqual(plain.enrichedFromReferences, false);
});

test('an absent brief changes nothing, and a long one is tail-cut and said out loud', () => {
  const { briefBlock, MAX_BRIEF_CHARS } = require('../src/services/gemini');

  // ABSENT IS THE DEGRADATION, and it is total: a pre-migration project row, a
  // doc with no project row, no tenant, or an unmigrated database all land here.
  // No lines means the prompt is what it was before the column existed.
  for (const empty of ['', '   ', null, undefined]) {
    assert.deepStrictEqual(briefBlock(empty), [], `${JSON.stringify(empty)} emits nothing`);
  }

  // Under the cap: verbatim, no notice.
  const short = briefBlock('a'.repeat(MAX_BRIEF_CHARS - 1)).join('\n');
  assert.ok(!/cut for length/.test(short), 'no truncation notice when nothing was cut');

  // Over the cap: THE HEAD IS KEPT. A brief front-loads what the campaign is;
  // cutting the middle would splice two halves into a sentence nobody wrote.
  const raw = 'HEAD-'.repeat(4) + 'x'.repeat(MAX_BRIEF_CHARS) + 'TAIL-TAIL';
  const long = briefBlock(raw).join('\n');
  assert.ok(long.includes('HEAD-HEAD-HEAD-HEAD-'), 'the opening survives');
  assert.ok(!long.includes('TAIL-TAIL'), 'the tail is what goes');

  // AND THE MODEL IS TOLD. A severed brief that stops mid-sentence otherwise
  // reads as the end of the ask, and a truncated thought gets treated as the
  // complete one.
  assert.match(long, /cut for length/);
  assert.match(long, /characters not shown/);
  assert.match(long, /Do NOT treat the last line above as the end of the ask/);

  // The cap is applied at PROMPT-BUILD time, never on write — projects.brief_raw
  // keeps whatever was sent, so raising it later is a code change and not data
  // that was already discarded.
  const pipe = fs.readFileSync(path.join(__dirname, '..', 'src', 'core', 'pipeline.js'), 'utf8');
  assert.match(pipe, /brief_raw: spec\.brief \|\| null/, 'stored whole');
  assert.ok(!/slice\(0, *MAX_BRIEF|substring\(0, *MAX_BRIEF/.test(pipe), 'not truncated on write');
});

test('the brief is read from the project row and threaded to every draft call', () => {
  const pipe = fs.readFileSync(path.join(__dirname, '..', 'src', 'core', 'pipeline.js'), 'utf8');
  const gd = fs.readFileSync(path.join(__dirname, '..', 'src', 'destinations', 'googleDocs.js'), 'utf8');
  const gem = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');

  // Read through the lookup this path ALREADY makes for the template half, so
  // this is a field on an existing query rather than a new query.
  assert.match(pipe, /const project = await getProjectByAnyDocId\(tenantId, docId\)/);
  assert.match(pipe, /brief = \(project && project\.brief_raw\) \|\| null/);
  // Every failure is the same failure: no brief, and a prompt identical to before.
  assert.match(pipe, /brief lookup failed — drafting without it/);
  assert.match(pipe, /generateDraft\(\s*docId, direction, clients, voiceGuide, lookupDirection, scopedFields, append, brief\s*\)/);

  // Threaded to ALL THREE gemini call sites inside generateDraft — scoped to
  // generateDraft, because createDocument has had its own `brief` parameter
  // since long before this and a file-wide count silently included it.
  //
  //   1. generateAssetDrafts   — the whole-doc batch
  //   2. generateFieldDraft    — the scoped single-field draft
  //   3. enforceVariationCeiling's `regen` context, which passes the brief on to
  //      generateFieldDraft for the insert/append path's corrective rewrite. A
  //      rewritten variation must not be the one field in the asset drafted
  //      without the campaign's own words.
  const draftFn = gd.slice(gd.indexOf('async function generateDraft(id, direction'));
  assert.strictEqual(
    (draftFn.match(/^\s+brief,$/gm) || []).length,
    3,
    'batch, single-field, and the variation-ceiling rewrite'
  );
  assert.match(draftFn, /generateAssetDrafts\(\{\s*\n\s*assetType: a\.assetType,\s*\n\s*brief,/);
  // …and to the batch RESCUE, or a field that fell out of a failed batch would be
  // the one field in the asset drafted without the campaign's own words.
  const rescue = gem.slice(gem.indexOf('async function generateAssetDrafts'), gem.indexOf('// --- Conceptual variations'));
  assert.match(rescue, /copy = await generateFieldDraft\(\{\s*\n\s*assetType,\s*\n(\s*\/\/.*\n)*\s*brief,/);
});

// A PARSE FAILURE WITH NO SAMPLE IS A BUG YOU CAN ONLY SEE THE SHADOW OF.
// Seen in production: "Unexpected non-whitespace character after JSON at position
// 2" on a 9-field asset. That message gives the SHAPE (a complete two-character
// JSON value with something immediately after it — `{}x`, `[]{…}`, `""…`) and
// nothing about the content, and `text` was declared inside the try, so the raw
// response was not merely unlogged: it was out of scope in the catch.
test('the batch parse failure logs the raw response, greppably and on one line', () => {
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  const fn = sliceBetween(src, 'async function generateAssetDrafts', '// --- Conceptual variations');
  assert.ok(fn.length > 500, 'found generateAssetDrafts');

  // HOISTED. The declarations are above the try, and the assignment inside it.
  // Two of them now: `text` (the raw response, needed in the catch) and
  // `batchFailureKind` (the transport class, needed after it).
  assert.match(
    fn,
    /let text = '';\n(?: {2}\/\/[^\n]*\n)* {2}let batchFailureKind = null;\n {2}try \{\n {4}text = await callGemini\(\{/
  );
  assert.ok(!/const text = await callGemini/.test(fn), 'no block-scoped redeclaration survives');

  // A token EMITTED from exactly one place, so `grep BATCH_PARSE_FAIL` over a log
  // window counts occurrences exactly — nothing in this system persists or counts
  // the event. Comments stripped first: the comment beside it names the token
  // twice explaining why it is unique, and counting that would be counting the
  // documentation rather than the emitter.
  const code = src.split('\n').filter((l) => !/^\s*\/\//.test(l)).join('\n');
  assert.strictEqual((code.match(/BATCH_PARSE_FAIL/g) || []).length, 1, 'emitted from one place');
  const log = fn.match(/console\.warn\(\s*`\[gemini\] BATCH_PARSE_FAIL[\s\S]*?\);/)[0];
  for (const key of ['asset=', 'fields=', 'err=', 'len=', 'raw=']) {
    assert.ok(log.includes(key), `the line carries ${key}`);
  }
  // fields is the COST: every field falls through to a sequential single-field
  // rescue, so fields=9 is nine extra calls.
  assert.match(log, /fields=\$\{fields\.length\}/);
  // Every free-text value is JSON.stringify'd, which is what keeps the record on
  // one line — a raw multi-line dump is unusable where concurrent requests
  // interleave, and would break the grep this exists for.
  assert.match(log, /asset=\$\{JSON\.stringify\(assetType\)\}/);
  assert.match(log, /raw=\$\{JSON\.stringify\(sampleForLog\(text\)\)\}/);
});

// THE BATCH RESCUE NOW SEES THE SET IT BELONGS TO. It never did: the batch
// writes every field of an asset in one call so they can reference each other,
// and the fallback redrafted a field in ignorance of all of them. On a total
// parse failure that turned a nine-field email into nine independent lines with
// an identical fieldCount and an identical completion card.
test('the batch rescue is given siblings, from finished fields AND unreached batch values', () => {
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  const fn = src.slice(src.indexOf('async function generateAssetDrafts'), src.indexOf('// --- Conceptual variations'));

  // It is PASSED. The whole gap was one absent key.
  const call = fn.match(/copy = await generateFieldDraft\(\{[\s\S]*?\}\);/)[0];
  assert.match(call, /\n\s*siblings,\n/, 'the rescue receives siblings');
  // Still no currentCopy — this is a first draft, not a revision, and
  // currentCopyBlock's rule is that a first draft must not be told it has one.
  assert.ok(!/currentCopy/.test(call.replace(/^\s*\/\/.*$/gm, '')), 'no currentCopy on a first draft');

  // BUILT INSIDE THE LOOP. The two call sites this copies (googleDocs scoped
  // redraft, pipeline template regenerate) build once and filter self per
  // iteration, because they read copy that already exists in the document. This
  // is a FIRST draft — copy accumulates as the loop runs — so a list built once
  // would hand every field the same empty set.
  assert.ok(fn.indexOf('for (const f of fields)') < fn.indexOf('const siblings = fields'),
    'siblings is built per field, inside the loop');

  // TWO SOURCES, and the second is the one that matters for the common case: a
  // single field missing or over-limit inside an otherwise-good batch is
  // redrafted while its siblings sit in byKey.
  assert.match(fn, /const finished = new Map\(out\.map\(\(d\) => \[d\.fieldName, d\.copy\]\)\)/);
  assert.match(fn, /finished\.has\(s\.fieldName\)/);
  assert.match(fn, /cleanDraft\(byKey\.get\(s\.fieldName\.trim\(\)\.toLowerCase\(\)\) \|\| ''\)/);

  // Same shape as the other two call sites: self excluded, empties dropped.
  assert.match(fn, /\.filter\(\(s\) => s\.fieldName !== f\.fieldName\)/);
  assert.match(fn, /\.filter\(\(s\) => s\.copy\)/);
});

// siblingContextBlock is what turns that list into prompt text, and its contract
// is what makes an empty list safe — asserted here because the rescue now relies
// on it for field 1 of a failed batch, which has no siblings at all.
test('siblingContextBlock emits nothing for an empty or all-blank list', () => {
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  // eslint-disable-next-line no-eval
  const siblingContextBlock = eval('(' + src.slice(
    src.indexOf('function siblingContextBlock'), src.indexOf('// The field\'s CURRENT copy')
  ).trim() + ')');

  assert.strictEqual(siblingContextBlock([]), '', 'field 1 of a failed batch has none');
  assert.strictEqual(siblingContextBlock(undefined), '');
  assert.strictEqual(siblingContextBlock([{ fieldName: 'A', copy: '   ' }]), '', 'blank copy is not context');
  const one = siblingContextBlock([{ fieldName: 'Headline (Offer 1)', copy: 'Ship copy in a minute' }]);
  assert.match(one, /- Headline \(Offer 1\): Ship copy in a minute/);
  // Context only — the model must not rewrite or emit them.
  assert.match(one, /do NOT rewrite or output them/);
});

test('sampleForLog bounds the sample from BOTH ends and reports the true length separately', () => {
  const { sampleForLog } = require('../src/services/gemini');

  // Short responses pass through whole — the shape that produced the real
  // failure is only a few characters long.
  assert.strictEqual(sampleForLog('{}x'), '{}x');
  assert.strictEqual(sampleForLog(''), '');
  assert.strictEqual(sampleForLog(null), '', 'a failed call leaves text empty, not null-ish garbage');
  assert.strictEqual(sampleForLog(undefined), '');

  // HEAD AND TAIL, because the two failure shapes live at opposite ends: a
  // "position N" error is decided in the first characters, and "Unexpected end of
  // JSON input" means truncation, which only the tail shows.
  const long = 'H'.repeat(1000) + 'M'.repeat(2000) + 'T'.repeat(400);
  const s = sampleForLog(long);
  assert.ok(s.startsWith('H'.repeat(200)), 'keeps the head');
  assert.ok(s.endsWith('T'.repeat(200)), 'keeps the tail');
  assert.ok(s.length < long.length, 'and is bounded');
  // The elision says how much is missing, so a bounded sample never reads as a
  // short response — and the log line carries len= separately besides.
  assert.match(s, /…\[2000 more\]…/);
});

// THE FLOOR REACHES A CHARACTER FIELD'S PROMPT. It never did: lengthClause read
// charMin only on the words branch, and the batch prompt's per-field line made
// the same split independently. A tenant set Graphic Headline to 40-60, the doc
// rendered [40-60], parseDoc recovered charMin 40, and the model was told
// "Character limit: 60" — then handed a sentence ending "even a few characters
// short", which argues DOWN. The draft came back at 32.
test('lengthClause states the floor on a character field, and drops the go-short nudge', () => {
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  // lengthClause is not exported (four internal callers, no public surface), so it
  // is lifted out of the source as an expression. A bare eval of a function
  // DECLARATION does not bind in a strict-mode arrow scope — hence the parens.
  // eslint-disable-next-line no-eval
  const lengthClause = eval('(' + src.slice(src.indexOf('function lengthClause'), src.indexOf('function countWords')).trim() + ')');

  const floored = lengthClause(60, 'text', 40);
  assert.match(floored, /40-60 characters/, 'the range, in characters');
  assert.match(floored, /at least 40/, 'the floor stated as a floor');
  assert.match(floored, /never more than 60/, 'and the ceiling still stated');
  // THE NUDGE MUST NOT SURVIVE BESIDE A FLOOR. "finish it, even a few characters
  // short" is sound advice against a bare ceiling and argues against the floor it
  // would sit next to.
  assert.ok(!/even a few characters short/.test(floored), 'no go-short nudge when there is a floor');
  assert.match(floored, /do not stop short of 40 to be safe/, 'it says the opposite instead');

  // No floor → byte-identical to before. Most seeded character fields are here.
  assert.strictEqual(
    lengthClause(60, 'text', 0),
    'Character limit: 60. Stay within this limit — write a COMPLETE, self-contained thought ' +
    'and finish it, even a few characters short; never run up to the limit and get cut off mid-sentence.'
  );
  // Word fields unchanged.
  assert.match(lengthClause(120, 'words', 50), /^Length: 50-120 words\. This is a WORD count/);
  // No ceiling → no clause at all, floor or not: char_max 0 is the no-limit
  // sentinel and a lone floor is not a length spec.
  assert.strictEqual(lengthClause(0, 'text', 40), null);
  // An impossible range is not asserted — min >= max falls back to the ceiling.
  assert.ok(!/BOTH ends/.test(lengthClause(60, 'text', 60)));
  assert.ok(!/BOTH ends/.test(lengthClause(60, 'text', 99)));
});

test('the batch prompt states the floor too — the same omission had to be fixed twice', () => {
  const src = fs.readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  const block = src.slice(src.indexOf('const fieldLines = fields'), src.indexOf('const guidance = fieldGuidanceFor'));
  assert.ok(block.length > 200, 'found the per-field bullet builder');

  // It composes its own clause rather than calling lengthClause (it is a terse
  // bullet, not a paragraph), which is exactly why the floor went missing here
  // as well. A floor honoured in one draft path and not the other means a field
  // obeys its range only when redrafted alone.
  assert.match(block, /\$\{floor\}-\$\{ceiling\} characters — at least \$\{floor\}, never more than \$\{ceiling\}/);
  assert.match(block, /character limit \$\{ceiling\} — stay within this limit/, 'the no-floor form survives');
  // Same guards as lengthClause: no ceiling → no range; min >= max → no range.
  assert.match(block, /Number\(f\.charMin\) > 0 && ceiling && Number\(f\.charMin\) < ceiling/);
  // And the word branch still reads the floor it always read.
  assert.match(block, /\$\{floor \? `\$\{floor\}-` : 'up to '\}\$\{ceiling\} WORDS/);
});

// WHAT THIS ACTUALLY CHANGES, counted rather than assumed. The floor was NOT a
// tenant-only affair: the seed ships 19 character fields with one, so this alters
// the prompt for every tenant on day one, not just for anyone who has opted in
// through Settings. Asserted so the blast radius is a number in the repo rather
// than a memory.
test('per-field guidance survives the WHOLE copy-doc draft path, not just the builder', async () => {
  // THE DROP THIS PINS. parseDoc recovered each field's italic line into `notes`
  // and generateDraft's assetTargets rebuilt the field without it, so the gemini
  // composer got undefined on every copy-doc draft — no tenant spec_note, no
  // seeded note, nothing; only the name-keyed built-ins ever fired.
  //
  // A STRUCTURAL TEST WOULD NOT HAVE CAUGHT IT and neither did the A/B, because
  // the A/B called generateAssetDrafts DIRECTLY with notes. The measurement was
  // clean and the wire between it and production was not. So this drives the real
  // entry point with a stubbed transport and reads the prompt.
  const gd = require('../src/destinations/googleDocs');
  const cfg = require('../src/config');
  const hadKey = cfg.GEMINI_API_KEY;
  const realFetch = global.fetch;
  let prompt = null;
  cfg.GEMINI_API_KEY = 'test-key';
  global.fetch = async (_u, o) => {
    prompt = JSON.parse(o.body).contents[0].parts[0].text;
    return { ok: true, json: async () => ({ candidates: [{ content: { parts: [{ text: '{"Subject Line 1":"x"}' }] } }] }) };
  };

  try {
    let idx = 1;
    const paras = [
      { text: 'Campaign Summary', style: 'HEADING_2' }, { text: 'S', italic: true },
      { text: 'Writer Direction', style: 'HEADING_2' }, { text: 'W', italic: true },
      { text: 'Demand Gen Nurture Email', style: 'HEADING_3' },
      { text: 'Subject Line 1 [130]', bold: true },
      // As fieldHint composes it: the seeded note, then the reader-only tier line.
      { text: 'Mobile inboxes cut around 40 characters — front-load the first 40. (Litmus) House default — set your own in Settings.', italic: true },
      { text: '' },
    ];
    const content = paras.map((p) => {
      const raw = (p.text || '') + '\n';
      const start = idx; idx += raw.length;
      return { startIndex: start, endIndex: idx, paragraph: {
        paragraphStyle: p.style ? { namedStyleType: p.style } : {},
        elements: [{ textRun: { content: raw, textStyle: { bold: !!p.bold, italic: !!p.italic } } }],
      } };
    });
    const clients = { docs: { documents: {
      get: async () => ({ data: { body: { content } } }),
      batchUpdate: async () => ({ data: {} }),
    } } };

    await gd.generateDraft('doc', null, clients, null, null, null, false, 'brief');

    assert.ok(prompt, 'a prompt was built');
    assert.match(prompt, /front-load the first 40/, 'the seeded note reaches the drafter');
    assert.match(prompt, /guidance: Mobile inboxes cut around 40 characters/,
      'and arrives as that field\'s guidance, not loose text');
    // AND THE READER-ONLY SENTENCE DOES NOT. Stripped at recovery, so restoring
    // notes cannot ship a Settings pointer as creative direction.
    assert.ok(!/set your own in Settings/.test(prompt), 'the Settings pointer stays out');
  } finally {
    global.fetch = realFetch;
    cfg.GEMINI_API_KEY = hadKey;
  }
});

test('one strip, two rules: reader-facing sentences out, writing guidance in', () => {
  const { stripReaderOnlyLines, NOT_A_HARD_LIMIT, HOUSE_DEFAULT_LINE } = require('../src/destinations/googleDocs');

  // THE TEST IS THE ONE ALREADY IN THE CODE: does this sentence address the
  // READER OF THE DOC or the WRITER OF THE COPY? The Settings pointer fails it.
  // So does "not a hard limit, adjust" — advice to a human deciding whether to
  // respect a number, which read as writing guidance CONTRADICTS the ceiling
  // stated in the same prompt bullet, on the one constraint that always wins.
  assert.strictEqual(stripReaderOnlyLines(`Recommended by Meta. ${NOT_A_HARD_LIMIT}`), '');
  assert.strictEqual(stripReaderOnlyLines(`Keep it short. ${HOUSE_DEFAULT_LINE}`), 'Keep it short.');

  // THE FINDING SURVIVES — it is writing guidance, unlike the attribution. The
  // source NAME goes for the same reason the reference-stats block withholds one:
  // a name in a drafting prompt is an object the model can reach for.
  assert.strictEqual(
    stripReaderOnlyLines('One of two body blocks. Recommended by Constant Contact (2.1M customers, small-business campaigns). Longer bodies click less.'),
    'One of two body blocks. Longer bodies click less.'
  );

  // ENFORCED IS LEFT ALONE. Redundant with the limit clause beside it, but it is
  // the one tier line that AGREES with the prompt. Logged, not stripped.
  assert.strictEqual(
    stripReaderOnlyLines('Platform limit (LinkedIn). Stay within this count.'),
    'Platform limit (LinkedIn). Stay within this count.'
  );
  // And real craft is untouched.
  assert.match(stripReaderOnlyLines('Mobile inboxes cut around 40 characters — front-load the first 40. (Litmus)'), /front-load/);
});

test('briefFacts: a date or time gates the note; a venue does NOT', () => {
  const { briefStatesDateTime, briefStatesLocation, briefFacts, MISSING_DATETIME_NOTE } = require('../src/utils/briefFacts');

  for (const b of [
    'Webinar on Thursday August 24 at 12 PM PT.',
    'The session is on Thursday.',
    'Doors at 6:30.',
    'Starts at 9am.',
    'Run it 24/08.',
    'It is tomorrow.',
  ]) assert.strictEqual(briefStatesDateTime(b), true, `should find a date/time in: ${b}`);

  for (const b of [
    'Reminder email for our product launch webinar. They already registered.',
    'Quillio turns a brief into a copy doc in about a minute.',
    'Q3 launch push for mid-size B2B teams.',   // Q3 and B2B are not dates
    '', null, undefined,
  ]) assert.strictEqual(briefStatesDateTime(b), false, `should find nothing in: ${JSON.stringify(b)}`);

  // THE OR WAS A HOLE, AND THIS IS THE CASE THAT PROVED IT. `briefStatesDateTime`
  // used to be `datetime || location`, reasoning that the field is called
  // "Date / Location Line" so a venue is something for it. True about the FIELD,
  // false about the FAILURE: a venue does not stop the model inventing a time.
  // The note's own trigger suppressed the note on exactly the case it exists for.
  for (const b of ['Reminder. Join us on Zoom.', 'Venue: the Grand Ballroom', 'in Room 210']) {
    assert.strictEqual(briefStatesLocation(b), true, `a venue: ${b}`);
    assert.strictEqual(briefStatesDateTime(b), false, `a venue is NOT a date/time: ${b}`);
  }

  // THE VENUE NOUN IS CASE-FLEXIBLE. The pattern carries no /i — [A-Z] requires a
  // proper noun — so a lowercase-only alternation matched "moscone center" and
  // never "Moscone Center", which is how a venue is actually written.
  assert.strictEqual(briefFacts('at the Moscone Center').location, true);
  assert.strictEqual(briefFacts('at the Moscone Convention Center').location, true);

  // `matches` carries WHAT fired, not just whether.
  assert.ok(briefFacts('Thursday at 12 PM').matches.length >= 2);

  // THE NOTE MOVED WITH THE TRIGGER. On this trigger a venue-only brief now GETS
  // the note, so a sentence claiming the venue is missing would be false.
  assert.ok(!/venue/i.test(MISSING_DATETIME_NOTE), 'no longer claims the venue is missing');
  assert.match(MISSING_DATETIME_NOTE, /date or time/);

  // Still one sentence for two readers, still no imperative, still no fault, and
  // still no fact-shaped example.
  assert.strictEqual(MISSING_DATETIME_NOTE.split(/(?<=[.!?])\s/).length, 1, 'one sentence');
  assert.ok(!/\badd\b|\bfill\b|\benter\b|\bwrite\b/i.test(MISSING_DATETIME_NOTE));
  assert.ok(!/missing|error|fail|should have|required/i.test(MISSING_DATETIME_NOTE));
  assert.ok(!/\d/.test(MISSING_DATETIME_NOTE), 'no digits at all');
  assert.ok(!/(?:mon|tues|wednes|thurs|fri|satur|sun)day/i.test(MISSING_DATETIME_NOTE));
});

test('a venue-only brief gets the note — the case the OR suppressed, end to end', async () => {
  // WHY THIS IS A TEST AND NOT AN A/B ARM. The arm existed to show the OR fix
  // changed BEHAVIOUR and not just the trigger. That chain has three links:
  //
  //   (a) briefStatesDateTime('…Join us on Zoom.') === false
  //   (b) generateDoc attaches the note when that is false
  //   (c) the note attached improves the field
  //
  // (a) and (b) are deterministic code and are asserted here. (c) is model
  // behaviour and was measured at n=15 across three wordings in the silent arm —
  // 4/35 on the shipped wording with 5 of 5 clean placeholders on the field. The
  // venue-only brief differs from the silent one only by a sentence naming a
  // platform, which is not a plausible moderator of how a note about the DATE
  // behaves. Re-measuring (c) with that brief would spend 45 calls confirming a
  // link already established.
  //
  // WHAT THE ARM WOULD STILL ANSWER, and it is a different question: with a venue
  // available and no time, does the field render "Live on Zoom" (correct — it is a
  // Date / LOCATION line and the venue was supplied) or "Live on Zoom at 2 PM"
  // (invention)? Worth running when convenient. It does not gate anything.
  const { briefStatesDateTime, MISSING_DATETIME_NOTE } = require('../src/utils/briefFacts');
  const pipeline = require('../src/core/pipeline');

  const VENUE_ONLY = 'Reminder for our launch webinar. Join us on Zoom. They already registered.';

  // (a) The trigger. Under the OR this returned TRUE and the note was skipped.
  assert.strictEqual(briefStatesDateTime(VENUE_ONLY), false, 'a venue is not a date or time');

  // (b) The attachment. Driven through tenantAssetsToSpecs so the spec objects are
  // the ones generateDoc actually decorates, rather than a hand-built shape.
  const rows = [{
    id: 1, name: 'Event Reminder Email', group: 'Email', sort_order: 1, asset_direction: '',
    fields: [
      { field_name: 'Subject Line 1', char_min: 0, char_max: 130, field_type: 'text', sort_order: 1, fact_kind: null },
      { field_name: 'Date / Location Line', char_min: 0, char_max: 80, field_type: 'text', sort_order: 2, fact_kind: 'datetime' },
    ],
  }];
  const specs = pipeline.tenantAssetsToSpecs(rows, ['Event Reminder Email']);
  const dateField = specs[0].fields.find((f) => f.fieldName === 'Date / Location Line');
  assert.strictEqual(dateField.factKind, 'datetime', 'fact_kind survives into the spec');

  // The attach step, exactly as generateDoc performs it.
  for (const group of specs) {
    for (const field of group.fields) {
      if (field.factKind !== 'datetime') continue;
      field.specNote = [field.specNote, MISSING_DATETIME_NOTE].filter(Boolean).join(' ');
    }
  }
  assert.match(dateField.specNote, /does not state a date or time/, 'the note attaches on a venue-only brief');
  // And it does NOT land on the generative field beside it.
  assert.ok(!specs[0].fields.find((f) => f.fieldName === 'Subject Line 1').specNote);
});

test('two fact kinds, and only datetime is wired to anything', () => {
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const byKind = {};
  for (const a of DEFAULT_ASSETS) {
    for (const f of a.fields) {
      if (f.fact_kind) (byKind[f.fact_kind] = byKind[f.fact_kind] || []).push(f.field_name);
    }
  }
  // A track label carries a ROOM and a directional label carries a PLACE. The
  // note `datetime` gates says "The brief does not state a date or time", which
  // on those two is a sentence about the wrong fact.
  assert.deepStrictEqual(byKind.datetime.sort(), ['Date / Location Line', 'Date / Location Line']);
  assert.deepStrictEqual(byKind.location.sort(), ['Location Label', 'Track / Room Label']);

  // THE SEED AND THE CORRECTIVE MIGRATION MUST AGREE, or a new tenant installs
  // the kind the migration just moved every existing tenant off.
  const m = require('../scripts/migrateFixLocationFactKind');
  assert.deepStrictEqual(m.FIELDS.slice().sort(), byKind.location.slice().sort());
  assert.strictEqual(m.TO, 'location');
  assert.strictEqual(m.FROM, 'datetime');

  // NOTHING FIRES ON 'location'. Every consumer gates on the explicit string, not
  // on truthiness, so adding a second kind switches nothing on.
  const pipeline = fs.readFileSync(require.resolve('../src/core/pipeline'), 'utf8');
  assert.match(pipeline, /field\.factKind !== 'datetime'/);
});

test('the note reaches ONLY a datetime field, and ONLY when the brief is silent', () => {
  const src = fs.readFileSync(require.resolve('../src/core/pipeline'), 'utf8');

  // Attached in generateDoc, the one place holding both the field list and the
  // brief. Guarded on factKind, so it cannot land on a generative field.
  assert.match(src, /if \(field\.factKind !== 'datetime'\) continue;/);
  assert.match(src, /const briefHasDateTime = briefStatesDateTime\(spec\.brief\);/);
  assert.match(src, /if \(!briefHasDateTime\) \{/);

  // ABSENT WHEN THE BRIEF SUPPLIES IT — not a different sentence. The field
  // already works in that case (0/30 invented, 21/30 transcribed), and a note in
  // the presence of the fact is instruction the model does not need. Every rule
  // this system adds costs variance; one that changes nothing costs it for free.
  // Asserted on the NOTE, not on the flag: the flag legitimately appears in a
  // ternary in the log line. What must not exist is a second sentence for the
  // supplied case — so the note constant is referenced exactly once, inside the
  // !briefHasDateTime branch, and there is no sibling constant.
  assert.strictEqual((src.match(/MISSING_DATETIME_NOTE/g) || []).length, 2,
    'imported once, used once — no second wording');
  const block = src.slice(src.indexOf('if (!briefHasDateTime) {'), src.indexOf('[pipeline] asset specs source'));
  assert.ok(block.includes('MISSING_DATETIME_NOTE'), 'the only use is in the silent branch');

  // It JOINS spec_note rather than replacing it — a tenant's own note survives.
  assert.match(src, /field\.specNote = \[field\.specNote, MISSING_DATETIME_NOTE\]\.filter\(Boolean\)\.join\(' '\)/);
});

test('the migration ships the column, the values and the field together', () => {
  const m = require('../scripts/migrateAddReminderDateLine');

  // ADDITIVE AND NULLABLE, no default. NULL means "this field generates rather
  // than transcribes", which is every field but four — a NOT NULL DEFAULT would
  // make the absence unrepresentable.
  assert.match(m.COLUMN_SQL, /ADD COLUMN IF NOT EXISTS/, 'idempotent');
  assert.ok(!/NOT NULL|DEFAULT/.test(m.COLUMN_SQL), 'nullable, no default');

  // The seed and the migration must mark the SAME fields — a row the seed flags
  // and the migration misses is a tenant whose note never appears.
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const seeded = new Set();
  for (const a of DEFAULT_ASSETS) for (const f of a.fields) if (f.fact_kind) seeded.add(f.field_name);
  assert.deepStrictEqual([...seeded].sort(), m.FACT_KIND_FIELDS.map(([n]) => n).sort());

  // ONE VALUE TODAY. The other candidate classes are enumerated in ROADMAP.md and
  // not started; this column commits to none of them.
  assert.deepStrictEqual([...new Set(m.FACT_KIND_FIELDS.map(([, k]) => k))], ['datetime']);

  // And the three ship together, because the field alone is a regression for
  // every tenant and the column alone leaves the reminder with nowhere to put a
  // time it was given.
  const src = fs.readFileSync(require.resolve('../scripts/migrateAddReminderDateLine'), 'utf8');
  assert.match(src, /THREE THINGS IN ONE TRANSACTION/);
  assert.match(src, /await client\.query\('BEGIN'\)/);
});

test('a reminder has somewhere to put the time, named as the invitation names it', () => {
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const FIELD = 'Date / Location Line';
  const of = (n) => DEFAULT_ASSETS.find((a) => a.name === n);
  const names = (n) => (of(n).fields || []).map((f) => f.field_name);

  // THE SEED SHIPPED WITHOUT IT. Event Reminder Email's field list was
  // byte-identical to Event Follow-Up / Recap Email's — and the follow-up needs
  // no date, because the event is over, so the shared shape was the follow-up's.
  // With nowhere to say when the event is, and an asset_direction demanding
  // urgency, drafts invented arrival times that disagreed by 24 hours. A
  // reminder carrying a wrong time makes the READER miss the event, which is the
  // only failure in this system that harms the reader rather than the client.
  assert.ok(names('Event Reminder Email').includes(FIELD), 'the reminder can carry a time');

  // NAMED EXACTLY AS THE INVITATION NAMES IT. The library is matched by name in
  // several places and a near-duplicate is what a name match gets wrong — so a
  // reminder and an invitation must not disagree about what the field is called.
  assert.ok(names('Event Invitation Email').includes(FIELD));
  const band = (n) => (of(n).fields || []).find((f) => f.field_name === FIELD);
  assert.strictEqual(band('Event Reminder Email').char_max, band('Event Invitation Email').char_max);
  assert.strictEqual(band('Event Reminder Email').char_min, band('Event Invitation Email').char_min);

  // Placed as the invitation places it: content, then the date line, then the ask.
  const r = names('Event Reminder Email');
  assert.ok(r.indexOf(FIELD) > r.indexOf('Body Copy') && r.indexOf(FIELD) < r.indexOf('CTA Text'));

  // AND THE FOLLOW-UP STILL HAS NONE, deliberately — the event is over. If this
  // ever fails, the copy-paste went the other way.
  assert.ok(!names('Event Follow-Up / Recap Email').includes(FIELD), 'a recap needs no arrival time');
});

test('20 seeded CHARACTER fields already carry a floor — this is not opt-in-only', () => {
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const floored = [];
  let charFields = 0;
  for (const a of DEFAULT_ASSETS) {
    for (const f of a.fields) {
      if ((f.field_type || 'text') === 'words') continue;
      charFields++;
      // The field name is pushed on its own: "Event Follow-Up / Recap Email"
      // contains a slash, so splitting a joined string back apart mis-parses it.
      if (Number(f.char_min) > 0) floored.push({ asset: a.name, field: f.field_name });
    }
  }
  // 167 since Event Reminder Email gained `Date / Location Line` — a reminder
  // needs somewhere to put the time. char_min 0, so the floored count is unmoved.
  assert.strictEqual(charFields, 167, 'character fields in the seed');
  // 20 since migrateFixMetaSpecs gave Meta Single Image Ad / Primary Text the
  // 50 half of Meta's published "50-150 characters" — the first new floor on a
  // paid-social field since floorAB measured what a floor costs in spread.
  assert.strictEqual(floored.length, 20, 'and 20 of them have a floor');
  // The shape of them: every Subhead, every Preheader, the landing-page meta
  // pairs — and now one Primary Text, the only one of the twenty whose floor is a
  // PLATFORM's published number rather than a house convention.
  const names = new Set(floored.map((r) => r.field));
  assert.deepStrictEqual([...names].sort(),
    ['Meta Description', 'Meta Title', 'Preheader', 'Primary Text', 'Subhead']);
  assert.deepStrictEqual(
    floored.filter((r) => r.field === 'Primary Text'),
    [{ asset: 'Meta Single Image Ad', field: 'Primary Text' }],
    'the carousel Primary Text has no floor — Meta states a single 80, not a band'
  );
});

// THE REGRESSION THIS GUARDS. Both draft prompts used to read
// `notes || builtInFieldGuidance(fieldName)`, so a field that carried ANY italic
// line lost its built-in craft rule outright. On the copy doc `notes` is
// fieldHint's composed line — spec_note PLUS the tier sentence — so a spec_note,
// a migration adding one, or a re-tier to enforced/recommended each silently
// deleted the sentence-case rule from every Graphic Headline prompt. It has
// never fired only because all 20 seeded Subhead / Graphic Headline fields are
// house_default with a NULL note, which is a one-column safety margin.
test('fieldGuidanceFor composes the built-in rule with the field note instead of being displaced by it', () => {
  const { fieldGuidanceFor, builtInFieldGuidance } = require('../src/services/gemini');

  // The case that motivated this: a tier line present on Graphic Headline. The
  // sentence-case rule MUST survive it.
  const tier = 'Platform limit (LinkedIn). Stay within this count.';
  const withTier = fieldGuidanceFor('Graphic Headline', tier);
  assert.match(withTier, /sentence case/i, 'the built-in rule survives a tier line');
  assert.ok(withTier.includes(tier), 'and the tier line is still there');

  // Same for Subhead, whose rule is the other one a model gets wrong by default.
  const withNote = fieldGuidanceFor('Subhead', 'Keep it to the date and venue.');
  assert.match(withNote, /supporting line/i, 'the built-in rule survives a spec_note');
  assert.ok(withNote.includes('Keep it to the date and venue.'));

  // ORDER IS THE PRECEDENCE. The field's own note leads, so where the two touch
  // it still reads as the governing instruction — CLAUDE.md's hierarchy is kept
  // by ordering, not by throwing the craft rule away.
  assert.ok(
    withNote.indexOf('Keep it to the date and venue.') < withNote.indexOf('Secondary supporting line'),
    'the field note comes first'
  );

  // ONE line, space-joined: the batch prompt's per-field clause is ';'-separated
  // and cannot carry a newline.
  assert.ok(!/\n/.test(withTier), 'no newline — both call sites emit a single line');

  // NO BEHAVIOUR CHANGE where there is nothing to compose. These three cover
  // every field in the seeded library, which is why this commit is a no-op on
  // today's data.
  assert.strictEqual(fieldGuidanceFor('Graphic Headline', ''), builtInFieldGuidance('Graphic Headline'),
    'note-less built-in field: byte-identical to before');
  assert.strictEqual(fieldGuidanceFor('Intro Text', 'Lead with the outcome.'), 'Lead with the outcome.',
    'note-carrying field with no built-in: byte-identical to before');
  assert.strictEqual(fieldGuidanceFor('Intro Text', ''), '', 'neither → empty, so the caller omits the line');

  // Nullish and whitespace-only notes are the empty case, not a leading space.
  assert.strictEqual(fieldGuidanceFor('Intro Text', null), '');
  assert.strictEqual(fieldGuidanceFor('Intro Text', undefined), '');
  assert.strictEqual(fieldGuidanceFor('Graphic Headline', '   '), builtInFieldGuidance('Graphic Headline'));
});

// The helper only matters if BOTH prompts go through it. A `||` restored at
// either call site brings the bug back for that path alone — the batch drafts
// most copy, the single-field generator drafts every rescue and every regenerate.
test('both draft prompts build their guidance through fieldGuidanceFor', () => {
  const src = require('fs').readFileSync(require.resolve('../src/services/gemini'), 'utf8');
  assert.match(src, /const fieldGuidance = fieldGuidanceFor\(fieldName, notes\)/,
    'generateFieldDraft');
  assert.match(src, /const guidance = fieldGuidanceFor\(f\.fieldName, f\.notes\)/,
    'generateAssetDrafts (the batch)');

  // CODE ONLY. fieldGuidanceFor's own comment quotes the `||` it replaced —
  // naming the bug is the point of that comment — so a raw scan of the file
  // fails on the documentation rather than on a regression. Whole-line comments
  // are dropped first; the file has no block comments (asserted below, because
  // this stripper would not survive one).
  assert.ok(!/^\s*\/\*/m.test(src), 'no block comments — the line stripper below is sufficient');
  const code = src
    .split('\n')
    .filter((l) => !/^\s*\/\//.test(l))
    .join('\n');
  assert.ok(!/\bnotes \|\| builtInFieldGuidance\b/.test(code), 'no short-circuit survives');
  assert.ok(!/f\.notes \|\| builtInFieldGuidance/.test(code), 'nor in the batch');
});

// Today's seeded library is entirely unaffected — asserted, not assumed, because
// "this is a no-op" is the claim that makes the commit safe to ship on its own.
test('the composed fallback changes no seeded field: none carries both a note and a built-in rule', () => {
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const { builtInFieldGuidance, fieldGuidanceFor } = require('../src/services/gemini');
  const { fieldHint, stripReaderOnlyLines } = require('../src/destinations/googleDocs');

  const both = [];
  let builtIn = 0;
  for (const a of DEFAULT_ASSETS) {
    for (const f of a.fields) {
      if (!builtInFieldGuidance(f.field_name)) continue;
      builtIn++;
      // What parseDoc would recover for this field: fieldHint's composed line
      // PUT THROUGH THE SAME STRIP parseDoc applies, or '' when it renders none.
      // The strip is why this still holds — every one of these 20 fields now
      // carries the house-default sentence in the DOC, and none of it reaches a
      // prompt. Reading fieldHint alone here would assert the wrong thing and
      // would have gone green on a build that shipped "set your own in Settings"
      // to Gemini as 20 fields' entire creative guidance.
      const hint = fieldHint({
        specNote: f.spec_note,
        specType: f.spec_type,
        specSource: f.spec_source || a.spec_source,
      });
      const notes = stripReaderOnlyLines(hint ? hint.text : '');
      if (notes) both.push(`${a.name} / ${f.field_name}`);
      // The composed value equals the old `||` result for every seeded field.
      assert.strictEqual(
        fieldGuidanceFor(f.field_name, notes),
        notes || builtInFieldGuidance(f.field_name),
        `${a.name} / ${f.field_name} drafts identically`
      );
    }
  }
  assert.strictEqual(builtIn, 20, '20 seeded Subhead / Graphic Headline fields');
  assert.deepStrictEqual(both, [], 'none of them renders an italic line, so none changes');
});

test('db/assets exposes seedTenantAssets + getTenantAssets', () => {
  const a = require('../src/db/assets');
  assert.strictEqual(typeof a.seedTenantAssets, 'function');
  assert.strictEqual(typeof a.getTenantAssets, 'function');
});

test('db/assets degrades gracefully with no database', async () => {
  // No DATABASE_URL in the test env → seed no-ops (false), read misses (null).
  const { seedTenantAssets, getTenantAssets } = require('../src/db/assets');
  assert.strictEqual(await seedTenantAssets('T0B8LPRDKHR'), false);
  assert.strictEqual(await getTenantAssets('T0B8LPRDKHR'), null);
});

// === WHAT THE SEED ACTUALLY SENDS ===========================================
//
// These drive the REAL seedTenantAssets against a fake pool and rebuild the rows
// it inserted from the SQL and its parameters. That shape is the point.
//
// `fact_kind` was computed by defaultAssets.js and absent from the INSERT in
// db/assets.js for as long as the column existed, so every tenant seeded in that
// window got NULL and the missing-date-time note never fired for them. The test
// that was supposed to cover it asserted the SEED CONSTANT and the MIGRATION
// CONSTANT marked the same fields — and they did. Both sides of that comparison
// were correct; the statement between them was not, and nothing read it.
//
// So the assertion has to be made against the ROWS, which is the only artefact
// that can disagree with both constants at once.

// A pool whose client records every (sql, params) pair, and which answers the two
// reads seedTenantAssets makes: the idempotency probe (no rows → not yet seeded)
// and the asset_types INSERT ... RETURNING id.
//
// `rejectFactKind` reproduces a database where migrateAddReminderDateLine.js has
// not run: the 12-column statement comes back 42703, exactly as Postgres would
// answer it, and every statement after it in that transaction is refused the way
// a real aborted transaction refuses them.
function fakeSeedPool({ rejectFactKind = false } = {}) {
  const queries = [];
  let nextId = 1;
  let aborted = false;
  const run = async (sql, params) => {
    queries.push({ sql, params });
    if (/^\s*BEGIN/i.test(sql)) { aborted = false; return { rows: [] }; }
    if (/^\s*ROLLBACK/i.test(sql)) { aborted = false; return { rows: [] }; }
    if (aborted) {
      const err = new Error('current transaction is aborted, commands ignored until end of transaction block');
      err.code = '25P02';
      throw err;
    }
    if (rejectFactKind && /INSERT INTO copy_fields/i.test(sql) && /fact_kind/i.test(sql)) {
      aborted = true;
      const err = new Error('column "fact_kind" of relation "copy_fields" does not exist');
      err.code = '42703';
      throw err;
    }
    if (/^\s*SELECT 1 FROM asset_types/i.test(sql)) return { rows: [] };
    if (/INSERT INTO asset_types/i.test(sql)) return { rows: [{ id: nextId++ }] };
    return { rows: [] };
  };
  return { queries, query: run, connect: async () => ({ query: run, release() {} }) };
}

// Run the real seed against a fake pool and return the rows it tried to write.
// db/assets destructures getPool at require time, so the module is evicted and
// re-required inside the patch rather than assigned to.
async function seedIntoFakePool(opts) {
  const db = require('../src/db');
  const realGetPool = db.getPool;
  const assetsPath = require.resolve('../src/db/assets');
  const pool = fakeSeedPool(opts);
  db.getPool = () => pool;
  delete require.cache[assetsPath];
  let seeded;
  try {
    seeded = await require(assetsPath).seedTenantAssets('T_SEED_TEST');
  } finally {
    db.getPool = realGetPool;
    delete require.cache[assetsPath];
  }

  // ONLY THE TRANSACTION THAT COMMITTED. An attempt that was rolled back sent
  // statements too — on the pre-migration path the first one is a copy_fields
  // INSERT naming a column the database does not have — and those rows do not
  // exist afterwards. Counting them would have this report the rejected shape as
  // though it had been written.
  const committed = pool.queries.slice(pool.queries.map((q) => /^\s*BEGIN/i.test(q.sql)).lastIndexOf(true));

  // Rebuild each INSERT as an object: column names come from the statement, values
  // from the parameters it was given. Reading both off the captured query is what
  // makes this a test of the statement rather than of the constants around it.
  const rowsFor = (table) =>
    committed
      .filter((q) => new RegExp(`INSERT INTO ${table}\\b`, 'i').test(q.sql))
      .map((q) => {
        const cols = q.sql.match(/INSERT INTO \w+\s*\(([\s\S]*?)\)/i)[1]
          .split(',')
          .map((c) => c.trim().replace(/^"|"$/g, ''));
        assert.strictEqual(
          cols.length,
          (q.params || []).length,
          `${table}: ${cols.length} columns named but ${(q.params || []).length} parameters passed`
        );
        return Object.fromEntries(cols.map((c, i) => [c, q.params[i]]));
      });

  return { seeded, queries: pool.queries, assetTypes: rowsFor('asset_types'), copyFields: rowsFor('copy_fields') };
}

test('the seed WRITES fact_kind — asserted on the rows, not on the constants', async () => {
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const { seeded, copyFields, assetTypes } = await seedIntoFakePool();

  assert.strictEqual(seeded, true);
  assert.strictEqual(assetTypes.length, DEFAULT_ASSETS.length, 'every asset type inserted');
  assert.strictEqual(
    copyFields.length,
    DEFAULT_ASSETS.reduce((n, a) => n + a.fields.length, 0),
    'every field inserted'
  );

  // The three fields that carry a supplied fact, read back out of what was SENT.
  const sentKinds = new Map();
  for (const row of copyFields) {
    if (row.fact_kind) sentKinds.set(row.field_name, row.fact_kind);
  }
  assert.deepStrictEqual(
    [...sentKinds.entries()].sort(),
    [
      ['Date / Location Line', 'datetime'],
      ['Location Label', 'location'],
      ['Track / Room Label', 'location'],
    ],
    'the fact-carrying fields reach the database with their kind'
  );

  // The one the notice depends on, named explicitly: core/pipeline.js gates the
  // drafter's note on factKind === 'datetime' and utils/briefFacts reads the same
  // rows for the writer-facing notice. A NULL here is silent on both surfaces.
  const dateRows = copyFields.filter((r) => r.field_name === 'Date / Location Line');
  assert.strictEqual(dateRows.length, 2, 'Event Invitation and Event Reminder both have one');
  for (const r of dateRows) assert.strictEqual(r.fact_kind, 'datetime');

  // And every generative field passes NULL rather than omitting the parameter —
  // the absence is the value.
  const generative = copyFields.filter((r) => !sentKinds.has(r.field_name));
  assert.ok(generative.length > 100, 'most fields generate rather than transcribe');
  for (const r of generative) {
    assert.ok('fact_kind' in r, `${r.field_name} names the column`);
    assert.strictEqual(r.fact_kind, null, `${r.field_name} passes NULL`);
  }
});

test('every column the seed computes is named in the INSERT', async () => {
  // THE GENERALISATION, and the reason this block exists rather than one more
  // fact_kind assertion. `fact_kind` was not a special case — it was a value
  // defaultAssets.js computed and the statement did not name, which is a shape
  // any future column can arrive in. Comparing the keys of the seed's own field
  // objects against the columns the statement names catches all of them.
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const { copyFields, assetTypes } = await seedIntoFakePool();

  const fieldCols = new Set(Object.keys(copyFields[0]));
  const seedFieldKeys = new Set();
  for (const a of DEFAULT_ASSETS) for (const f of a.fields) for (const k of Object.keys(f)) seedFieldKeys.add(k);
  const droppedFields = [...seedFieldKeys].filter((k) => !fieldCols.has(k));
  assert.deepStrictEqual(droppedFields, [], 'copy_fields INSERT drops no computed field value');

  // Same question of the asset row. `spec_source` / `spec_version` are asset-level
  // in the seed shape but stored per FIELD, so they are expected on the other
  // statement rather than this one — named here so the exemption is deliberate
  // rather than a hole the assertion happens not to look through.
  const ASSET_KEYS_STORED_ON_FIELDS = new Set(['fields', 'spec_source', 'spec_version']);
  const typeCols = new Set(Object.keys(assetTypes[0]));
  const droppedTypes = Object.keys(DEFAULT_ASSETS[0]).filter(
    (k) => !ASSET_KEYS_STORED_ON_FIELDS.has(k) && !typeCols.has(k)
  );
  assert.deepStrictEqual(droppedTypes, [], 'asset_types INSERT drops no computed asset value');
  for (const k of ASSET_KEYS_STORED_ON_FIELDS) {
    if (k === 'fields') continue;
    assert.ok(fieldCols.has(k), `${k} is stored on the field row`);
  }
});

test('deploy-before-migration: a database without fact_kind still gets a full library', async () => {
  // Railway auto-deploys `main` on merge, so this code runs against a database
  // that has not had scripts/migrateAddReminderDateLine.js run yet. The seed must
  // fall back rather than fail: a silent date note is recoverable by running the
  // migration, a tenant with NO asset library is a first brief that fails on
  // something unrelated.
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const { seeded, copyFields, queries } = await seedIntoFakePool({ rejectFactKind: true });

  assert.strictEqual(seeded, true, 'the seed still reports success');
  assert.strictEqual(
    copyFields.filter((r) => 'fact_kind' in r).length,
    0,
    'the retry drops the column rather than passing it positionally'
  );
  assert.strictEqual(
    copyFields.filter((r) => !('fact_kind' in r)).length,
    DEFAULT_ASSETS.reduce((n, a) => n + a.fields.length, 0),
    'and every field is still written'
  );

  // The aborted transaction is rolled back before the replay, so the retry starts
  // clean. Without this the second attempt runs inside a transaction Postgres has
  // already refused and every statement comes back 25P02.
  const shape = queries.map((q) => q.sql.trim().split(/\s+/).slice(0, 3).join(' '));
  const firstRollback = shape.indexOf('ROLLBACK');
  const lastBegin = shape.lastIndexOf('BEGIN');
  assert.ok(firstRollback > 0, 'the failed attempt rolls back');
  assert.ok(lastBegin > firstRollback, 'and the replay opens its own transaction');
  assert.strictEqual(shape.filter((s) => s === 'COMMIT').length, 1, 'exactly one commit');
});

