// --- Silent failure 2: specReview overwrites tenant divergence ----------------
// commitReview updates copy_fields by asset name + field name with NO tenant
// predicate, so one approval rewrites every tenant's row. distinctValue already
// knew when tenants disagreed — it joins them into "150 | 200" — but a joined
// string says nothing about how many tenants hold each value or which ones, so
// a write that reverted a tenant looked exactly like one that changed nothing.

test('specReview divergence: the breakdown names the value, the count and the tenants', () => {
  const { tenantValueBreakdown } = require('../src/services/specReview');

  // Three tenants on the curated 150, one that has moved to 200.
  const rows = [
    { tenant_id: 'T1', char_max: 150, spec_note: 'n' },
    { tenant_id: 'T2', char_max: 150, spec_note: 'n' },
    { tenant_id: 'T3', char_max: 200, spec_note: 'n' },
    { tenant_id: 'T4', char_max: 150, spec_note: 'n' },
  ];
  const d = tenantValueBreakdown(rows, 'char_max');
  assert.strictEqual(d.diverged, true);
  assert.strictEqual(d.expected, '150', 'the value the most rows hold is the expected one');
  assert.strictEqual(d.expected_row_count, 3);
  assert.strictEqual(d.divergent_row_count, 1);
  assert.deepStrictEqual(d.divergent, [{ value: '200', tenants: ['T3'], row_count: 1 }]);

  // All agreeing → not diverged, so the UI renders nothing on the normal path.
  const same = tenantValueBreakdown(rows, 'spec_note');
  assert.strictEqual(same.diverged, false);
  assert.deepStrictEqual(same.divergent, []);
  assert.strictEqual(same.expected_row_count, 4);

  // null and '' are the SAME value — an unset spec_note and an empty one are not
  // two different tenant opinions.
  const nulls = tenantValueBreakdown(
    [{ tenant_id: 'T1', spec_note: null }, { tenant_id: 'T2', spec_note: '' }],
    'spec_note'
  );
  assert.strictEqual(nulls.diverged, false);

  // No rows at all (a renamed asset nobody matches) → empty, never a crash.
  assert.deepStrictEqual(tenantValueBreakdown([], 'char_max').divergent, []);
  assert.strictEqual(tenantValueBreakdown([], 'char_max').diverged, false);
});

test('specReview overwrite log: only rows whose VALUE changes are reported', () => {
  const { changedRows } = require('../src/services/specReview');

  const before = [
    { tenant_id: 'T1', char_max: 150 },
    { tenant_id: 'T2', char_max: 200 },
    { tenant_id: 'T3', char_max: 150 },
  ];
  // Writing 150: T2 loses its 200, the others are only re-stamped. The write
  // always sets spec_verified_at on every matched row, so counting a re-stamp as
  // an overwrite would bury the one row that actually lost data.
  const changed = changedRows(before, 'char_max', 150);
  assert.deepStrictEqual(changed, [
    { tenant_id: 'T2', attr: 'char_max', old_value: '200', new_value: '150', diverged: true },
  ]);

  // Writing something new overwrites everyone, and each entry carries what that
  // tenant held — the audit trail the commit log had no way to print before.
  const all = changedRows(before, 'char_max', 400);
  assert.strictEqual(all.length, 3);
  assert.deepStrictEqual(all.map((r) => [r.tenant_id, r.old_value]), [['T1', '150'], ['T2', '200'], ['T3', '150']]);

  // `diverged` separates the two kinds of overwrite. T1 and T3 held what everyone
  // else held — a routine update. T2 held its OWN value and that value is now
  // gone, which is the only one of the three that reverts a tenant.
  assert.deepStrictEqual(all.map((r) => r.diverged), [false, true, false]);

  assert.deepStrictEqual(changedRows([], 'char_max', 1), []);
});

test('admin.html surfaces divergence in the preview and the overwrite list after commit', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'admin.html'), 'utf8');
  // The preview roll-up says the write has no tenant filter, in the UI, not just
  // in a server log the admin will never read.
  assert.match(html, /pv\.diverged/);
  assert.match(html, /divergent_field_count/);
  assert.match(html, /no tenant filter/);
  // Per-field detail: which value, how many rows, which tenants.
  assert.match(html, /function divergenceNode/);
  assert.match(html, /row\(s\) hold something else and will be overwritten/);
  assert.match(html, /g\.tenants\.join/);
  // And after the write, what was actually reverted.
  assert.match(html, /w\.overwritten/);
  assert.match(html, /held a different value and were overwritten/);
  assert.match(html, /diverged_overwritten_count/);
  assert.match(html, /this tenant/, 'and names the rows whose own value is gone');
  // Amber — a fact to weigh, not an error that blocked the write.
  assert.match(html, /\.msg\.warn\s*\{[^}]*--warn/);
});

// --- Silent failure 3: a write that lands on nothing reported success ---------
// spec_watch_list.affected_fields is a snapshot taken once by
// migrateAddSpecTables.js and never recomputed, and commitReview's UPDATE matches
// copy_fields by asset NAME (and, since b2e13f2, only through an ACTIVE
// asset_types row). So a pair whose asset has been renamed, or all of whose rows
// have been deactivated, matches zero rows — and every step after the UPDATE used
// to run regardless: a spec_change_log entry recording a limit change for 0
// tenants, the flag flipped to 'reviewed' so the queue stopped showing it, and
// "Written. 0 tenant row(s) updated." on screen. An admin was told a platform's
// new limit was in place when nothing had been written.
//
// Live as of the 2026-07-31 audit: the Google watch entry's four pairs all name
// 'Google DV360 / Responsive Display', which migrateSpecIntegrityFixes.js renamed
// to 'Google Responsive Display Ad'.

// A pg stub that RECORDS the statements in order and answers by SQL substring.
// Same idiom as makeFakePool above, but scripted rather than stateful: what is
// under test is not what the rows contain, it is WHICH statements were issued and
// whether the transaction ended in COMMIT or ROLLBACK.
//
// `matched` is the rowCount the UPDATE reports. Zero is a renamed asset OR a
// fully deactivated one — commitReview cannot tell those apart, because both are
// invisible through the same `AND at.is_active` join, which is exactly why the
// refusal message names both causes.
function fakeSpecPool({ matched, before = [], pair }) {
  const log = [];
  const query = async (sql) => {
    const flat = String(sql).replace(/\s+/g, ' ').trim();
    log.push(flat);
    const has = (...frags) => frags.every((f) => flat.includes(f));

    if (has('FROM spec_review_queue q', 'JOIN spec_watch_list w')) {
      return {
        rows: [{
          id: 7, watch_id: 3, source_url: 'https://support.google.com/google-ads/answer/17090561',
          old_hash: 'a', new_hash: 'b', status: 'pending', is_test: false,
          detected_at: new Date(), display_name: 'Google', affected_fields: [pair],
        }],
        rowCount: 1,
      };
    }
    if (has('SELECT at.tenant_id')) return { rows: before, rowCount: before.length };
    if (has('UPDATE copy_fields cf')) {
      return { rows: Array.from({ length: matched }, (_, i) => ({ tenant_id: 'T' + i })), rowCount: matched };
    }
    if (has('INSERT INTO spec_change_log')) return { rows: [], rowCount: 1 };
    if (has('UPDATE spec_review_queue SET status')) return { rows: [], rowCount: 1 };
    if (flat === 'BEGIN' || flat === 'COMMIT' || flat === 'ROLLBACK') return { rows: [], rowCount: 0 };
    throw new Error('fake spec pool: unhandled query → ' + flat);
  };
  return { pool: { query, connect: async () => ({ query, release() {} }) }, log };
}

// Stub `pg`, reload db.js and specReview against it, run fn, restore everything.
// specReview destructures getPool at load, so it has to be reloaded AFTER db.js
// is dropped from the cache or it keeps the real one.
function withFakeSpecPool(opts, fn) {
  const saved = new Map();
  const remember = (p) => { if (!saved.has(p)) saved.set(p, require.cache[p]); };
  const rel = (r) => require.resolve(path.join(__dirname, '..', r));
  const savedUrl = process.env.DATABASE_URL;
  const fake = fakeSpecPool(opts);

  const pgPath = require.resolve('pg');
  remember(pgPath);
  require.cache[pgPath] = {
    id: pgPath, filename: pgPath, path: path.dirname(pgPath), loaded: true,
    exports: { Pool: function () { return fake.pool; } }, children: [], paths: [],
  };
  process.env.DATABASE_URL = 'postgres://fake/quillio';
  for (const r of ['src/db', 'src/services/specReview']) {
    const p = rel(r);
    remember(p);
    delete require.cache[p];
  }
  const spec = require(rel('src/services/specReview'));

  return Promise.resolve(fn(spec, fake)).finally(() => {
    for (const [p, mod] of saved) {
      if (mod === undefined) delete require.cache[p];
      else require.cache[p] = mod;
    }
    if (savedUrl === undefined) delete process.env.DATABASE_URL;
    else process.env.DATABASE_URL = savedUrl;
  });
}

const LIVE_PAIR = { asset: 'LinkedIn Single Image Ad', field: 'Intro Text' };
const RENAMED_PAIR = { asset: 'Google DV360 / Responsive Display', field: 'Short Headline' };
const DEACTIVATED_PAIR = { asset: 'LinkedIn Single Image Ad — Variant A', field: 'Intro Text' };

test('commitReview: a pair that resolves writes, logs and flips the flag', async () => {
  await withFakeSpecPool(
    { matched: 2, pair: LIVE_PAIR, before: [{ tenant_id: 'T1', char_max: 150 }, { tenant_id: 'T2', char_max: 150 }] },
    async (spec, fake) => {
      const r = await spec.commitReview(7, [{ ...LIVE_PAIR, char_max: 200 }], 1);
      assert.strictEqual(r.ok, true);
      assert.strictEqual(r.flagStatus, 'reviewed');
      assert.strictEqual(r.written[0].tenant_count, 2);
      // The success line in admin.html sums tenant_count. With the guard in
      // place a successful commit can no longer carry a zero.
      assert.ok(r.written.every((w) => w.tenant_count > 0));

      const joined = fake.log.join(' | ');
      assert.match(joined, /INSERT INTO spec_change_log/, 'the audit row is written');
      assert.match(joined, /UPDATE spec_review_queue SET status = 'reviewed'/, 'the flag is flipped');
      assert.strictEqual(fake.log[fake.log.length - 1], 'COMMIT');
      assert.ok(!fake.log.includes('ROLLBACK'));
    }
  );
});

// The two zero-row causes, asserted identically on purpose: the renamed asset is
// the one that is live today, the deactivated one is the case b2e13f2 created and
// that no watch entry is in yet. Both must refuse, and neither may leave a trace.
for (const [label, pair] of [['a renamed asset', RENAMED_PAIR], ['a deactivated asset', DEACTIVATED_PAIR]]) {
  test(`commitReview: ${label} refuses, rolls back, and writes nothing`, async () => {
    // before is EMPTY for both: currentValues carries the same `AND at.is_active`
    // join as the write, so a renamed asset and a fully deactivated one look the
    // same to it. That is the honest shape, not a simplification.
    await withFakeSpecPool({ matched: 0, pair, before: [] }, async (spec, fake) => {
      const r = await spec.commitReview(7, [{ ...pair, char_max: 200 }], 1);

      assert.strictEqual(r.ok, false, 'the write is refused, not reported as a 0-row success');
      assert.ok(!('written' in r), 'and carries no written[] for a UI to sum to zero');

      // The message names the pair, says nothing was written, says the flag is
      // still pending, and points at the repair — which is re-deriving the watch
      // entry, NOT editing the library.
      assert.ok(r.error.includes(`${pair.asset} / ${pair.field}`), 'names the pair');
      assert.match(r.error, /NOTHING was written/);
      assert.match(r.error, /still pending/);
      assert.match(r.error, /affected_fields/);
      assert.match(r.error, /affectedFieldsWhere\(\) in seedWatchList/);
      assert.match(r.error, /scripts\/migrateAddSpecTables\.js/);
      assert.match(r.error, /renamed, or every row behind it has been deactivated/,
        'names both causes, because this layer cannot tell them apart');
      assert.match(r.error, /library is not what is wrong/, 'and does not send them to fix copy_fields');

      // Nothing survived the transaction.
      const joined = fake.log.join(' | ');
      assert.ok(!joined.includes('INSERT INTO spec_change_log'), 'no audit row for a change nobody received');
      assert.ok(!joined.includes('UPDATE spec_review_queue SET status'), 'the flag stays pending');
      assert.strictEqual(fake.log[fake.log.length - 1], 'ROLLBACK');
      assert.ok(!fake.log.includes('COMMIT'));
    });
  });
}

test('the zero-row guard sits inside the transaction, before the audit row', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'specReview.js'), 'utf8');
  const at = (needle) => {
    const i = src.indexOf(needle);
    assert.ok(i > 0, 'expected to find ' + needle);
    return i;
  };
  // Ordering is what makes the rollback meaningful: BEGIN, the UPDATE, the guard,
  // then the audit row and the flag flip. Moving the guard below either of the
  // last two would put it after the writes it exists to prevent.
  const begin = at("client.query('BEGIN')");
  const update = at("'UPDATE copy_fields cf'");
  const guard = at('if (tenantCount === 0)');
  const audit = at('INSERT INTO spec_change_log');
  const flip = at("UPDATE spec_review_queue SET status = 'reviewed'");
  const commit = at("client.query('COMMIT')");
  assert.ok(begin < update && update < guard, 'the guard reads the write it guards');
  assert.ok(guard < audit && audit < flip && flip < commit, 'and precedes both writes and the COMMIT');

  // It throws rather than returning, so the existing catch does the ROLLBACK —
  // one rollback path, not two.
  assert.match(src.slice(guard, audit), /throw new SpecWriteRefusal/);
  assert.match(src, /if \(err instanceof SpecWriteRefusal\)/, 'and the catch surfaces its message');
  // A driver error still gets the generic sentence: not every failure is ours to
  // put in front of an admin.
  assert.match(src, /write failed -- rolled back, nothing changed/);

  // And the refusal reaches the screen. api() throws Error(data.error) on a
  // non-2xx, the route answers 400 with result.error, and the commit button's
  // catch renders that message — so the admin reads the named pair rather than
  // "Written. 0 tenant row(s) updated."
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'admin.html'), 'utf8');
  assert.match(html, /'Write failed: '\s*\+\s*e\.message/, 'the commit catch renders the server message');
  assert.match(html, /throw new Error\(data\.error/, 'and api\(\) carries it through unaltered');
});

// --- Re-deriving affected_fields (scripts/rederiveAffectedFields.js) ---------
// The repair for one stale watch entry. What is worth pinning here is not the
// derivation — that needs a database — but the four things a reader of the script
// is relying on: that it cannot be run unscoped, that it carries the is_active
// divergence deliberately, that it refuses rather than writing an empty gate, and
// that its Litmus refusal list still matches the rows it protects.

test('rederive: scoped to one entry, with no --all', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'rederiveAffectedFields.js'), 'utf8');
  assert.match(src, /--only=<watch id> is required/);
  assert.ok(!/'--all'|"--all"|argv\.includes\('--all'\)/.test(src), 'no --all is implemented');
  // Dry run by default, like every other write script in scripts/.
  assert.match(src, /const COMMIT = process\.argv\.includes\('--commit'\)/);
  assert.match(src, /ROLLED BACK \(dry run\)/);
});

test('rederive: the is_active divergence is deliberate, and says so', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'rederiveAffectedFields.js'), 'utf8');
  const derive = src.slice(src.indexOf('const DERIVE_SQL'), src.indexOf('function sslFor'));
  assert.match(derive, /cf\.spec_source = \$1/, 'platform entries derive from the watch URL');
  assert.match(derive, /AND at\.is_active/, 'and skip deactivated assets');

  // The seed query it diverges from still does NOT carry the predicate — if that
  // ever changes, this note becomes wrong and should be removed rather than left
  // describing a difference that no longer exists.
  const seed = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'migrateAddSpecTables.js'), 'utf8');
  const fn = seed.slice(seed.indexOf('async function affectedFieldsWhere'), seed.indexOf('// Insert one watch entry'));
  assert.ok(!/is_active/.test(fn), 'affectedFieldsWhere still has no is_active filter');
  assert.match(src, /NOT in affectedFieldsWhere\(\)/, 'and the script names the divergence in its header');
  assert.match(src, /b2e13f2/, 'and says which change made it necessary');
});

test('rederive: refuses an empty gate, the test row, and the note-derived rows', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'rederiveAffectedFields.js'), 'utf8');
  assert.match(src, /REFUSED: the derivation is EMPTY/);
  assert.match(src, /REFUSED: this is the is_test entry/);
  assert.match(src, /REFUSED: this entry is derived from spec_note text/);

  // The Litmus URLs are a REFUSAL list, so they have to match the rows they are
  // protecting. Read out of the migration rather than retyped, the same way the
  // retired-name coverage test reads RETIRE out of its migration.
  const seed = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'migrateAddSpecTables.js'), 'utf8');
  const litmus = seed.slice(seed.indexOf('const LITMUS = ['), seed.indexOf('const TEST_ENTRY'));
  const seedUrls = (litmus.match(/'(https:\/\/[^']+)'/g) || []).map((s) => s.slice(1, -1)).sort();
  const scriptBlock = src.slice(src.indexOf('const NOTE_DERIVED_URLS'), src.indexOf('// The platform rule'));
  const scriptUrls = (scriptBlock.match(/'(https:\/\/[^']+)'/g) || []).map((s) => s.slice(1, -1)).sort();
  assert.strictEqual(seedUrls.length, 2, 'two note-derived entries in the seed');
  assert.deepStrictEqual(scriptUrls, seedUrls, 'the refusal list matches the seed byte for byte');
});

test('rederive: the header says it re-freezes, and names what it does not repair', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'rederiveAffectedFields.js'), 'utf8');
  // Someone running this will reasonably assume it fixed the class. It fixes one
  // instance, and the added-field case it does not repair has no detection
  // anywhere — not the zero-row guard, not auditWatchList.
  assert.match(src, /RE-FREEZES THE SNAPSHOT/);
  assert.match(src, /DOES NOT REPAIR THE WORST CASE/);
  assert.match(src, /field ADDED to a watched asset/);
  assert.match(src, /auditWatchList\.js cannot see it either/);
  assert.match(src, /fixes one instance of a class/);
  // And the same two facts are in CLAUDE.md, next to the frozen-snapshot note.
  const claude = fs.readFileSync(path.join(__dirname, '..', 'CLAUDE.md'), 'utf8');
  assert.match(claude, /it does not fix the class/);
  assert.match(claude, /### The durable fix is an open decision/);
  assert.match(claude, /only as trustworthy as `spec_source`/);
  // The carousel gap is CLOSED — row #12 exists, anchored and baselined — so the
  // heading changed. What this assertion was guarding is not the gap but the
  // ORDERING rule it taught: add the new watch row BEFORE re-deriving the old
  // entry, or six pairs go from gated-by-the-wrong-page to gated-by-nothing.
  // That rule outlives the instance and is what `--only` exists for.
  assert.match(claude, /### CLOSED: LinkedIn Carousel now has its own watch row/);
  assert.match(claude, /gate-by-the-wrong-page into a gate-by-nothing/);
});

// --- Asset-library uniqueness (scripts/migrateAddAssetUniqueness.js) ---------
// There is no UNIQUE constraint on asset_types (tenant_id, name) or copy_fields
// (asset_type_id, field_name), and duplicates do not fail loudly — they resolve
// four different ways (pipeline takes the FIRST row, getAssetDirections the LAST,
// copyReview's fieldKey and googleDocs' ctxKey collapse a repeated field name
// onto one key). The migration adds the constraint; these tests pin the parts of
// it that can be checked without a database.

test('normalizer convergence: one definition, not three', () => {
  const assets = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');
  const gemini = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'gemini.js'), 'utf8');

  // Neither file may re-declare a normalizer of its own any more.
  assert.ok(!/function normName\s*\(/.test(assets), 'db/assets.js no longer defines its own normName');
  assert.match(assets, /require\('\.\.\/utils\/normalize'\)/, 'db/assets.js takes the shared one');
  assert.ok(
    !/const normalize = \(s\) =>/.test(gemini),
    'gemini.js no longer defines a local normalize inside parseBrief'
  );
  assert.match(gemini, /require\('\.\.\/utils\/normalize'\)/, 'gemini.js takes the shared one');
});

test('normalizer convergence: no allowed asset name collides under the shared fold', () => {
  const { normalize } = require('../src/utils/normalize');
  const { ALLOWED_ASSETS } = require('../src/config');
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');

  // If two allowed names folded together, parseBrief's canonicalByNorm would
  // silently drop one — and the unique index would refuse to build at all.
  const seen = new Map();
  for (const n of ALLOWED_ASSETS) {
    const k = normalize(n);
    assert.ok(!seen.has(k), `"${n}" and "${seen.get(k)}" both normalize to "${k}"`);
    seen.set(k, n);
  }
  assert.strictEqual(seen.size, ALLOWED_ASSETS.length);
});

test('the bundled library can actually satisfy the unique index', () => {
  // The precondition for the migration: seedTenantAssets must not itself create
  // a conflict. A duplicate introduced into defaultAssets.js would make the
  // migration refuse for EVERY tenant, so this fails CI instead.
  const { normalize } = require('../src/utils/normalize');
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');

  const names = new Map();
  for (const a of DEFAULT_ASSETS) {
    const k = normalize(a.name);
    assert.ok(!names.has(k), `asset "${a.name}" and "${names.get(k)}" both normalize to "${k}"`);
    names.set(k, a.name);
  }
  // And no asset may carry two fields whose names fold together.
  for (const a of DEFAULT_ASSETS) {
    const fields = new Map();
    for (const f of a.fields) {
      const k = normalize(f.field_name);
      assert.ok(
        !fields.has(k),
        `${a.name}: fields "${f.field_name}" and "${fields.get(k)}" both normalize to "${k}"`
      );
      fields.set(k, f.field_name);
    }
  }
});

test('gemini parse matching got MORE tolerant, and stayed collision-free', () => {
  const { normalize } = require('../src/utils/normalize');
  // The local normalizer folded dashes but kept the spaces around them, so an
  // em dash written WITHOUT spaces missed. The shared one matches it.
  assert.strictEqual(normalize('Direct Mail—Box / Mailer'), normalize('Direct Mail — Box / Mailer'));
  assert.strictEqual(normalize('Direct Mail - Box / Mailer'), normalize('Direct Mail — Box / Mailer'));
  assert.strictEqual(normalize('direct mail  —  box / mailer'), normalize('Direct Mail — Box / Mailer'));
  // Still distinguishes genuinely different assets.
  assert.notStrictEqual(normalize('One-Pager'), normalize('Battle Card'));
  assert.notStrictEqual(
    normalize('LinkedIn Single Image Ad — Variant A'),
    normalize('LinkedIn Single Image Ad — Variant B')
  );
});

test('migration SQL character classes are DERIVED from the JS regexes, not retyped', () => {
  // The drift guard. The index must fold exactly what utils/normalize folds; if
  // a future edit changes either JS class, these recomputed strings stop
  // matching the migration's constants and CI fails instead of the index
  // quietly disagreeing with the pipeline.
  const { WS, DASH } = require('../scripts/migrateAddAssetUniqueness');

  const esc = (c) => '\\u' + c.toString(16).toLowerCase().padStart(4, '0');
  const classFor = (re) => {
    const cps = [];
    for (let c = 0; c <= 0xffff; c += 1) if (re.test(String.fromCodePoint(c))) cps.push(c);
    const parts = [];
    let i = 0;
    while (i < cps.length) {
      let j = i;
      while (j + 1 < cps.length && cps[j + 1] === cps[j] + 1) j += 1;
      parts.push(j - i >= 2 ? `${esc(cps[i])}-${esc(cps[j])}` : cps.slice(i, j + 1).map(esc).join(''));
      i = j + 1;
    }
    return parts.join('');
  };

  assert.strictEqual(WS, classFor(/\s/), 'WS class still equals every character JS \\s matches');
  assert.strictEqual(DASH, classFor(/[‐-―−]/), 'DASH class still equals the normalize() dash set');

  // Postgres \s is locale-dependent and does NOT match U+00A0, so using it would
  // make the index LAXER than the pipeline. The class must stay spelled out.
  assert.ok(WS.includes('\\u00a0'), 'the whitespace class covers NBSP explicitly');
  const { NORMALIZE_SQL } = require('../scripts/migrateAddAssetUniqueness');
  assert.ok(!/\\\\s/.test(NORMALIZE_SQL), 'the SQL never falls back to Postgres \\s');
});

test('migration SQL mirrors normalize() step for step, in order', () => {
  const { NORMALIZE_SQL, CREATE_FUNCTION_SQL } = require('../scripts/migrateAddAssetUniqueness');
  // lower → fold dashes → drop spaces around hyphens → collapse runs → trim.
  // The order is load-bearing: dropping spaces around hyphens BEFORE collapsing
  // runs is what turns 'A  —  B' into 'a-b' rather than 'a - b'.
  const dashAt = NORMALIZE_SQL.indexOf("'-', 'g'");
  const collapseAt = NORMALIZE_SQL.indexOf("' ', 'g'");
  assert.ok(NORMALIZE_SQL.includes('lower(coalesce($1'), 'lowercases first, null-safe like String(s || "")');
  assert.ok(dashAt > 0 && collapseAt > dashAt, 'dash/hyphen folding happens before whitespace collapsing');
  assert.ok(NORMALIZE_SQL.includes("btrim("), 'and trims last');
  // The index expression needs an IMMUTABLE function or Postgres refuses it.
  assert.match(CREATE_FUNCTION_SQL, /IMMUTABLE/);
  assert.match(CREATE_FUNCTION_SQL, /quillio_normalize_name/);
});

test('migration is dry-run by default, refuses on conflict, and never auto-resolves', () => {
  const src = fs.readFileSync(
    path.join(__dirname, '..', 'scripts', 'migrateAddAssetUniqueness.js'),
    'utf8'
  );
  assert.match(src, /const COMMIT = process\.argv\.includes\('--commit'\)/, 'writes are opt-in');
  assert.match(src, /REFUSING TO CREATE THE INDEXES/, 'a conflict stops the run');
  assert.match(src, /process\.exit\(refused \? 2 : 0\)/, 'and exits non-zero so a pipeline notices');
  // Everything is one transaction, so a refusal leaves no function and no index.
  assert.match(src, /await client\.query\('BEGIN'\)/);
  // It must not delete, rename or otherwise pick a winner among duplicates.
  assert.ok(!/DELETE FROM asset_types|UPDATE asset_types SET name/.test(src), 'never resolves a conflict itself');

  const { INDEXES } = require('../scripts/migrateAddAssetUniqueness');
  assert.strictEqual(INDEXES.length, 2);
  assert.ok(INDEXES.every((i) => /CREATE UNIQUE INDEX IF NOT EXISTS/.test(i.sql)), 're-runnable');
  // Both nullable owner columns are coalesced — a unique index treats NULLs as
  // distinct, so two orphan rows sharing a name would otherwise slip through.
  assert.match(INDEXES[0].sql, /coalesce\(tenant_id, ''\)/);
  assert.match(INDEXES[1].sql, /coalesce\(asset_type_id, -1\)/);
});

// --- The parse allow-list is the TENANT's library, not a global constant ------
// config.ALLOWED_ASSETS gated gemini.parseBrief unconditionally, which meant an
// asset sitting in a tenant's asset_types but missing from the bundled 30 was
// filtered out of the plan — a tenant could not ask for an asset they owned.
// Three of the four gates downstream were already per-tenant; this was the one
// global one, upstream of all of them.

test('parseBrief is gated on the vocabulary it is GIVEN, not on ALLOWED_ASSETS', async () => {
  const { ALLOWED_ASSETS } = require('../src/config');
  const custom = 'Podcast Read Ad';
  assert.ok(!ALLOWED_ASSETS.includes(custom), 'the fixture name is genuinely not in the bundled list');

  const model = { ...MODEL_BASE, assets: [{ asset: custom, count: 2 }, { asset: 'Battle Card', count: 1 }] };

  // Given a tenant vocabulary that HAS it, it survives the filter.
  const withTenant = await parseBriefWith(model, 'brief', [custom, 'Battle Card']);
  assert.deepStrictEqual(withTenant.result.assets, [
    { asset: custom, count: 2 },
    { asset: 'Battle Card', count: 1 },
  ]);
  assert.deepStrictEqual(withTenant.result.unmatchedAssets, []);
  assert.ok(withTenant.prompt.includes(custom), 'and the model was actually offered it');

  // Given the bundled list (the old behavior), it is filtered out and surfaced.
  const withDefault = await parseBriefWith(model, 'brief');
  assert.deepStrictEqual(withDefault.result.assets, [{ asset: 'Battle Card', count: 1 }]);
  assert.deepStrictEqual(withDefault.result.unmatchedAssets, [custom]);
});

test('a name the TENANT lacks is caught at parse, not thrown downstream', async () => {
  // Before, a name in ALLOWED_ASSETS but absent from the tenant's library parsed
  // clean and then threw inside tenantAssetsToSpecs. Now the parse gate is the
  // same list the expansion checks, so it is reported instead of exploding.
  const narrow = require('../src/config').ALLOWED_ASSETS.filter((n) => n !== 'Battle Card');
  const { result } = await parseBriefWith(
    { ...MODEL_BASE, assets: [{ asset: 'Battle Card', count: 1 }, { asset: 'One-Pager', count: 1 }] },
    'brief',
    narrow
  );
  assert.deepStrictEqual(result.assets, [{ asset: 'One-Pager', count: 1 }]);
  assert.deepStrictEqual(result.unmatchedAssets, ['Battle Card']);

  // And what survived really does clear the downstream gate.
  const { tenantAssetsToSpecs } = require('../src/core/pipeline');
  const rows = narrow.map((name, i) => ({
    id: i + 1, name, group: 'g', sort_order: i,
    fields: [{ field_name: 'H', char_min: 0, char_max: 10, field_type: 'text', sort_order: 0 }],
  }));
  assert.strictEqual(tenantAssetsToSpecs(rows, result.assets).length, 1);
});

test('no-DB / demo falls back to the 30-name constant, unchanged', async () => {
  const { resolveAssetVocabulary } = require('../src/core/pipeline');
  const { ALLOWED_ASSETS } = require('../src/config');
  // No DATABASE_URL in the test env, so getTenantAssets returns null for any id.
  for (const tenantId of [null, undefined, 'T0B8LPRDKHR']) {
    const v = await resolveAssetVocabulary(tenantId);
    assert.strictEqual(v.source, 'default', `tenant ${tenantId} falls back`);
    assert.deepStrictEqual(v.names, ALLOWED_ASSETS);
  }
  // An empty list passed to gemini.parseBrief is treated as "no vocabulary",
  // never as "nothing is allowed" — which would reject every brief.
  const { prompt } = await parseBriefWith({ ...MODEL_BASE, assets: [] }, 'brief', []);
  assert.ok(prompt.includes('Battle Card'), 'an empty list still offers the bundled 30');
});

test('the mapping block is filtered to targets the tenant actually has', async () => {
  const { assetPhraseHintLines, ASSET_PHRASE_HINTS } = require('../src/services/gemini');
  const { ALLOWED_ASSETS } = require('../src/config');

  // Every targeted hint must name a real asset AND mention it in its own rendered
  // line. That is the drift guard: `target` drives the filtering, so if someone
  // rewrites a line's text without updating `target` (or vice versa), the wrong
  // line gets dropped for the wrong tenant. Not `endsWith` — most lines are
  // "phrase → Target", but the A/B one is prose ("… one entry: X, count 3").
  for (const h of ASSET_PHRASE_HINTS) {
    if (h.always || h.anyMatching) continue;
    assert.ok(ALLOWED_ASSETS.includes(h.target), `${h.target} is a real asset name`);
    assert.ok(h.line.includes(h.target), `hint line for ${h.target} names its own target`);
    // AND ONLY ITS OWN. The filter drops a line by its `target`, so a line that
    // also names a SECOND asset survives into the prompt of a tenant who has the
    // first and not the second — the stale-mapping failure this table's header
    // warns about, arriving through a line that passes the check above.
    //
    // It became reachable when the landing-page routes were split into a default
    // and a specialisation, where the tempting phrasing is "…, not the other
    // one". Each line has to stand alone instead, and their ORDER is what relates
    // them.
    for (const other of ALLOWED_ASSETS) {
      if (other === h.target) continue;
      assert.ok(!h.line.includes(other), `hint for ${h.target} must not also name ${other}`);
    }
  }

  // TRIPWIRE, NOT COVERAGE — and labelled as one because it cannot tell a good
  // route from a bad one. It pins the DIRECTION of the landing-page pair, which
  // shipped inverted: a bare "landing page" routed to the EVENT asset while
  // Campaign Landing Page needed the literal phrase "campaign page", so a product
  // launch got Stat 1-3 and four benefit blocks with nothing flagged. Whether the
  // corrected routing actually changes what the model returns is a question for
  // scripts/checkParsePlans.js and a live key; this only stops the inversion
  // being tidied back in.
  const routes = assetPhraseHintLines(ALLOWED_ASSETS);
  const campaign = routes.find((l) => l.includes('→ Campaign Landing Page'));
  const event = routes.find((l) => l.includes('→ Event Landing Page'));
  assert.ok(campaign && event, 'both landing-page routes are present');
  assert.match(campaign, /"landing page"/, 'the BARE phrase belongs to the campaign asset');
  assert.ok(!/"landing page"/.test(event), 'and must not also be claimed by the event asset');
  assert.match(event, /date|venue|registration/i, 'the event asset requires an event signal');
  assert.ok(
    routes.indexOf(campaign) < routes.indexOf(event),
    'the default is stated before the specialisation'
  );

  // Full list → every mapping present.
  const full = assetPhraseHintLines(ALLOWED_ASSETS).join('\n');
  assert.ok(full.includes('→ Battle Card'));
  assert.ok(full.includes('→ Sales Basho Email'));

  // Narrow list → the lines whose targets are gone go with them. A stale mapping
  // line is worse than none: it tells the model to emit a name the filter will
  // then reject, which is exactly the silent drop this work made loud.
  const narrow = assetPhraseHintLines(['One-Pager', 'Campaign Landing Page']).join('\n');
  assert.ok(!narrow.includes('Battle Card'), 'no mapping to an asset this tenant lacks');
  assert.ok(!narrow.includes('Sales Basho Email'));
  assert.ok(narrow.includes('→ One-Pager'), 'kept the one it does have');

  // The count/A-B rule is about the `count` mechanism, not any asset, so it
  // survives a library with no LinkedIn in it at all.
  assert.ok(narrow.includes('the BASE asset, count 2'), 'universal count guidance always ships');
  assert.ok(narrow.includes('MORE VERSIONS OF ONE ASSET'));
  // …but the LinkedIn example and the Variant caveat do not.
  assert.ok(!narrow.includes('3 linkedin ads'), 'the LinkedIn example needs LinkedIn');
  assert.ok(!narrow.includes('Variant A'), 'the Variant caveat needs Variant types');
  assert.ok(
    assetPhraseHintLines(['LinkedIn Single Image Ad — Variant A']).join('\n').includes('Variant A'),
    'and it comes back for a library that has them'
  );
});

test('refusal examples never name an asset the tenant owns', async () => {
  const { refusalRuleLine, REFUSAL_EXAMPLES } = require('../src/services/gemini');
  const { ALLOWED_ASSETS } = require('../src/config');

  // Default library: none of the four are in it, so all four still illustrate.
  const base = refusalRuleLine(ALLOWED_ASSETS);
  for (const ex of REFUSAL_EXAMPLES) assert.ok(base.includes(ex), `${ex} still an example`);

  // A tenant with a podcast asset must NOT be told to refuse podcast asks. The
  // match is token-based on purpose: "Podcast Read Ad" does not CONTAIN the
  // substring "podcast ad" — "Read" sits between the words — so a substring
  // test left this exact line in the prompt.
  const podcast = refusalRuleLine([...ALLOWED_ASSETS, 'Podcast Read Ad']);
  assert.ok(!podcast.includes('podcast ad'), 'dropped the example this tenant owns');
  assert.ok(podcast.includes('TikTok') && podcast.includes('billboard'), 'kept the others');

  // A tenant owning all four gets the rule with no examples rather than a rule
  // naming their own assets as things to refuse.
  const all = refusalRuleLine(['TikTok Ad', 'Podcast Ad', 'Billboard', 'SMS Blast']);
  assert.ok(!/e\.g\./.test(all), 'no examples left');
  assert.ok(all.includes('do NOT substitute a nearest guess'), 'but the rule still stands');
});

test('the unmatched message names the gate that actually ran', () => {
  const { totalMissMessage, partialMissNotice } = require('../src/utils/assetMatch');

  // Tenant library gate → "your asset library", and adding it is REAL advice.
  const t = totalMissMessage(['TikTok Ad'], 'tenant');
  assert.match(t, /your asset library: TikTok Ad\./);
  assert.match(t, /add them to your asset library/i);
  const tp = partialMissNotice(['TikTok Ad'], 'tenant');
  assert.match(tp, /your asset library/);
  assert.match(tp, /Add it to your asset library to include it next time\./);

  // Bundled-list gate (no DB / demo) → the old wording. There is no library to
  // add to, so promising that adding one would help would be a lie.
  const d = totalMissMessage(['TikTok Ad'], 'default');
  assert.match(d, /any asset type Quillio supports/);
  assert.ok(!/add them to your asset library/i.test(d), 'never promises a fix that cannot work');
  // An absent/unknown source degrades to the weaker but never-false claim.
  assert.strictEqual(totalMissMessage(['X']), totalMissMessage(['X'], 'default'));
  assert.strictEqual(partialMissNotice(['X'], 'nonsense'), partialMissNotice(['X'], 'default'));
});

test('LiveSpecs reads and writes both skip deactivated asset rows', () => {
  const fs = require('fs');
  const path = require('path');
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'specReview.js'), 'utf8');

  // currentValues is the ONLY read in the file that joins asset_types, and all
  // four callers go through it — so one predicate here covers the review form,
  // the preview, the pre-commit capture and the Gemini suggestion pass.
  const read = src.slice(src.indexOf('async function currentValues'), src.indexOf('// Distinct current value'));
  assert.match(read, /JOIN asset_types at ON at\.id = cf\.asset_type_id/);
  assert.match(read, /AND at\.is_active/, 'the shared read filters inactive assets');
  assert.strictEqual(
    (src.match(/JOIN asset_types at ON at\.id = cf\.asset_type_id/g) || []).length,
    1,
    'still exactly one asset_types read — a second would need its own filter'
  );

  // The write must agree with the read: `before` is captured through
  // currentValues, so a row the capture skipped must not then be written.
  const write = src.slice(src.indexOf("'UPDATE copy_fields cf'"), src.indexOf('RETURNING at.tenant_id'));
  assert.match(write, /AND at\.is_active/, 'and so does the write');
});

// --- A retired asset name is told what replaced it ---------------------------
// f3683f4 retired six asset types. "Add it to your asset library" is the wrong
// instruction for any of them: following it rebuilds the near-duplicate the
// prune removed. These assert the redirect fires, replaces (not supplements)
// that advice, and never fires on an ordinary unknown name.

test('retired names: a form/confirmation phrase is redirected to the template flow', () => {
  const { totalMissMessage, partialMissNotice } = require('../src/utils/assetMatch');

  const t = totalMissMessage(['confirm page'], 'tenant');
  assert.match(t, /document template now/, 'says what replaced it');
  assert.match(t, /import one in Settings/);
  // The contradictory advice is GONE, not merely followed by a correction.
  assert.ok(!/add .* to your asset library/i.test(t), 'the wrong instruction is replaced');
  assert.match(t, /Nothing was built\./, 'still reads as the refusal it is');

  // The phrase the brief actually used is what arrives — none of these is the
  // retired canonical name, and all of them must land.
  for (const phrase of ['confirm page', 'the confirmation page', 'Form Confirm Page',
    'Form and Confirmation Copy', 'form  confirm  page']) {
    assert.match(totalMissMessage([phrase], 'tenant'), /document template now/, phrase);
  }

  const p = partialMissNotice(['confirm page'], 'tenant');
  assert.match(p, /document template now/);
  assert.match(p, /everything else was built/, 'stays advisory, not a failure');
  assert.ok(!/Add it to your asset library/i.test(p));
});

test('retired names: variant-letter phrasing is redirected to a count', () => {
  const { totalMissMessage } = require('../src/utils/assetMatch');

  const t = totalMissMessage(['variant B'], 'tenant');
  assert.match(t, /is a count now/);
  assert.ok(!/add .* to your asset library/i.test(t));
  assert.match(totalMissMessage(['LinkedIn Single Image Ad — Variant A'], 'tenant'), /is a count now/);

  // Unlike the template redirect, a count works with or without a library, so
  // this one is true on the bundled-list path too.
  assert.match(totalMissMessage(['variant C'], 'default'), /is a count now/);
});

test('retired names: the template redirect is withheld where it cannot be followed', () => {
  const { totalMissMessage } = require('../src/utils/assetMatch');

  // No tenant → no Settings to import a template into. Promising one would be
  // the same class of lie the two wordings above exist to avoid.
  const d = totalMissMessage(['confirm page'], 'default');
  assert.ok(!/document template now/.test(d), 'not offered on the bundled-list path');
  assert.match(d, /try different asset names/, 'falls back to the honest generic advice');
});

test('retired names: a mixed batch keeps both kinds of advice, correctly scoped', () => {
  const { totalMissMessage, partialMissNotice } = require('../src/utils/assetMatch');

  const t = totalMissMessage(['confirm page', 'TikTok Ad'], 'tenant');
  assert.match(t, /document template now/, 'the retired one is redirected');
  assert.match(t, /Add TikTok Ad to your asset library/, 'the unknown one still gets the real fix');
  // Scoped BY NAME, so the library advice cannot be read as covering the
  // retired name sitting in the same sentence list.
  assert.ok(!/Add confirm page to your asset library/i.test(t));

  const p = partialMissNotice(['variant B', 'TikTok Ad'], 'tenant');
  assert.match(p, /is a count now/);
  assert.match(p, /Add TikTok Ad to your asset library to include it next time\./);
});

test('retired names: an ordinary unknown name is untouched, byte for byte', () => {
  const { totalMissMessage, partialMissNotice } = require('../src/utils/assetMatch');

  // The guarantee that makes this change safe to land: when no retired name is
  // present the output is exactly what it was before the table existed.
  assert.strictEqual(
    totalMissMessage(['TikTok Ad', 'Billboard'], 'tenant'),
    "Couldn't match these to your asset library: TikTok Ad, Billboard. " +
      'Nothing was built — add them to your asset library, or try different asset names.'
  );
  assert.strictEqual(
    partialMissNotice(['TikTok Ad'], 'tenant'),
    "Couldn't match these to your asset library: TikTok Ad. It was left out — " +
      'everything else was built. Add it to your asset library to include it next time.'
  );

  // Words that share a stem with a trigger but mean something else. "landing
  // page", "form" and a plural "variants" are ordinary brief vocabulary; a
  // trigger loose enough to catch them would fire on half the misses there are.
  for (const innocent of ['Landing Page', 'Registration Form', 'Confirmation Email',
    '4 variants', 'Billboard']) {
    const m = totalMissMessage([innocent], 'tenant');
    assert.ok(!/document template now|is a count now/.test(m), `no redirect for "${innocent}"`);
  }
});

test('retired names: the guidance table covers every name the migration retired', () => {
  const { RETIRED_GUIDANCE } = require('../src/utils/assetMatch');
  const { RETIRE } = require('../scripts/migrateRetireDeadAssets');
  const { normalize } = require('../src/utils/normalize');

  // Derived from the migration rather than hand-typed here, so retiring another
  // asset without saying what replaced it fails at this line instead of showing
  // a writer advice that rebuilds what was just removed.
  assert.ok(Array.isArray(RETIRE) && RETIRE.length > 0, 'the migration still exports RETIRE');
  for (const [name] of RETIRE) {
    const hits = RETIRED_GUIDANCE.filter((g) => g.test(normalize(name)));
    assert.strictEqual(hits.length, 1, `"${name}" is covered by exactly one entry (got ${hits.length})`);
  }

  // And every entry earns its place — an orphan is a rule for a name nothing
  // can produce any more.
  for (const g of RETIRED_GUIDANCE) {
    assert.ok(
      RETIRE.some(([name]) => g.test(normalize(name))),
      `guidance "${g.key}" still speaks for a retired name`
    );
  }
});

