test('an asset name is a heading, and the toggle never moves', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  // Headings take the display face; body copy stays in the body face.
  assert.match(html, /\.lib-name \{ font-family: 'StarCrush', serif/);
  assert.match(html, /\.lib-group \{[^}]*font-size: 11px/);
  assert.ok(!/\.lib-group \{[^}]*StarCrush/.test(html), 'the group is body copy, not a heading');

  // The head is two columns and the toggle is not one of the wrapping things.
  assert.match(html, /\.lib-head \{ display: flex; align-items: flex-start/);
  assert.ok(!/\.lib-head \{[^}]*flex-wrap: wrap/.test(html));
  assert.match(html, /\.lib-headtext \{ flex: 1; min-width: 0;[^}]*flex-wrap: wrap/);
  assert.match(html, /var headText = el\('div', 'lib-headtext'\)/);
  assert.match(html, /\.lib-toggle \{[^}]*flex: none/);

  // The create form's row-name rule is scoped, so it stops bolding the read-only
  // card's field names 70 lines above it.
  assert.match(html, /\.lib-frow \.lib-fname \{[^}]*flex: 1/);
  assert.match(html, /\.lib-fname \{ color: var\(--ink\); \}/, 'the card\'s own rule is intact');
});

test('the review modal reads its heading in the display face and cannot be abandoned', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'app.html'), 'utf8');
  // "Reviewing your copy…" is the heading of that state, so it takes .review-status
  // (StarCrush) like the result heading — it was .review-note (the body face)
  // while the Close button below it was StarCrush, i.e. the rule exactly inverted.
  assert.match(html, /<div class="review-status">Reviewing your copy…<\/div>/);
  assert.match(html, /\.review-status \{ font-family: 'StarCrush', serif/);
  assert.match(html, /\.review-note \{ font-family: 'Zen Kaku Gothic New'/);

  // Close is gone — the run takes seconds and there is nothing to gain by
  // abandoning it. Its handler and its element go together; no dead listener.
  assert.ok(!/project-review-modal-close/.test(html), 'no Close button and no handler for one');
  // The sheet is still dismissable the way it already was.
  assert.match(html, /if \(e\.target === document\.getElementById\('project-review-modal'\)\) closeProjectReviewModal\(\)/);
});

// --- char_max 0 is NO LIMIT, not a limit of zero -----------------------------
// A real review comment: "The copy is 40 characters over the 0-character limit.
// If this legal footer is required, the character limit in the system needs to
// be updated." Same class as the char_min bug — a sentinel read as a constraint.
// fieldLabel has always applied the rule (googleDocs.js:408 renders no bracket);
// the prompts did not.

test('an unlimited field is sent to the review with no ceiling at all', async () => {
  const gemini = require('../src/services/gemini');
  const config = require('../src/config');
  const seen = [];
  const realFetch = global.fetch;
  const realKey = config.GEMINI_API_KEY;
  config.GEMINI_API_KEY = 'test-key';
  global.fetch = async (_url, opts) => {
    seen.push(JSON.parse(opts.body).contents[0].parts[0].text);
    return { ok: true, status: 200, json: async () => ({ candidates: [{ content: { parts: [{ text: '[]' }] }, finishReason: 'STOP' }] }) };
  };
  try {
    await gemini.reviewCopyFields({
      fields: [
        { assetType: 'Event Landing Page', fieldName: 'Legal Line', charMax: 0, fieldType: 'text',
          copy: 'Offer valid through 31 March. Terms apply.' },
        { assetType: 'Event Landing Page', fieldName: 'Hero Headline', charMax: 70, fieldType: 'text',
          copy: 'Two days with the people shipping this.' },
      ],
    });
  } finally {
    global.fetch = realFetch;
    config.GEMINI_API_KEY = realKey;
  }
  const payload = seen[0].slice(seen[0].indexOf('FIELDS:'));
  const fields = JSON.parse(payload.slice(payload.indexOf('[')));

  // The unlimited field carries NO charMax key — not 0, not null. A number that
  // is never sent cannot be asserted as a constraint.
  assert.ok(!('charMax' in fields[0]), 'no charMax key on the unlimited field');
  assert.ok(!/"charMax": 0/.test(payload), 'and no zero ceiling anywhere in the payload');
  // The unit still travels for it — that is orthogonal to having a ceiling.
  assert.strictEqual(fields[0].lengthUnit, 'characters');
  assert.strictEqual(fields[0].copy, 'Offer valid through 31 March. Terms apply.');
  // A field that DOES have a limit is unaffected.
  assert.strictEqual(fields[1].charMax, 70);

  // And the model is told what an absent ceiling means, in the words that rule
  // out the sentence the live run produced.
  // Joined with single spaces: the rule is stored as wrapped display lines, and
  // asserting on the wrap points would test the formatting, not the rule.
  const rule = gemini.LENGTH_RULE.join(' ').replace(/\s+/g, ' ');
  assert.match(rule, /A field with NO stated maximum/);
  assert.match(rule, /Never invent a ceiling for it/);
  assert.match(rule, /never write "the 0-character limit"/);
  assert.match(rule, /that the limit "needs to be updated"/);
  assert.ok(seen[0].includes(gemini.LENGTH_RULE.join('\n')), 'the rule ships with the payload');
});

test('the variation review states no ceiling for an unlimited field, in either unit', () => {
  const { buildVariantReviewPrompt } = require('../src/services/gemini');
  const base = { assetType: 'Event Landing Page', fieldName: 'Legal Line', variations: [{ index: 1, doorway: null, copy: 'Terms apply.' }] };

  const chars = buildVariantReviewPrompt({ ...base, charMax: 0, fieldType: 'text' });
  assert.match(chars, /Keep each option concise\./);
  assert.ok(!/Character limit: 0|limit: 0|0 per option/.test(chars), 'no zero ceiling asserted');

  const words = buildVariantReviewPrompt({ ...base, charMax: 0, fieldType: 'words' });
  assert.match(words, /Length is counted in WORDS, not characters\. Keep each option tight\./);
  assert.ok(!/up to 0 words|0 words per option/.test(words), 'no zero word ceiling either');
  // "null" appears legitimately further down (the output schema, "strategy = null"),
  // so check only the length line itself.
  const limitLine = words.split('\n').find((l) => /Length is counted in WORDS/.test(l));
  assert.ok(!/null/.test(limitLine), 'no interpolated null in the length line');
});

test('the DRAFT path treats char_max 0 as no limit — including on word fields', () => {
  const gem = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'gemini.js'), 'utf8');
  const { buildVariationsPrompt } = require('../src/services/gemini');

  // The character branches were already correct. Both WORD branches were not:
  // whoever wrote them assumed a word field always carries a ceiling.

  // 1. generateAssetDrafts' per-field line — the batch prompt that drafts most
  //    copy. Rendered "up to 0 WORDS (a word count, not characters)".
  // Bounded by the next statement rather than a byte count: a comment added above
  // the branches used to push them out of a fixed-width window and fail here for
  // a reason that had nothing to do with the guard.
  const lines = gem.slice(gem.indexOf('const fieldLines = fields'), gem.indexOf('const guidance = fieldGuidanceFor'));
  // `wordCeiling` was renamed `ceiling` when the character branch grew a floor and
  // needed the same guarded value. The NAME was never the point — the > 0 guard is.
  assert.match(lines, /const ceiling = Number\(f\.charMax\) > 0 \? Number\(f\.charMax\) : null/);
  assert.match(lines, /'no word limit — length is yours to judge; measured in WORDS, not characters'/);
  assert.ok(!/'up to '\}\$\{f\.charMax\}/.test(lines), 'the raw charMax is no longer interpolated');

  // 2. buildVariationsPrompt — worse: lengthClause returns null for a 0 ceiling,
  //    and the template literal put the string "null" straight in the prompt.
  const wordsNoLimit = buildVariationsPrompt({
    assetType: 'Demand Gen Nurture Email', fieldName: 'Offer Body 1', charMax: 0, fieldType: 'words',
    summary: 's', writerPrompt: 'w', doorways: ['Outcome', 'Contrast'],
  });
  assert.ok(!/\bnull\b/.test(wordsNoLimit), 'no interpolated null reaches the prompt');
  assert.match(wordsNoLimit, /Length is counted in WORDS, not characters, and this field has no word limit/);

  // A word field WITH a ceiling is unchanged.
  const wordsLimited = buildVariationsPrompt({
    assetType: 'Demand Gen Nurture Email', fieldName: 'Offer Body 1', charMax: 140, charMin: 50, fieldType: 'words',
    summary: 's', writerPrompt: 'w', doorways: ['Outcome', 'Contrast'],
  });
  assert.match(wordsLimited, /50-140 words.*EACH variation is held to this range\./s);

  // 3. The rest of the draft path was ALREADY correct — assert it stays that way.
  const clause = new Function(`${gem.match(/^function lengthClause[\s\S]*?\n\}/m)[0]}\nreturn lengthClause;`)();
  assert.strictEqual(clause(0, 'text', 0), null, 'no clause for an unlimited character field');
  assert.strictEqual(clause(0, 'words', 50), null, 'nor for an unlimited word field, floor or not');
  // generateFieldDraft falls back to prose rather than emitting a zero.
  assert.match(gem, /lengthClause\(charMax, fieldType, charMin\) \|\|\s*\n\s*'Keep it concise/);
  // The over-limit rewrite and the hard trim are both gated on a real ceiling, so
  // an unlimited field is never "corrected" for length.
  assert.match(gem, /const ceiling = Number\(charMax\) > 0 \? Number\(charMax\) : null;/);
  assert.match(gem, /if \(ceiling && copy\.length > ceiling\)/);
  assert.match(gem, /if \(copy && ceiling && copy\.length > ceiling\) copy = trimToCeiling/);
});

test('no ceiling is ever interpolated into a prompt without a > 0 guard', () => {
  // The whole bug class in one assertion: every site that writes a number into
  // prompt text must have proved it is non-zero first.
  const gem = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'gemini.js'), 'utf8');
  const interpolations = gem.split('\n')
    .map((l, i) => [i + 1, l])
    .filter(([, l]) => /\$\{(?:f\.)?(?:charMax|ceiling|wordCeiling|max)\}/.test(l));
  assert.ok(interpolations.length >= 6, 'found the interpolation sites');
  const src = gem.split('\n');
  for (const [lineNo, l] of interpolations) {
    // A ternary's guard often sits a line or two above its branches, so look at a
    // small window rather than the single line.
    const window = src.slice(Math.max(0, lineNo - 4), lineNo).join('\n');
    const guarded =
      /Number\((?:f\.)?charMax\) > 0/.test(window) ||       // guarded inline or just above
      /\$\{ceiling\}|\$\{wordCeiling\}|\$\{max\}/.test(l); // a name that is null-or-positive by construction
    assert.ok(guarded, `gemini.js:${lineNo} interpolates a ceiling with no > 0 guard: ${l.trim()}`);
  }
  // The three names above are only ever assigned through that guard.
  for (const decl of [
    /const ceiling = Number\(charMax\) > 0 \? Number\(charMax\) : null;/,
    /const ceiling = Number\(f\.charMax\) > 0 \? Number\(f\.charMax\) : null;/,
    /const max = Number\(charMax\) > 0 \? Number\(charMax\) : null;/,
  ]) {
    assert.match(gem, decl);
  }

  // The two ENFORCEMENT ceilings — the ones that reach trimToCeiling — come from
  // trimCeiling instead. Same > 0 guard, wrapped in a word-field check that can
  // only ever make the result null, so the name stays null-or-positive and every
  // interpolation above still holds. Asserted here so `const ceiling = …` can
  // never quietly become something unguarded.
  assert.match(gem, /function trimCeiling\(charMax, fieldType\) \{\n {2}if \(String\(fieldType \|\| ''\) === 'words'\) return null;\n {2}return Number\(charMax\) > 0 \? Number\(charMax\) : null;\n\}/);
  // Anchored to the start of a line so the commented-out original quoted in
  // generateFieldDraft's explanation is not counted as a fifth assignment.
  const assignments = gem.match(/^ *const ceiling = .*/gm) || [];
  for (const a of assignments) {
    assert.ok(
      /Number\((?:f\.)?charMax\) > 0 \? Number\((?:f\.)?charMax\) : null;$/.test(a) ||
        /trimCeiling\(charMax, fieldType\);$/.test(a),
      `ceiling assigned without a guard: ${a}`
    );
  }
  // Five now: the batch's per-field ceiling was `wordCeiling` until the character
  // branch grew a floor and needed the same guarded value under a name that no
  // longer claimed to be word-only.
  assert.strictEqual(assignments.length, 5, 'three prompt ceilings, two enforcement ceilings');
});

// --- A terminal Slack card cannot be reverted by a late write ----------------
// dbd3306 collapsed the whole flow onto one message ts, which removed the stray
// orphan messages it was meant to remove and created a worse failure: a late
// write now OVERWRITES the finished card instead of landing beside it. A real
// run went draft-complete → Open in Drive → back to "Building your document…",
// permanently.

test('a Slack redelivery of work already accepted never runs it again', () => {
  const lm = require('../src/liveMessage');
  lm._reset();
  const key = lm.deliveryKey('generate_first_draft', 'C1', 'TS1', 'DOC1');

  // The original delivery owns the work.
  assert.strictEqual(lm.claimDelivery(key, false), true, 'the first delivery runs');
  // A redelivery WHILE it runs is refused — this is the double-run that rebuilds
  // the doc and writes progress text over the card.
  assert.strictEqual(lm.claimDelivery(key, true), false, 'retry mid-run refused');
  // …and so is a second tap that is not a retry at all (a phone double-tap).
  assert.strictEqual(lm.claimDelivery(key, false), false, 'double-tap mid-run refused');

  // The run settles. THE KEY IS REMEMBERED, NOT FORGOTTEN — this is the whole
  // fix for the reported bug, where the redelivery landed AFTER completion.
  lm.releaseDelivery(key);
  assert.strictEqual(lm.claimDelivery(key, true), false, 'retry AFTER completion refused');

  // But a deliberate second click is not a retry, and must still work.
  assert.strictEqual(lm.claimDelivery(key, false), true, 'a real second click runs');
});

test('a retry of a delivery that never arrived is still honoured', () => {
  // The other half of the rule. Refusing every retry would silently drop a click
  // whose original request genuinely never reached the server — the user would
  // tap and nothing would happen, with no way to tell.
  const lm = require('../src/liveMessage');
  lm._reset();
  const key = lm.deliveryKey('plan_build', 'C1', 'TS1', 'PEND1');
  assert.strictEqual(lm.claimDelivery(key, true), true, 'first sighting is a retry → run it');
  assert.strictEqual(lm.claimDelivery(key, true), false, 'the next one is a duplicate');

  // Different button, message or target = different work, never deduped together.
  const keys = [
    lm.deliveryKey('plan_build', 'C1', 'TS1', 'PEND1'),
    lm.deliveryKey('generate_first_draft', 'C1', 'TS1', 'PEND1'),
    lm.deliveryKey('plan_build', 'C1', 'TS2', 'PEND1'),
    lm.deliveryKey('plan_build', 'C2', 'TS1', 'PEND1'),
    lm.deliveryKey('plan_build', 'C1', 'TS1', 'PEND2'),
  ];
  assert.strictEqual(new Set(keys).size, 5, 'every dimension is part of the key');
  // No key at all → never block the work.
  assert.strictEqual(lm.claimDelivery(null, true), true);
});

test('only the newest run may write to a message', () => {
  const lm = require('../src/liveMessage');
  lm._reset();
  // The guard is "newest run wins", NOT "terminal is final". Clicking Generate
  // First Draft on a doc-ready card legitimately drives a terminal card back to a
  // progress state, so a terminal flag would block a transition the user asked for.
  const first = lm.beginRun('C1', 'TS1');
  assert.strictEqual(lm.mayWrite('C1', 'TS1', first), true);
  const second = lm.beginRun('C1', 'TS1');
  assert.ok(second > first, 'sequences are monotonic per message');
  assert.strictEqual(lm.mayWrite('C1', 'TS1', second), true, 'the newest run writes');
  assert.strictEqual(lm.mayWrite('C1', 'TS1', first), false, 'the superseded run does not');

  // Runs on a DIFFERENT message are independent.
  assert.strictEqual(lm.mayWrite('C1', 'TS2', first), true);
  // An untagged write is never blocked, so adding the guard cannot break a path
  // that has not been taught about it.
  assert.strictEqual(lm.mayWrite('C1', 'TS1', undefined), true);
  assert.strictEqual(lm.mayWrite('C1', 'TS1', null), true);
  // No coordinates → no guard and no need for one.
  assert.strictEqual(lm.beginRun(null, 'TS1'), null);
  assert.strictEqual(lm.beginRun('C1', null), null);
});

test('updateLive drops a superseded write instead of sending it', async () => {
  const lm = require('../src/liveMessage');
  const { updateLive } = require('../src/services/slack');
  lm._reset();
  const older = lm.beginRun('C1', 'TS1');
  lm.beginRun('C1', 'TS1'); // a newer run takes the message

  const sent = [];
  const realFetch = global.fetch;
  global.fetch = async (url, opts) => {
    sent.push(JSON.parse(opts.body).text);
    return { ok: true, status: 200, json: async () => ({ ok: true }) };
  };
  try {
    const r = await updateLive('C1', 'TS1', 'Building your document…', undefined, 'xoxb-t', older);
    assert.deepStrictEqual(sent, [], 'nothing reached chat.update');
    assert.strictEqual(r.skipped, true, 'and the caller is told, rather than seeing a fake success');
  } finally {
    global.fetch = realFetch;
  }
});

test('every interactive handler that starts a run claims its delivery first', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'server.js'), 'utf8');
  // Slack's own header is what separates a redelivery from a deliberate re-click.
  assert.match(src, /const isRetry = !!req\.get\('X-Slack-Retry-Num'\)/);

  // Every action that kicks off a long fire-and-forget run is claimed, and every
  // claim is released in a finally (a run that throws is still a run that happened).
  for (const kind of ['plan_build', 'pick_build', 'generate_first_draft', 'regenerate_modal', 'plan_modal']) {
    assert.match(src, new RegExp(`deliveryKey\\('${kind}'`), `${kind} is claimed`);
  }
  // FIVE since the asset picker's build joined them — it is the same exposure:
  // a slow fire-and-forget run, and a pending record that survives until it
  // succeeds, so a redelivery would build a second doc.
  assert.strictEqual((src.match(/claimDelivery\([^)]*isRetry\)/g) || []).length, 5, 'all five pass the retry flag');
  assert.strictEqual((src.match(/\.finally\(\(\) => releaseDelivery\(/g) || []).length, 5, 'all five release');

  // The ack still goes out before any of this — Slack's 3s window is what forces
  // the async work that creates the retry in the first place.
  // `claimDelivery(` with the paren — the prose above the ack explains the rule
  // and naming it there is not a call.
  const handler = src.slice(src.indexOf("app.post('/slack/interactions'"));
  assert.ok(handler.indexOf("res.status(200).send('')") < handler.indexOf('claimDelivery('), 'ack first, then claim');
});

test('every writer to a live message carries its run sequence', () => {
  const wf = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackWorkflow.js'), 'utf8');
  const rv = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackReview.js'), 'utf8');
  // Every updateLive in the adapters passes a sequence. An unguarded one is the
  // hole the whole fix exists to close, so the count is asserted rather than
  // spot-checked.
  // Balanced-paren extraction: a call's own arguments contain calls
  // (copyCompleteBlocks(...), emojiBlocks([...])), so a non-greedy regex stops
  // inside them and reads a correct call as unguarded.
  const callsIn = (src) => {
    const out = [];
    let i = src.indexOf('updateLive(');
    while (i >= 0) {
      let depth = 0;
      let j = i + 'updateLive'.length;
      for (; j < src.length; j += 1) {
        if (src[j] === '(') depth += 1;
        else if (src[j] === ')') {
          depth -= 1;
          if (depth === 0) break;
        }
      }
      out.push(src.slice(i, j + 1));
      i = src.indexOf('updateLive(', j);
    }
    return out;
  };
  const calls = [...callsIn(wf), ...callsIn(rv)];
  assert.ok(calls.length >= 6, `found the writers (got ${calls.length})`);
  for (const c of calls) {
    assert.ok(/runSeq|beginRun\(/.test(c), `updateLive without a run sequence: ${c.replace(/\s+/g, ' ').slice(0, 90)}`);
  }
  assert.match(wf, /const runSeq = beginRun\(channel, messageTs\)/, 'the draft flow claims the clicked message');
  assert.match(wf, /let runSeq = live \? beginRun\(live\.channel, live\.ts\) : null/, 'and so does the resume flow');
});

// --- Slack microcopy: one punctuation rule ----------------------------------

test('the three progress lines are the same weight', () => {
  const wf = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackWorkflow.js'), 'utf8');
  const rv = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackReview.js'), 'utf8');
  // "Reviewing your copy…" was the only bolded one. Matched to the other two
  // rather than bolding those.
  assert.match(rv, /\$\{REVIEW_EMOJI\} Reviewing your copy…/);
  assert.ok(!/\*Reviewing your copy…\*/.test(rv), 'no longer bold');
  assert.match(wf, /const BUILDING_TEXT = `\$\{emoji\('quillio-scroll'\)\} Building your document…`/);
  assert.match(wf, /const progressText = `\$\{emoji\('quillio'\)\} \$\{progressMsg\}`/);
  for (const s of [wf, wf, rv]) assert.ok(!/\*Building your document…\*|\*\$\{progressMsg\}\*/.test(s));
});

test('in-progress states end in an ellipsis, terminal states in a period', () => {
  const wf = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackWorkflow.js'), 'utf8');
  const rv = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackReview.js'), 'utf8');
  const sl = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'slack.js'), 'utf8');
  const pb = fs.readFileSync(path.join(__dirname, '..', 'src', 'pendingBriefs.js'), 'utf8');

  // In progress → ellipsis.
  assert.match(wf, /Building your document…`/);
  assert.match(rv, /Reviewing your copy…'/);
  assert.match(rv, /Reviewing your copy…`/);

  // Terminal → a complete sentence with a period.
  // The noun branches on whether there IS a copy doc — a template-only brief
  // built a document, not a doc. The terminal period is what this test is about
  // and is on both branches.
  assert.match(wf, /Your \$\{doc \? 'doc' : 'document'\} is ready — \$\{primary\.title\}\.`/);
  assert.match(sl, /Saved to \$\{folderName\}\.`/);
  assert.match(pb, /These assets are not in your library: \$\{unknown\.join\(', '\)\}\.`/);
  assert.match(rv, /Review didn’t finish\.'/);
  assert.match(rv, /\*Review didn’t finish\*/, 'the block and its fallback use the same apostrophe');
  assert.match(rv, /d\/…`\.',/, 'the paste-a-link instruction is a punctuated sentence');

  // A HEADER BLOCK is a line of copy the reader takes as a sentence, so it is
  // punctuated as one. A BUTTON LABEL is a control, and a period on a button is
  // wrong. The two used to share a rule; they do not.
  // Whitespace-tolerant between the fields: the result card's header wraps onto
  // three lines now that its noun branches on whether there is a copy doc. The
  // claim is unchanged — every header block's text is a sentence.
  const headerBlocks = [...sl.matchAll(/type: 'header',?\s*text: \{\s*type: 'plain_text',\s*text: (`[^`]+`|"[^"]+"|'[^']+')/g)]
    .map((m) => m[1]);
  // Three since the asset picker card arrived with its own header.
  assert.strictEqual(headerBlocks.length, 3, 'all three header blocks found');
  for (const h of headerBlocks) {
    assert.ok(/\.(`|"|')$/.test(h), `a header block is a sentence: ${h}`);
  }
  assert.ok(sl.includes("text: `${emoji('quillio-doc-done')} Your ${templateOnly ? 'document' : 'doc'} is ready.`"));
  assert.ok(sl.includes("text: \"Here's how I read that brief.\""));

  // Button labels stay bare — asserted by name, and then swept so a new one
  // cannot arrive punctuated.
  for (const l of ['Generate First Draft', 'Skip for now', 'Open in Drive', 'Build the doc', 'Edit counts', 'Regenerate']) {
    assert.ok(sl.includes(`text: '${l}'`), `unpunctuated button label intact: ${l}`);
  }
  const buttons = sl.split('\n').filter((l) => /type: 'button'/.test(l) || /action_id:/.test(l));
  void buttons;
  const plainLabels = sl.match(/text: \{ type: 'plain_text', text: '[^']+'/g) || [];
  for (const b of plainLabels) {
    assert.ok(!/[.!?]'$/.test(b), `button label must not end in terminal punctuation: ${b}`);
  }
});

test('a review headline is a sentence on both surfaces', () => {
  const { qualitativeStatus } = require('../src/services/copyReview');
  // One function feeds Slack's review lead line AND the web's .review-status, so
  // the rule is applied at the source rather than twice at the edges.
  for (const [f, t] of [[0, 0], [0, 6], [1, 8], [3, 5], [5, 5]]) {
    const s = qualitativeStatus(f, t);
    assert.ok(/\.( ✨)?$/.test(s), `punctuated headline: ${JSON.stringify(s)}`);
  }
  const cr = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'copyReview.js'), 'utf8');
  // The no-copy early return used to carry its own copy of the string, free to
  // drift from the function that produces every other headline.
  assert.match(cr, /status: qualitativeStatus\(0, 0\)/);
  assert.ok(!/status: 'Nothing to review yet'/.test(cr), 'no second literal to drift');

  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'app.html'), 'utf8');
  assert.match(html, /\|\| 'Review complete\.'/, "the web's fallback headline follows the same rule");
});

test('craft.md carries no FACT-SHAPED example — a tripwire, not coverage', () => {
  // A TRIPWIRE. It cannot tell a good example from a bad one; it holds the line
  // on five specific strings that were each measured producing a false claim in
  // customer-facing copy. Re-adding any of them should fail loudly rather than
  // be rediscovered by a fifth A/B run.
  //
  // The rule they came from is in craft.md's own maintainer block (stripped
  // before the file reaches a prompt): an example WILL be reproduced, as syntax
  // and sometimes literally, so what matters is whether it demonstrates a FORM
  // (asserts nothing — free to reproduce) or a FACT (asserts a quantity,
  // duration, date, price or named deliverable — reproducing it is a false
  // claim the model cannot know is false).
  const craft = fs.readFileSync(path.join(__dirname, '..', 'craft.md'), 'utf8');
  const body = craft.replace(/<!--[\s\S]*?-->/g, ''); // the maintainer note names them on purpose

  const REMOVED = [
    ['Save 4 hours a week', 'a duration; §1.7 — implicated in the invented "in 60 seconds"'],
    ['3 ways', 'a quantity; §2.54 — reproduced as "3 practical frameworks"'],
    ['in 10 minutes', 'a duration; §2.54 — reproduced VERBATIM as an event arrival time'],
    ['Get the 2026 Benchmark', 'a named deliverable + a year; §2 — reproduced as "Get the 2026 Content Ops Benchmark" in 4 of 5 drafts'],
    ['Get the Guide', 'a named deliverable; §4 gloss — 4 of 5 drafts with NO reference material'],
  ];
  for (const [str, why] of REMOVED) {
    assert.ok(!body.includes(str), `fact-shaped example is back: ${JSON.stringify(str)} — ${why}`);
  }

  // THE CTA LIBRARY IS NOT COVERED BY THIS and must survive. It is a menu, not an
  // illustration: every entry sits under a heading naming the DESTINATION it is
  // valid for, so reaching one means first believing that destination exists.
  // The §4 gloss was the unconditioned one, and that is why it went alone.
  assert.match(body, /Approved CTA Library by Destination/);
  assert.match(body, /Gated content \(whitepaper, report, guide\)/);
  assert.match(body, /Download the Guide · Get the Report/);

  // FORM examples are the point of the distinction and must NOT be swept up.
  // They have been in the file just as long and have never produced anything.
  assert.match(body, /"We built this" not "this was built\."/);
  assert.match(body, /Start\s+where\s+the\s+work\s+is/);
});

test('craft.md rules headline terminal punctuation, universally', () => {
  const craft = fs.readFileSync(path.join(__dirname, '..', 'craft.md'), 'utf8');

  // A real doc came back with some generated headlines ending in a period and
  // some not, WITHIN one asset. That is craft, not a field limit, so the answer
  // is a rule the model reads rather than a per-field instruction.
  const head = craft.slice(craft.indexOf('## 2. Headlines'), craft.indexOf('## 3. Body Copy'));
  assert.match(head, /Terminal punctuation — apply this consistently, do not decide per field/);
  assert.match(head, /The default is \*\*no\s*\n?full stop\*\*/);
  assert.match(head, /No terminal period\*\* on ad headlines/);
  // A question mark still carries meaning; the rule removes the period only.
  assert.match(head, /question mark or exclamation mark still applies/);
  // Multi-sentence headlines DO take stops — the rule is not "never punctuate".
  assert.match(head, /Punctuate the period when the headline is two or more sentences/);
  // The failure that prompted this: mixed treatment inside one asset.
  assert.match(head, /Within one asset, be consistent/);
  // And the boundary — what is NOT a headline.
  assert.match(head, /Body copy, offer bodies, descriptions and legal lines are NOT headlines/);
  assert.match(head, /CTAs are not headlines either/);

  // THE CONTRADICTION THAT WAS THERE. The ultra-short example carried a period,
  // which is exactly the convention the rule rejects. That example is now GONE
  // for a different and larger reason — it was "Get the 2026 Benchmark", a
  // fully-formed offer for a document no client has, and the model reproduced it
  // as "Get the 2026 Content Ops Benchmark" in 4 of 5 drafts. The rule needs an
  // example (you cannot show a punctuation contrast without a string) so it now
  // uses one that asserts nothing.
  assert.match(head, /No setup\.\n/, 'the ultra-short bullet carries no example at all');
  // The line wraps in the file, so match whitespace-flexibly rather than pinning
  // the wrap point — reflowing the paragraph must not fail this.
  assert.match(head, /"Start\s+where\s+the\s+work\s+is" — not "Start\s+where\s+the\s+work\s+is\."/);
  assert.strictEqual((head.match(/"Start where the work is\."/g) || []).length, 1, 'punctuated only as the counter-example');

  // It sits OUTSIDE the mediums section, so gemini's per-asset slicing treats it
  // as universal craft and injects it for every asset — not just the one whose
  // medium happens to match.
  // Anchored on the level-2 HEADING, not the phrase: craft.md's own header
  // comment names the section too, and the parser keys on the heading (which is
  // why the injection check below is the real proof either way).
  const mediums = craft.search(/^##\s.*Writing Across Mediums/m);
  assert.ok(mediums > 0 && craft.indexOf('Terminal punctuation') < mediums, 'universal, not per-medium');
  const gemini = require('../src/services/gemini');
  for (const asset of ['LinkedIn Single Image Ad', 'Demand Gen Nurture Email', 'Battle Card', 'Event Landing Page']) {
    assert.match(gemini.buildCraftContext(asset), /Terminal punctuation/, `injected for ${asset}`);
  }
  // Copy review spans several assets and gets the union — still carries it.
  assert.match(gemini.buildCraftContext(['LinkedIn Single Image Ad', 'Demand Gen Nurture Email']), /Terminal punctuation/);

  // Nothing else in craft.md now shows a bare headline example ending in a
  // period. (Prose examples inside sentences — "this was built." — are body
  // copy illustrations, not headlines, and are left alone.)
  const byLength = head.slice(head.indexOf('**By length:**'), head.indexOf('**Terminal punctuation'));
  assert.ok(!/"[^"]+\."/.test(byLength), `a headline example still ends in a period: ${byLength}`);
});

// --- Editing an asset a tenant created ---------------------------------------
// Create shipped without an update or a delete, so a typo was permanent. Fields
// are edited BY ID — the ids the editor read has been returning since it shipped.

test('create and edit share ONE field allowlist, so they cannot drift', () => {
  const { normalizeNewAsset, normalizeAssetEdit } = require('../src/utils/assetInput');
  const body = {
    name: 'House Landing Page',
    group: 'Web',
    asset_direction: 'Plain.',
    // Every hostile key, at both levels, on both paths.
    id: 999, tenant_id: 'other', is_active: false, sort_order: -5,
    spec_type: 'enforced', spec_source: 'https://www.linkedin.com/help',
    fields: [{
      id: '42', field_name: 'Hero Headline', char_max: 70,
      spec_type: 'enforced', spec_source: 'https://www.linkedin.com/help', spec_version: 3,
      asset_type_id: 7, group_label: 'Nope',
    }],
  };
  const created = normalizeNewAsset(body).asset;
  const edited = normalizeAssetEdit(body, { selfName: 'House Landing Page' }).asset;

  // The asset shell is identical on both.
  assert.deepStrictEqual(Object.keys(created).sort(), ['asset_direction', 'fields', 'group', 'name']);
  assert.deepStrictEqual(Object.keys(edited).sort(), ['asset_direction', 'fields', 'group', 'name']);
  // The field differs ONLY by the id an edit needs to address a row.
  assert.deepStrictEqual(Object.keys(created.fields[0]).sort(),
    ['char_max', 'char_min', 'field_name', 'field_type', 'sort_order', 'spec_note']);
  assert.deepStrictEqual(Object.keys(edited.fields[0]).sort(),
    ['char_max', 'char_min', 'field_name', 'field_type', 'id', 'sort_order', 'spec_note']);
  assert.strictEqual(edited.fields[0].id, '42');
  // Neither can name the two authority columns, anywhere in the result.
  for (const a of [created, edited]) {
    assert.ok(!/spec_type|spec_source|spec_version|tenant_id|is_active|group_label/.test(JSON.stringify(a)));
  }
  // sort_order is the SUBMITTED ORDER on both, never a client-supplied number —
  // which is what makes reordering "move the row" rather than "trust the index".
  assert.strictEqual(created.fields[0].sort_order, 1);
  assert.strictEqual(edited.fields[0].sort_order, 1);

  // And it is literally one function: the source has a single field allowlist.
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'utils', 'assetInput.js'), 'utf8');
  assert.strictEqual((src.match(/field_name: fieldName,/g) || []).length, 1, 'one allowlist, not two');
  assert.strictEqual((src.match(/function normalizeFields/g) || []).length, 1);
});

test('an edit may keep its own name, and only its own', () => {
  const { normalizeAssetEdit } = require('../src/utils/assetInput');
  const ok = { fields: [{ field_name: 'H', char_max: 50 }] };
  const names = ['House Landing Page', 'Battle Card'];

  // Saving without renaming must not read as a duplicate of yourself.
  assert.deepStrictEqual(
    normalizeAssetEdit({ ...ok, name: 'House Landing Page' }, { existingNames: names, selfName: 'House Landing Page' }).errors,
    []
  );
  // Folded, so a dash/case variant of your own name is still yours.
  assert.deepStrictEqual(
    normalizeAssetEdit({ ...ok, name: 'house  landing page' }, { existingNames: names, selfName: 'House Landing Page' }).errors,
    []
  );
  // Somebody else's name is still a duplicate.
  assert.match(
    normalizeAssetEdit({ ...ok, name: 'Battle Card' }, { existingNames: names, selfName: 'House Landing Page' }).errors[0],
    /already have an asset type called "Battle Card"/
  );
  // A rename still meets every create rule — the instance-suffix one especially,
  // because googleDocs INSTANCE_HEADING_RE would read it as instance N of another
  // asset when the doc is re-parsed.
  assert.match(
    normalizeAssetEdit({ ...ok, name: 'Landing Page 2' }, { selfName: 'House Landing Page' }).errors[0],
    /ends in a number/
  );
  const { INSTANCE_SUFFIX_RE } = require('../src/utils/assetInput');
  const { parseAssetHeading } = require('../src/destinations/googleDocs');
  void parseAssetHeading;
  assert.ok(INSTANCE_SUFFIX_RE.test('Landing Page 2'), 'the two regexes agree on the shape');

  // A field id we never issued is not trusted — it becomes a NEW field rather
  // than a claim on a row.
  const { FIELD_ID_RE } = require('../src/utils/assetInput');
  for (const bad of ['1; DROP TABLE', '1 OR 1=1', '-1', '1.5', 'abc', '']) {
    assert.ok(!FIELD_ID_RE.test(bad), `not an id we issued: ${JSON.stringify(bad)}`);
  }
  const smuggled = normalizeAssetEdit(
    { name: 'X', fields: [{ id: '1; DROP TABLE copy_fields', field_name: 'H' }] },
    { selfName: 'X' }
  ).asset;
  assert.ok(!('id' in smuggled.fields[0]), 'a non-id is dropped, not passed through');
});

test('a seeded asset is read-only apart from is_active, decided by NAME', () => {
  const { isSeededAssetName } = require('../src/db/assets');
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');

  // Every bundled name is seeded, folded the way everything else folds.
  for (const a of DEFAULT_ASSETS) {
    assert.ok(isSeededAssetName(a.name), `${a.name} is seeded`);
    assert.ok(isSeededAssetName(a.name.toUpperCase()), 'case-folded');
  }
  assert.ok(isSeededAssetName('linkedin  single image ad'), 'whitespace-folded');
  assert.ok(!isSeededAssetName('House Landing Page'), 'a tenant creation is not');
  assert.ok(!isSeededAssetName(''), 'and neither is nothing');

  // WHY the name and not a stored column: services/specReview updates copy_fields
  // by asset NAME with no tenant filter, so the name is exactly what decides
  // whether a row is reachable by that cross-tenant write. A renamed seeded asset
  // would silently stop receiving platform-limit updates while its doc kept
  // rendering "Platform limit (LinkedIn)" beside a stale number.
  const spec = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'specReview.js'), 'utf8');
  const sql = spec.slice(spec.indexOf("'UPDATE copy_fields cf'"), spec.indexOf('RETURNING at.tenant_id'));
  assert.match(sql, /AND at\.name = \$/, 'specReview still matches on NAME');
  // No tenant PREDICATE — the statement deliberately rewrites every tenant's row
  // for this (asset, field), which is how a platform's changed limit reaches all
  // of them at once. (It RETURNS at.tenant_id, to report who was overwritten;
  // that is the opposite of filtering by it.)
  assert.ok(!/WHERE[\s\S]*tenant_id|AND\s+\S*tenant_id/.test(sql),
    'and still has no tenant filter — which is the whole reason for this rule');
  // It DOES filter on is_active, which is a different axis: no tenant predicate
  // (every tenant's row is rewritten) but no dead rows either (a retired asset
  // is invisible to every doc, so writing to it only pollutes the audit log).
  assert.match(sql, /AND at\.is_active/, 'and skips deactivated asset rows');

  // Enforced in the DB layer against the STORED row, not just the request: a
  // rename in the same call cannot walk past the check.
  const db = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');
  const fn = db.slice(db.indexOf('async function updateAssetType'), db.indexOf('// Asset toggles, BY ID'));
  assert.match(fn, /SELECT id, name FROM asset_types WHERE id = \$1 AND tenant_id = \$2 FOR UPDATE/);
  assert.match(fn, /const seeded = isSeededAssetName\(cur\.rows\[0\]\.name\)/, 'checked against the stored name');
  assert.ok(fn.indexOf('isSeededAssetName(cur.rows[0].name)') < fn.indexOf('UPDATE asset_types SET'),
    'refused BEFORE anything is written');
  // The default mode still refuses outright. A seeded asset's STRUCTURE — name,
  // field list, tiers — is what the cross-tenant write above reaches by, and
  // that has not been relaxed at all: only 'houseDefaultsOnly' gets past here,
  // and that path writes override columns and nothing else.
  assert.match(fn, /if \(seeded && mode !== 'houseDefaultsOnly'\)/);
  assert.match(fn, /return \{ ok: false, reason: 'seeded', name: cur\.rows\[0\]\.name \}/);
  assert.strictEqual(/function updateAssetType\(tenantId, assetTypeId, asset, \{ mode = 'full' \} = \{\}\)/.test(fn), true,
    "the default is 'full', so an existing caller that passes no mode still gets the refusal");
  // And the inverse: the reduced mode against a TENANT asset is refused too,
  // rather than silently dropping every rename and delete in the request.
  assert.match(fn, /if \(!seeded && mode === 'houseDefaultsOnly'\)/);
  assert.match(fn, /reason: 'not_seeded'/);

  // And the route reports it too, so the UI can say why — but the route is not
  // the guarantee.
  const route = fs.readFileSync(path.join(__dirname, '..', 'src', 'routes', 'settings.js'), 'utf8');
  assert.match(route, /if \(isSeededAssetName\(current\.name\)\)/);
  assert.match(route, /result\.reason === 'seeded'/, 'and honours the db layer even so');
});

// THE SECOND HALF OF THE GATE. The name rule says which ASSETS are structurally
// off-limits; this says which of a seeded asset's FIELDS a tenant may put their
// own number on. Getting it wrong is silent in both directions — a locked
// house_default is a feature that quietly does not work, an open enforced field
// is a tenant publishing an invented number under "Platform limit (LinkedIn)".
// THE DOC IS THE DISCOVERY PATH, deliberately instead of an onboarding step —
// and the sentence that does it must not become drafting instructions.
test('the house-default line reaches the doc and never reaches a prompt', () => {
  const {
    fieldHint, parseDoc, stripReaderOnlyLines, HOUSE_DEFAULT_LINE, HOUSE_DEFAULT_LINE_SET,
  } = require('../src/destinations/googleDocs');

  // It is in the doc.
  assert.strictEqual(fieldHint({ specType: 'house_default' }).text, HOUSE_DEFAULT_LINE);

  // It is not in the prompt. `notes` is prompt input and nothing else — it
  // becomes the field's `Field guidance:` (gemini.fieldGuidanceFor). "Set your
  // own in Settings" is addressed to the TENANT, not the writer, and on 144
  // seeded fields it would be the only guidance most of them carry.
  assert.strictEqual(stripReaderOnlyLines(HOUSE_DEFAULT_LINE), '');
  assert.strictEqual(stripReaderOnlyLines(HOUSE_DEFAULT_LINE_SET), '', 'both wordings');
  // The tenant's own note IS writing guidance and must survive intact.
  assert.strictEqual(
    stripReaderOnlyLines(`Lead with the outcome. ${HOUSE_DEFAULT_LINE}`),
    'Lead with the outcome.'
  );
  // A doc built before an override still strips after one — the wording changed
  // under it and the old sentence is still on the page.
  assert.strictEqual(
    stripReaderOnlyLines(`Lead with the outcome. ${HOUSE_DEFAULT_LINE_SET}`),
    'Lead with the outcome.'
  );
  // Position-independent: fieldHint always appends, but a doc is a document and
  // somebody will reorder the line by hand.
  assert.strictEqual(stripReaderOnlyLines(`${HOUSE_DEFAULT_LINE} Lead with it.`), 'Lead with it.');
  // An authority line is NOT stripped — it is a real constraint on the writing.
  const enf = 'Platform limit (LinkedIn). Stay within this count.';
  assert.strictEqual(stripReaderOnlyLines(enf), enf);
  assert.strictEqual(stripReaderOnlyLines(''), '');
  assert.strictEqual(stripReaderOnlyLines(null), '');

  // AND IT IS WIRED: parseDoc, the only producer of prompt-facing notes, applies
  // it. Asserted through the parser rather than the helper, because a helper
  // nothing calls is the failure this is guarding against.
  const doc = {
    body: { content: [
      { paragraph: { paragraphStyle: { namedStyleType: 'HEADING_2' },
        elements: [{ textRun: { content: 'Copy Assets\n' } }] } },
      { paragraph: { paragraphStyle: { namedStyleType: 'HEADING_3' },
        elements: [{ textRun: { content: 'Event Landing Page\n' } }] } },
      { paragraph: { paragraphStyle: { namedStyleType: 'NORMAL_TEXT' },
        elements: [{ textRun: { content: 'Hero Headline [70]', textStyle: { bold: true } } }] } },
      { paragraph: { paragraphStyle: { namedStyleType: 'NORMAL_TEXT' },
        elements: [{ textRun: {
          content: `Lead with the outcome. ${HOUSE_DEFAULT_LINE}`, textStyle: { italic: true },
        } }] } },
    ] },
  };
  const parsed = parseDoc(doc);
  const field = parsed.assets[0].fields[0];
  assert.strictEqual(field.fieldName, 'Hero Headline');
  assert.strictEqual(field.notes, 'Lead with the outcome.', 'the Settings sentence never leaves the doc');
});

// THE POINT OF THE OVERRIDE COLUMNS, stated against the two readers. If a
// tenant's number lived in char_max, the next seed-alignment migration would
// erase it — they match by asset NAME across every tenant with no tenant
// predicate and no value guard.
test('the reads take the override and leave the base column to the migrations', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');

  // THE PIPELINE READ resolves in SQL, so there is one number and no chance of a
  // caller forgetting which to prefer.
  const pipeline = src.slice(src.indexOf('async function getTenantAssets'), src.indexOf('// THE EDITOR READ'));
  assert.match(pipeline, /COALESCE\(char_min_override, char_min\) AS char_min/);
  assert.match(pipeline, /COALESCE\(char_max_override, char_max\) AS char_max/);
  assert.match(pipeline, /COALESCE\(spec_note_override, spec_note\) AS spec_note/);
  // spec_overridden is a THREE-COLUMN OR, not "does the effective value differ
  // from the seed". A tenant who deliberately re-typed Quillio's own number has
  // overridden it, and a later seed change must not drag them along.
  assert.match(pipeline, /char_min_override IS NOT NULL\s*\n\s*OR char_max_override IS NOT NULL\s*\n\s*OR spec_note_override IS NOT NULL\) AS spec_overridden/);

  // THE EDITOR READ carries BOTH, because the form prefills from the effective
  // value and the row has to be able to say what Quillio's was.
  const editor = src.slice(src.indexOf('async function getTenantLibrary'), src.indexOf('async function createAssetType'));
  assert.match(editor, /base_char_min: baseMin/);
  assert.match(editor, /base_char_max: baseMax/);
  assert.match(editor, /base_spec_note: baseNote/);
  // Per VALUE as well as per field: a reset control that could not tell a limit
  // from a note would throw away the half the tenant meant to keep.
  assert.match(editor, /overridden: \{ char_min: hasMin, char_max: hasMax, spec_note: hasNote \}/);

  // NEITHER READER WRITES. The protection is that the base column is left alone.
  for (const reader of [pipeline, editor]) {
    assert.ok(!/UPDATE |INSERT |DELETE /.test(reader), 'a read does not write');
  }
});

// CLAUDE.md: either deploy order is safe. Railway auto-deploys `main` on merge,
// so this code runs against a database without the override columns first.
test('deploy-before-migration: both reads degrade to "nothing is overridden"', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');

  // The pipeline read falls back to the EXACT pre-migration query and reports
  // false — which is true, not a guess.
  const pipeline = src.slice(src.indexOf('async function getTenantAssets'), src.indexOf('// THE EDITOR READ'));
  assert.match(pipeline, /if \(!isUndefinedColumn\(err\)\) throw err;/,
    'only 42703 — a permissions or connectivity failure still throws');
  assert.match(pipeline, /warnMissingSchema\(missing, 'getTenantAssets', err\)/);
  assert.match(pipeline, /false AS spec_overridden/);

  // TWO independent migrations add columns to this read now — the override trio
  // and fact_kind — so the fallback is a LIST tried most-complete first, not a
  // nested catch. Nesting was wrong the moment there were two: the overrides
  // shipped first and are already in production, so the realistic gap is
  // fact_kind ALONE, and a nested catch would have dropped the overrides it does
  // have on the way past.
  assert.match(pipeline, /\['copy_fields\.fact_kind', OVERRIDE_COLS, 'fact_kind'\]/);
  assert.match(pipeline, /\['copy_fields\.fact_kind', NO_OVERRIDE_COLS, 'fact_kind'\]/);
  assert.match(pipeline, /\['copy_fields\.char_max_override', OVERRIDE_COLS, 'NULL AS fact_kind'\]/);
  assert.match(pipeline, /\[null, NO_OVERRIDE_COLS, 'NULL AS fact_kind'\]/);
  // Every degraded variant reports the honest default rather than guessing.
  assert.match(pipeline, /NULL AS fact_kind/);
  // And a database missing BOTH still returns rows rather than throwing.
  assert.match(pipeline, /if \(!fieldsRes\) throw lastErr;/);

  // The editor read reads the overrides in their OWN query, so a missing column
  // costs an empty map rather than a four-way fallback across two migrations.
  const editor = src.slice(src.indexOf('async function getTenantLibrary'), src.indexOf('async function createAssetType'));
  assert.match(editor, /const overrides = new Map\(\);/);
  assert.match(editor, /warnMissingSchema\('copy_fields\.char_max_override', 'getTenantLibrary', err\)/);
  assert.match(editor, /if \(!isUndefinedColumn\(err\)\) throw err;/);
  // An empty map means every field reports its base value and nothing overridden
  // — which is exactly the pre-migration behaviour.
  assert.match(editor, /const ov = overrides\.get\(String\(row\.id\)\) \|\| \{\};/);
});

test('the two migrations: additive columns, and a backfill scoped by the app\'s own predicate', () => {
  const { STATEMENTS } = require('../scripts/migrateAddHouseDefaultOverrides');

  // Three nullable columns. NULL is load-bearing — it MEANS "no override" and is
  // what COALESCE falls through — so a NOT NULL DEFAULT would break the read.
  assert.strictEqual(STATEMENTS.length, 3);
  for (const [label, sql] of STATEMENTS) {
    assert.match(sql, /ADD COLUMN IF NOT EXISTS/, `${label} is idempotent`);
    assert.ok(!/NOT NULL|DEFAULT/.test(sql), `${label} stays nullable with no default`);
  }
  assert.deepStrictEqual(STATEMENTS.map(([l]) => l), [
    'copy_fields.char_min_override',
    'copy_fields.char_max_override',
    'copy_fields.spec_note_override',
  ]);

  const backfill = fs.readFileSync(
    path.join(__dirname, '..', 'scripts', 'migrateBackfillSeededSpecType.js'), 'utf8'
  );
  // SCOPED BY THE APP'S OWN PREDICATE, not a SQL name match: the script and
  // updateAssetType's gate then cannot drift, and it does not depend on
  // quillio_normalize_name() existing.
  assert.match(backfill, /const \{ isSeededAssetName \} = require\('\.\.\/src\/db\/assets'\)/);
  assert.match(backfill, /rows\.filter\(\(r\) => isSeededAssetName\(r\.asset_name\)\)/);
  assert.match(backfill, /rows\.filter\(\(r\) => !isSeededAssetName\(r\.asset_name\)\)/);
  // It writes ONLY the bundled rows, by id, guarded so a re-run is a no-op.
  assert.match(backfill, /SET spec_type = 'house_default'\s*\n\s*WHERE id = ANY\(\$1::bigint\[\]\) AND spec_type IS NULL/);
  // A tenant-authored field keeps its NULL. That is the whole reason for scoping:
  // NULL is what a custom field carries, and a custom field has no house default.
  // EVERY update in the script is id-scoped — comments stripped first, because
  // the header quotes migrateAddCopyFieldSpecType's original blanket UPDATE and
  // naming that statement is precisely what this script exists to narrow.
  const code = backfill.split('\n').filter((l) => !/^\s*\/\//.test(l)).join('\n');
  const updates = code.match(/UPDATE copy_fields[\s\S]*?`/g) || [];
  assert.strictEqual(updates.length, 1, 'exactly one write');
  assert.match(updates[0], /WHERE id = ANY\(\$1::bigint\[\]\)/, 'and it is scoped to the ids it printed');

  // Both are dry-run by default. A migration that writes on a bare invocation is
  // one somebody runs to "see what it would do".
  for (const s of [fs.readFileSync(path.join(__dirname, '..', 'scripts', 'migrateAddHouseDefaultOverrides.js'), 'utf8'), backfill]) {
    assert.match(s, /const COMMIT = process\.argv\.includes\('--commit'\)/);
    assert.match(s, /if \(COMMIT\) \{\s*\n\s*await client\.query\('COMMIT'\)/);
    assert.match(s, /await client\.query\('ROLLBACK'\);/);
    // Requiring the module must not connect to a database — this test does.
    assert.match(s, /if \(require\.main === module\)/);
  }
});

// The reduced submission's allowlist. Smaller than the create/edit one, and the
// smallness is the feature: there is no branch here that can express a rename,
// an insert, a reorder or a tier.
test('normalizeHouseDefaults accepts three values per field and cannot express anything else', () => {
  const { normalizeHouseDefaults, MAX_SPEC_NOTE, MAX_CHAR_LIMIT } = require('../src/utils/assetInput');

  const ok = normalizeHouseDefaults({
    // Everything below `fields` is ignored: there is no branch that reads it.
    name: 'Renamed', group: 'Web', asset_direction: 'do as I say',
    fields: [{
      id: '42', char_min: 10, char_max: 70, spec_note: 'Lead with the outcome.',
      field_name: 'Renamed Field', field_type: 'words', sort_order: 99,
      spec_type: 'enforced', spec_source: 'https://linkedin.com',
    }],
  });
  assert.deepStrictEqual(ok.errors, []);
  assert.deepStrictEqual(ok.fields, [
    { id: '42', char_min: 10, char_max: 70, spec_note: 'Lead with the outcome.' },
  ], 'exactly four keys, and three of them are values');

  // EVERY ROW MUST CARRY AN ID — there is no insert on this path, so a row
  // without one is refused rather than silently dropped. A form that appears to
  // add a field and does not is worse than one that says it cannot.
  assert.ok(normalizeHouseDefaults({ fields: [{ char_max: 70 }] }).errors.length > 0, 'no id');
  assert.ok(normalizeHouseDefaults({ fields: [{ id: 'abc', char_max: 70 }] }).errors.length > 0, 'not an id we issued');
  assert.ok(normalizeHouseDefaults({ fields: [{ id: '1' }, { id: '1' }] }).errors.length > 0, 'the same field twice');

  // undefined is "not offered, leave it alone"; null is "clear this one back to
  // Quillio's". They are different instructions and both survive as themselves.
  const partial = normalizeHouseDefaults({ fields: [{ id: '7', char_max: 50 }] });
  assert.deepStrictEqual(partial.fields[0], { id: '7', char_max: 50 }, 'char_min absent, not zeroed');
  const cleared = normalizeHouseDefaults({ fields: [{ id: '7', char_max: null }] });
  assert.strictEqual(cleared.fields[0].char_max, null, 'an explicit null reaches the write as null');

  // '' is the tenant DELETING the note — distinct from leaving the seed's alone.
  const emptied = normalizeHouseDefaults({ fields: [{ id: '7', spec_note: '' }] });
  assert.strictEqual(emptied.fields[0].spec_note, '', "'' survives as '' and is not folded to null");

  // reset is exclusive: nothing sent beside it is carried, because a request that
  // both sets and resets has no coherent reading.
  const reset = normalizeHouseDefaults({ fields: [{ id: '7', reset: true, char_max: 999 }] });
  assert.deepStrictEqual(reset.fields, [{ id: '7', reset: true }]);

  // The numeric rules, borrowed from the full path so the two agree.
  assert.ok(normalizeHouseDefaults({ fields: [{ id: '7', char_max: 'abc' }] }).errors.length > 0);
  assert.ok(normalizeHouseDefaults({ fields: [{ id: '7', char_max: -1 }] }).errors.length > 0);
  assert.ok(normalizeHouseDefaults({ fields: [{ id: '7', char_max: MAX_CHAR_LIMIT + 1 }] }).errors.length > 0);
  // THE PAIR IS NOT THIS FUNCTION'S TO JUDGE. It is pure, so it can only compare
  // the two numbers when both arrive — and since the form began sending a control
  // its own value alone, a minimum can arrive to be measured against a limit that
  // is only in the stored row. applyHouseDefaultOverrides owns the rule, where
  // every submission shape reaches the same test and the refusal names the field.
  // Asserted here so the delegation is deliberate rather than lost:
  assert.deepStrictEqual(
    normalizeHouseDefaults({ fields: [{ id: '7', char_min: 80, char_max: 70 }] }).errors, [],
    'a floor above the ceiling passes HERE and is refused at the write'
  );
  assert.deepStrictEqual(normalizeHouseDefaults({ fields: [{ id: '7', char_min: 80, char_max: 0 }] }).errors, []);
  assert.ok(normalizeHouseDefaults({ fields: [{ id: '7', spec_note: 'x'.repeat(MAX_SPEC_NOTE + 1) }] }).errors.length > 0);

  // Nothing at all is an error, not a silent success.
  assert.ok(normalizeHouseDefaults({ fields: [] }).errors.length > 0);
  assert.ok(normalizeHouseDefaults(null).errors.length > 0);
});

test('the tier gate: house_default and NULL are the tenant\'s, enforced and recommended are not', () => {
  const { isTenantEditableTier } = require('../src/db/assets');

  assert.ok(isTenantEditableTier('house_default'), 'the tier this whole change exists for');
  // NULL is OPEN: it renders identically to house_default (specTypeLine), the
  // seed gives the same field house_default, and EVERY tenant-authored field is
  // NULL by construction — createAssetType never writes spec_type. Locking it
  // would freeze custom assets, which have always been fully editable.
  assert.ok(isTenantEditableTier(null), 'null — a tenant-authored field');
  assert.ok(isTenantEditableTier(undefined), 'absent reads as null');
  assert.ok(isTenantEditableTier(''), 'and so does empty');

  assert.ok(!isTenantEditableTier('enforced'), 'the platform decides');
  assert.ok(!isTenantEditableTier('recommended'), 'someone measured it');

  // AN UNRECOGNISED TIER IS LOCKED. An allowlist, not a pair of !== checks: a
  // fourth tier would only ever be added to carry some authority, so it must be
  // refused by default and let in on purpose. Failing closed on the authority
  // axis is the entire reason this gate exists.
  for (const unknown of ['platform_enforced', 'observed_practice', 'HOUSE_DEFAULT', 'house default', 'anything']) {
    assert.ok(!isTenantEditableTier(unknown), `${unknown} is locked until someone says otherwise`);
  }

  // The seeded library's three tiers are exactly the three this reasons about.
  // A fourth appearing in the seed without a decision here fails right now.
  const { DEFAULT_ASSETS } = require('../src/data/defaultAssets');
  const tiers = new Set();
  for (const a of DEFAULT_ASSETS) for (const f of a.fields) tiers.add(f.spec_type);
  assert.deepStrictEqual([...tiers].sort(), ['enforced', 'house_default', 'recommended']);
});

// The write itself. Everything a seeded asset keeps, kept — asserted against the
// source, because each of these is a way the structural rule could leak.
test('the house-default write sets overrides only, on permitted tiers only, from the STORED row', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');
  const fn = sliceBetween(src, 'async function applyHouseDefaultOverrides', '// UPDATE one asset the tenant owns');
  assert.ok(fn.length > 500, 'found the function');

  // THE TIER COMES FROM POSTGRES, NEVER THE REQUEST. The client sends whatever
  // it likes; a submitted spec_type must not be able to unlock a field.
  assert.match(fn, /SELECT id, field_name, spec_type, spec_note, char_min, char_max,/);
  assert.match(fn, /FROM copy_fields WHERE asset_type_id = \$1/);
  assert.match(fn, /isTenantEditableTier\(tierById\.get\(id\)\)/);
  assert.ok(!/field\.spec_type|submitted\.spec_type/.test(fn), 'the submission cannot name a tier');

  // OVERRIDE COLUMNS ONLY. Not one base column is written — that is what keeps a
  // seed-alignment migration and specReview correct without knowing this exists.
  //
  // Asserted at `put`, which is where the value UPDATE's column list is actually
  // decided — the SQL interpolates `sets`, so no column name is literal in it and
  // scanning the statement would find nothing either way. Scanning the whole
  // function instead is what this used to do, and it broke the moment the pair
  // check compared `field.char_min === null`: "char_min =" is a substring of
  // "char_min ===". A read of a base column is not a write of one.
  const puts = (fn.match(/put\('([a-z_]+)'/g) || []).sort();
  assert.deepStrictEqual(puts, [
    "put('char_max_override'",
    "put('char_min_override'",
    "put('spec_note_override'",
  ], 'the only columns this function can write are the three overrides');
  const updates = fn.match(/UPDATE copy_fields[\s\S]*?`/g) || [];
  assert.ok(updates.length >= 2, 'found the reset and the value UPDATE');
  for (const u of updates) {
    for (const base of ['char_min =', 'char_max =', 'spec_note =', 'field_name =', 'sort_order =', 'field_type =']) {
      assert.ok(!u.includes(base), `no base column inside an UPDATE (${base})`);
    }
  }
  // No authority column inside any UPDATE. spec_type appears in this function
  // exactly once, in the SELECT that READS the gate — checking the whole body
  // would be checking that, which is the opposite of what matters.
  for (const u of updates) {
    assert.ok(!/spec_type|spec_source|spec_version/.test(u), 'no authority column in an UPDATE');
  }

  // NO INSERT, NO DELETE. A seeded asset's field LIST is part of what specReview
  // reaches by name, so it cannot grow or shrink through this path.
  assert.ok(!/INSERT INTO copy_fields/.test(fn), 'no insert');
  assert.ok(!/DELETE FROM copy_fields/.test(fn), 'no delete');
  // An unknown id names nothing here — it is skipped, NOT treated as a new field.
  assert.match(fn, /if \(!id \|\| !tierById\.has\(id\)\) \{\s*\n\s*skipped\+\+;/);

  // Reset is all three columns at once, so a half-reset row cannot exist.
  const reset = fn.match(/if \(field\.reset === true\)[\s\S]*?continue;/)[0];
  assert.match(reset, /char_min_override = NULL, char_max_override = NULL, spec_note_override = NULL/);

  // Scoped to the asset as well as the id, like every other field write here.
  assert.match(fn, /WHERE id = \$\$\{params\.length - 1\} AND asset_type_id = \$\$\{params\.length\}/);
});

// === Collateral overrides: a value nobody chose, pinned forever ==============
//
// An override column is not merely "the tenant's value" — it is a value no
// future write can move. Every spec correction writes the BASE column by asset
// name with no tenant predicate, and the reads resolve COALESCE(override, base),
// so a field carrying an override is permanently detached from every correction
// that will ever be made to it. Nothing surfaces that.
//
// The house-defaults form used to write three of them for every one the tenant
// changed: dirtiness was tracked per ROW, and a dirty row posted all three of its
// values. Changing a limit pinned the minimum and the note as well. On a field
// whose seed carries no note the note collateral was '', submitted by a collapsed
// textarea nobody opened — and '' is not NULL, so the row began reporting itself
// overridden and the document began saying "yours, set in Settings".
//
// Two halves, tested separately because they fail separately: the client sends
// only what fired, and the server refuses to store a value that says nothing.

// A stand-in for the transaction's client. Records every statement, answers the
// one SELECT with the rows given, and reports one row affected by an UPDATE.
function houseTxnClient(rows) {
  const calls = [];
  return {
    calls,
    updates: () => calls.filter((c) => /UPDATE copy_fields/.test(c.sql)),
    query: async (sql, params) => {
      calls.push({ sql, params });
      if (/^\s*SELECT id, field_name/.test(sql)) return { rows, rowCount: rows.length };
      return { rows: [], rowCount: 1 };
    },
  };
}

// One stored copy_fields row as applyHouseDefaultOverrides reads it. The default
// is the row this was found on: LinkedIn Single Image Ad / Graphic Headline,
// seeded ['Graphic Headline', 0, 70, 'Graphic Copy'] — house_default, no note.
function houseStoredRow(over) {
  return Object.assign({
    id: '7',
    field_name: 'Graphic Headline',
    spec_type: 'house_default',
    spec_note: null,
    char_min: 0,
    char_max: 70,
    eff_min: 0,
    eff_max: 70,
  }, over);
}

test('an empty note over a seed that has none is stored as no override at all', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  const client = houseTxnClient([houseStoredRow()]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', spec_note: '' }]);

  assert.strictEqual(res.ok, true);
  const upd = client.updates();
  assert.strictEqual(upd.length, 1, 'one write');
  assert.match(upd[0].sql, /SET spec_note_override = \$1 WHERE/);
  assert.strictEqual(upd[0].params[0], null,
    "'' deletes nothing when the seed gives no note, so it is not an override");
});

test('an empty note over a SEEDED note is still the tenant deleting it', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  // The twelve Litmus email fields are this shape — house_default, and carrying a
  // note. A general '' -> NULL fold would silently restore the note here.
  const client = houseTxnClient([houseStoredRow({ spec_note: 'Front-load the first 40 characters.' })]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', spec_note: '' }]);

  assert.strictEqual(res.ok, true);
  assert.strictEqual(client.updates()[0].params[0], '', 'the deletion survives');
});

test('only the values the tenant touched are written', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  const client = houseTxnClient([houseStoredRow()]);
  await applyHouseDefaultOverrides(client, 99, [{ id: '7', char_max: 60 }]);

  const upd = client.updates()[0];
  assert.match(upd.sql, /SET char_max_override = \$1 WHERE/);
  assert.ok(!/char_min_override/.test(upd.sql), 'the untouched minimum is not pinned');
  assert.ok(!/spec_note_override/.test(upd.sql), 'the untouched note is not pinned');
});

test('the min/max pair is checked against the values in force, not against the request', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  // normalizeHouseDefaults compares the two numbers only when both arrive, which
  // the form used to guarantee. Now a control sends its own value alone, so the
  // stored half is the only thing the submitted half can be checked against.
  const client = houseTxnClient([houseStoredRow({ eff_min: 40, eff_max: 60 })]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', char_max: 30 }]);

  assert.strictEqual(res.ok, false);
  assert.strictEqual(res.reason, 'range');
  assert.strictEqual(res.field, 'Graphic Headline', 'named by field, not by position');
  assert.deepStrictEqual([res.min, res.max], [40, 30]);
  assert.strictEqual(client.updates().length, 0, 'nothing is written on a refusal');
});

test('the pair refusal is the SAME refusal when both halves arrive', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  // This case used to be caught by normalizeHouseDefaults, which could only see
  // it when both numbers were in the request. The rule moved here rather than
  // being written in two places — so the coverage moves with it, and a tenant who
  // edits both halves gets the field's own name instead of "Field 3".
  const client = houseTxnClient([houseStoredRow()]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', char_min: 80, char_max: 70 }]);

  assert.strictEqual(res.reason, 'range');
  assert.strictEqual(res.field, 'Graphic Headline');
  assert.deepStrictEqual([res.min, res.max], [80, 70]);
});

test('clearing one half of the pair resolves to the SEED, not to the override it replaces', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  // 40 is in force over a seed of 0. An explicit null CLEARS that override, so 0
  // is what will stand — and a new maximum of 30 is legal. Resolving against the
  // 40 that is on its way out would refuse an edit that is fine.
  const client = houseTxnClient([houseStoredRow({ char_min: 0, eff_min: 40, eff_max: 60 })]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', char_min: null, char_max: 30 }]);

  assert.strictEqual(res.ok, true);
  assert.strictEqual(client.updates().length, 1);
});

test('char_max 0 is "no limit", so no floor can be above it', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  const client = houseTxnClient([houseStoredRow({ eff_min: 40 })]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', char_max: 0 }]);

  assert.strictEqual(res.ok, true, 'mirrors the rule normalizeHouseDefaults applies');
});

test('a locked tier is skipped BEFORE the pair check, so it cannot refuse a save', async () => {
  const { applyHouseDefaultOverrides } = require('../src/db/assets');
  // A mixed bundled asset posts its enforced rows too. One of them carrying a
  // pair the tenant cannot change must not turn into a 400 about somebody else's
  // field — it is `locked`, which is what that counter has always meant.
  const client = houseTxnClient([houseStoredRow({ spec_type: 'enforced', eff_min: 40, eff_max: 60 })]);
  const res = await applyHouseDefaultOverrides(client, 99, [{ id: '7', char_max: 30 }]);

  assert.strictEqual(res.ok, true);
  assert.strictEqual(res.locked, 1);
  assert.strictEqual(client.updates().length, 0);
});

// The client half, RUN rather than matched. `readRow` decides what goes on the
// wire, and the defect was a missing condition inside it — which no string test
// can see. This lifts the shipped function out of settings.html and calls it.
//
// It is still not a browser: it says what the function returns for a given set of
// flags, not that the flags get set by the right events. Those three listeners
// are asserted structurally below, and the device remains the test for the page.
test('the house form sends only the controls that fired', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  const houseRow = sliceBetween(src, "function libHouseRow(f, prevSource) {", "function libOpenHouseForm(");
  // The two-line anchor matters: the LOCKED branch above assigns wrap.readRow too,
  // on one line, and a one-line anchor finds that one first.
  const readRow = sliceBetween(houseRow, 'wrap.readRow = function () {\n        if (doReset)', '      return wrap;');
  const run = new Function('f', 'touched', 'doReset', 'min', 'max', 'note',
    `var wrap = {};\n${readRow}\nreturn wrap.readRow();`);

  const box = (v) => ({ value: v });
  const f = { id: '7' };
  const nothing = { char_min: false, char_max: false, spec_note: false };
  const maxOnly = { char_min: false, char_max: true, spec_note: false };
  const noteOnly = { char_min: false, char_max: false, spec_note: true };

  assert.strictEqual(run(f, nothing, false, box('0'), box('70'), box('')), null,
    'an untouched row is not sent at all');

  const row = run(f, maxOnly, false, box('0'), box('60'), box(''));
  assert.deepStrictEqual(row, { id: '7', char_max: 60 });
  assert.ok(!('char_min' in row), 'the untouched minimum is not pinned');
  assert.ok(!('spec_note' in row),
    'the collapsed note box the tenant never opened contributes nothing');

  assert.deepStrictEqual(run(f, noteOnly, false, box('0'), box('70'), box('')),
    { id: '7', spec_note: '' },
    'emptying a note box IS sent — that is a deletion, and the server decides what it means');

  assert.deepStrictEqual(run(f, maxOnly, true, box('0'), box('60'), box('')),
    { id: '7', reset: true }, 'reset still wins over values');

  // Each control marks its own key, and no row-level flag survives to
  // reintroduce the defect by accident.
  assert.match(houseRow, /min\.addEventListener\('input', function \(\) \{ touched\.char_min = true; \}\)/);
  assert.match(houseRow, /max\.addEventListener\('input', function \(\) \{ touched\.char_max = true; \}\)/);
  assert.match(houseRow, /note\.addEventListener\('input', function \(\) \{ touched\.spec_note = true; \}\)/);
  assert.ok(!/\bdirty\b/.test(houseRow), 'the row-level dirty flag is gone');
});

test('a pair refusal is a 400 that names the field, not the generic 404', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'routes', 'settings.js'), 'utf8');
  const branch = sliceBetween(src, "if (!hResult.ok && hResult.reason === 'range')", 'if (!hResult.ok) {');
  assert.match(branch, /status\(400\)/);
  assert.match(branch, /\$\{hResult\.field\}/, 'the message names the field');
  assert.match(branch, /\$\{hResult\.min\}[\s\S]*\$\{hResult\.max\}/);
});

test('the redundant-override repair only ever writes NULL, over a base it equals', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'migrateClearRedundantOverrides.js'), 'utf8');

  assert.match(src, /const COMMIT = process\.argv\.includes\('--commit'\)/, 'dry run unless asked');
  const updates = src.match(/UPDATE copy_fields[\s\S]*?`/g) || [];
  assert.strictEqual(updates.length, 1, 'one UPDATE, driven by the column table');
  assert.match(updates[0], /SET \$\{col\} = NULL/, 'it can only ever write NULL');

  // Each test is an equality against the BASE column. A bare IS NOT NULL here
  // would clear the tenant's real values — the thing the columns exist to hold.
  assert.match(src, /cf\.char_min_override = cf\.char_min/);
  assert.match(src, /cf\.char_max_override = cf\.char_max/);
  // '' over an absent base and 'x' over a base of 'x' are one rule: the override
  // says what the base already says. '' over a base that HAS a note is DISTINCT
  // from it and is not matched, which is what preserves a real deletion.
  assert.match(src, /NULLIF\(cf\.spec_note_override, ''\) IS NOT DISTINCT FROM NULLIF\(cf\.spec_note, ''\)/);
});

test('the update writes six columns, by id, in one transaction', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');
  const fn = src.slice(src.indexOf('async function updateAssetType'), src.indexOf('// Asset toggles, BY ID'));

  // The field UPDATE names the same six columns the create INSERT does — and
  // neither authority column, so an edit can neither SET nor CLEAR them.
  const upd = fn.match(/UPDATE copy_fields[\s\S]*?WHERE id = \$7 AND asset_type_id = \$8/)[0];
  assert.ok(!/spec_type|spec_source|spec_version/.test(upd), 'no spec claim in the field UPDATE');
  assert.match(upd, /field_name = \$1, char_min = \$2, char_max = \$3, field_type = \$4,\s*\n?\s*sort_order = \$5, spec_note = \$6/);
  // Scoped to the asset as well as the id, so an id from another asset cannot be
  // steered into this one.
  assert.match(upd, /WHERE id = \$7 AND asset_type_id = \$8/);

  // Reconcile by id: update what is owned, insert what has none, delete the rest.
  assert.match(fn, /SELECT id FROM copy_fields WHERE asset_type_id = \$1/);
  assert.match(fn, /const id = field\.id && owned\.has\(String\(field\.id\)\) \? String\(field\.id\) : null/);
  assert.match(fn, /DELETE FROM copy_fields WHERE asset_type_id = \$1 AND id = ANY\(\$2::bigint\[\]\)/);

  // One transaction — a half-applied edit is a library shape nobody asked for.
  assert.match(fn, /await client\.query\('BEGIN'\)/);
  assert.match(fn, /await client\.query\('COMMIT'\)/);
  assert.match(fn, /ROLLBACK/);
  assert.match(fn, /client\.release\(\)/);

  // Cross-tenant answers not_found, never forbidden — a 403 would confirm the id.
  assert.match(fn, /return \{ ok: false, reason: 'not_found' \}/);
});

test('the update route is session-scoped and answers 404 across tenants', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'routes', 'settings.js'), 'utf8');
  // Ends at the TEMPLATE routes below it, which are a separate feature with
  // their own tests — the old anchor (GET /workspace) now swallows them.
  const route = src.slice(
    src.indexOf("'/api/settings/library/asset/:id'"),
    src.indexOf('--- Template documents')
  );
  assert.match(route, /settingsWriteLimiter, requireAuth/, 'rate-limited and auth-gated');
  assert.match(route, /req\.user && req\.user\.tenant_id/, 'tenant from the session');
  // The only thing taken from the URL is the id, and it is digit-checked.
  assert.match(route, /req\.params\.id/);
  assert.match(route, /\/\^\\d\+\$\/\.test\(assetId\)/);
  // EVERY req.body reaches an allowlist and nothing else. Two now, because the
  // route serves two shapes — the full edit for a tenant asset, the reduced
  // house-default submission for a seeded one — and both are allowlisted. The
  // count is asserted against the number of allowlist calls rather than a
  // literal, so adding a third shape without a normalizer fails here.
  const bodyUses = (route.match(/req\.body/g) || []).length;
  const allowlisted = (route.match(/normalize(?:AssetEdit|HouseDefaults)\(req\.body/g) || []).length;
  assert.strictEqual(bodyUses, allowlisted, 'every req.body use is an allowlist argument');
  assert.strictEqual(bodyUses, 2, 'the full edit and the house-default submission');
  assert.match(route, /normalizeAssetEdit\(req\.body/);
  assert.match(route, /normalizeHouseDefaults\(req\.body/);
  // Someone else's id is a 404, the same shape a missing one gets.
  assert.match(route, /status\(404\)/);
  assert.match(route, /status\(403\)/, 'a seeded asset with no house default is 403 — it exists, it is just not yours to change');
  assert.match(route, /err\.code === '23505'/);
  assert.match(route, /status\(409\)/);
  // Nothing else in the router updates an asset type. Two CALLS now — the full
  // edit and the house-default one — but both are inside this one route slice,
  // which is what the assertion is actually about.
  assert.strictEqual((src.match(/updateAssetType\(/g) || []).length, 2, 'two calls in the whole router');
  assert.strictEqual((route.match(/updateAssetType\(/g) || []).length, 2, 'and both are in this route');
});

// BOTH OF THESE ARE REGRESSIONS THE SUITE DID NOT CATCH. They were found by
// loading the page in a browser, which is the only thing that tests public/*.html
// (CLAUDE.md: "the device is the test"). These assertions are structural — the
// suite still executes no JS — so they pin the SHAPE that was wrong, not the
// behaviour. Treat them as a tripwire, not as coverage.
test('the house-default form sends only the rows the tenant touched', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  const form = html.slice(html.indexOf('--- Set your own limits on a BUNDLED asset'), html.indexOf('--- Create an asset type'));
  assert.ok(form.length > 500, 'found the reduced form');

  // WHAT WENT WRONG. The form posted every rendered row, so saving ONE changed
  // number wrote an override to every house_default field of the asset — each
  // equal to the seed's own value, so nothing looked different on screen — and
  // silently detached all of them from every future seed update. Confirmed on a
  // real Postgres: editing Graphic Headline alone logged "3 changed" and left
  // Subhead and CTA Button pinned. That is the exact failure the override
  // columns exist to prevent, arriving through the front door.
  //
  // AND THEN THE SAME THING ONE LEVEL DOWN, which this row-level assertion could
  // not see: a dirty row still posted all THREE of its values, so changing a
  // limit pinned the minimum and the note as well. The flag is per value now.
  // What it returns for a given set of flags is exercised for real in "the house
  // form sends only the controls that fired"; these stay structural.
  assert.match(form, /var touched = \{ char_min: false, char_max: false, spec_note: false \};/);
  assert.match(form, /if \(!touched\.char_min && !touched\.char_max && !touched\.spec_note\) return null;/,
    'an untouched row is not sent');
  // A reset is an explicit act and IS sent, even though nothing was typed.
  assert.ok(form.indexOf('if (doReset) return { id: f.id, reset: true };')
    < form.indexOf('if (!touched.char_min'),
    'reset is checked before the touched gate, so it survives it');
  // And the caller drops the nulls rather than posting them.
  assert.match(form, /if \(row\) fields\.push\(row\);/);
  assert.match(form, /if \(fields\.length === 0\) \{ close\(\); return; \}/,
    'nothing touched → no request at all');
});

test('a locked row in the house-default form renders no control at all', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  const form = html.slice(html.indexOf('--- Set your own limits on a BUNDLED asset'), html.indexOf('--- Create an asset type'));

  // WHAT WENT WRONG. Locked rows were drawn as DISABLED INPUTS at 0.55 opacity.
  // On a phone, against this card's light background, they read as enabled — so
  // the first thing a tenant does on an enforced field is tap a control that can
  // never accept anything. "Dimmed, not hidden" is still right about the ROW (the
  // paid-social assets are mixed and a half list reads as broken), but a row is
  // kept honest by showing its VALUE, not a control that refuses input.
  const locked = form.slice(form.indexOf('if (!editable) {'), form.indexOf('var ctl = el('));
  assert.ok(locked.length > 100, 'found the locked branch');
  for (const control of ["createElement('input')", "createElement('textarea')", "createElement('select')"]) {
    assert.ok(!locked.includes(control), `a locked row builds no ${control}`);
  }
  assert.match(locked, /lib-fstatic/, 'it renders the value as text');
  assert.match(locked, /wrap\.readRow = function \(\) \{ return null; \};/, 'and is never posted');
  // The locked branch returns BEFORE any control is built, so a control cannot be
  // added above it and reach a locked row by accident.
  assert.ok(form.indexOf('if (!editable) {') < form.indexOf("var min = document.createElement('input')"));

  // field_type stays a real, DISABLED control on an editable row — shown rather
  // than omitted, and styled inert so it does not read as a dropdown failing to
  // open (no chevron, flat fill).
  assert.match(form, /var unitWrap = el\('span', 'lib-funit locked'\);/);
  assert.match(form, /unit\.disabled = true;/);
  assert.match(html, /\.lib-funit\.locked::after \{ display: none; \}/, 'no chevron on the inert unit');
  assert.match(html, /\.lib-funit\.locked select \{ background: rgba\(26,26,46,0\.05\)/);
});

test('removing an asset is is_active, and the UI says what that means', () => {
  // Five tables reference asset_types(id) with no ON DELETE, so the row cannot
  // go anywhere. is_active ALREADY means everything "deleted" would mean — a
  // brief cannot ask for it and it never reaches a doc — so there is one state,
  // not two, and the UI's job is to say so rather than to invent a difference.
  const db = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');
  assert.ok(!/DELETE FROM asset_types/.test(db), 'no hard delete of an asset type anywhere');

  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  const form = html.slice(html.indexOf('--- Create an asset type'), html.indexOf('async function libEnsureLoaded'));
  assert.match(form, /Remove this asset type/);
  // It is the SAME write the toggle makes.
  assert.match(form, /'\/api\/settings\/library\/active'[\s\S]{0,300}active: false/);
  // And it explains the state rather than implying a second one.
  assert.match(form, /Removing an asset type switches it off/);
  assert.match(form, /Docs you already built keep their copy/);
  assert.match(form, /switch it back on any time/);
});

test('the edit form warns before a rename, not after', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  const form = html.slice(html.indexOf('--- Create an asset type'), html.indexOf('async function libEnsureLoaded'));

  // Confirmed against a real Postgres: after a rename, getAssetDirections no
  // longer matches the OLD heading, so re-drafting a doc built under it silently
  // loses the asset's creative direction. Nothing errors — which is exactly why
  // the warning has to appear at the moment the name is being changed.
  assert.match(form, /nameI\.addEventListener\('input'/);
  assert.match(form, /Renaming affects new docs only/);
  // Escaped in the source, since the string is single-quoted.
  assert.match(form, /won\\'t pick up this asset\\'s creative direction any more/);
  // Not repeated as a toast afterwards — that would be a notification about a
  // decision already made.
  assert.ok(!/showToast/.test(form), 'no post-hoc toast');

  // The server says it too, for API callers.
  const route = fs.readFileSync(path.join(__dirname, '..', 'src', 'routes', 'settings.js'), 'utf8');
  assert.match(route, /renamed = normalize\(current\.name\) !== normalize\(asset\.name\)/);
  assert.match(route, /won't pick up this asset's creative direction if you re-draft them/);

  // ONE form serves both create and edit, so an edit cannot drift into a
  // different set of controls from the one a create was tested against.
  assert.match(form, /function libOpenForm\(existing, host, onClose\)/);
  assert.match(form, /isEdit \? 'Save changes' : 'Create asset type'/);
  assert.match(form, /isEdit \? '\/api\/settings\/library\/asset\/' \+ existing\.id : '\/api\/settings\/library\/asset'/);
  // Prefilled rows are MANUAL rows, so the paste box — which owns only what it
  // made — can never overwrite the tenant's existing fields.
  assert.match(form, /if \(isEdit\) addRows\(existing\.fields \|\| \[\]\)/);
  assert.match(form, /Anything you paste is ADDED below/);

  // The Edit button renders only where the SERVER said editable, and the server
  // re-checks — the button is a convenience, never the rule. TWO flags now, and
  // they open different forms: `editable` (a tenant asset) the full one,
  // `houseEditable` (a bundled asset with a house_default field) the reduced one.
  const card = html.slice(html.indexOf('function libRenderAsset'), html.indexOf('THE ATTACH/MAP UI IS GONE'));
  assert.match(card, /if \(a\.editable \|\| a\.houseEditable\) \{/);
  assert.match(card, /if \(a\.editable\) libOpenForm\(a, editHost, done\);/);
  assert.match(card, /else libOpenHouseForm\(a, editHost, done\);/);
  const route2 = fs.readFileSync(path.join(__dirname, '..', 'src', 'routes', 'settings.js'), 'utf8');
  assert.match(route2, /const editable = !isSeededAssetName\(a\.name\)/);
  // The per-field flag is the asset's OR the tier's — that disjunction is what
  // keeps every field of a tenant asset editable while opening only the
  // house_default ones on a bundled asset.
  assert.match(route2, /editable: editable \|\| isTenantEditableTier\(f\.spec_type\)/);
  // And `counts.editable` still means what it meant. A stale client reads it to
  // mean "opens the full form"; the new state travels in its own count.
  assert.match(route2, /editable: assets\.filter\(\(a\) => !isSeededAssetName\(a\.name\)\)\.length/);
  assert.match(route2, /houseEditable: decorated\.filter\(\(a\) => a\.houseEditable\)\.length/);
});

// --- Custom document types, step one: bring a template and find its markers ---

test('a placeholder split across runs is found, because runs are joined first', () => {
  const { discoverPlaceholders } = require('../src/destinations/docPlaceholders');
  // Exactly what Docs returns when a user bolds half a token, or when a
  // spellcheck mark lands inside one. On screen it is "{{Hero Headline}}".
  const doc = {
    body: {
      content: [
        {
          paragraph: {
            elements: [
              { textRun: { content: '{{Hero ' } },
              { textRun: { content: 'Headline}}', textStyle: { bold: true } } },
            ],
          },
        },
      ],
    },
  };
  const d = discoverPlaceholders(doc);
  assert.equal(d.counts.distinct, 1);
  assert.equal(d.placeholders[0].name, 'Hero Headline');

  // The failure mode this guards: scanning a single run finds nothing at all.
  const perRun = doc.body.content[0].paragraph.elements
    .map((e) => discoverPlaceholders({ body: { content: [{ paragraph: { elements: [e] } }] } }).counts.distinct)
    .reduce((a, b) => a + b, 0);
  assert.equal(perRun, 0, 'run-by-run scanning finds nothing — hence the join');
});

test('discovery reports where a marker is, including inside a merged cell', () => {
  const { discoverPlaceholders, describeLocation } = require('../src/destinations/docPlaceholders');
  const para = (t) => ({ paragraph: { elements: [{ textRun: { content: t } }] } });
  const d = discoverPlaceholders({
    body: {
      content: [
        para('Campaign copy matrix'),
        {
          table: {
            tableRows: [
              { tableCells: [{ content: [para('Form heading')] }, { content: [para('{{Form Heading}}')] }] },
              {
                tableCells: [
                  { content: [para('Submit')] },
                  { content: [para('{{Submit Button}}')], tableCellStyle: { columnSpan: 2 } },
                ],
              },
            ],
          },
        },
      ],
    },
  });
  assert.equal(d.counts.tables, 1);
  assert.equal(describeLocation(d.occurrences[0].location), 'table 1, row 1, column 2');
  // The span is reported, so "column 2" and "columns 2-3 merged" are tellable
  // apart — a tenant looking at their own matrix needs to recognize the cell.
  assert.equal(describeLocation(d.occurrences[1].location), 'table 1, row 2, column 2 (merged 1×2)');
});

test('two spellings of one marker are ONE placeholder, counted twice', () => {
  const { discoverPlaceholders, placeholderKey } = require('../src/destinations/docPlaceholders');
  const para = (t) => ({ paragraph: { elements: [{ textRun: { content: t } }] } });
  const d = discoverPlaceholders({
    body: { content: [para('{{Hero Headline}}'), para('{{ hero  headline }}')] },
  });
  assert.equal(d.counts.distinct, 1);
  assert.equal(d.counts.total, 2);
  assert.equal(d.placeholders[0].count, 2);
  // The name kept is the FIRST spelling seen — what the tenant most likely means.
  assert.equal(d.placeholders[0].name, 'Hero Headline');
  assert.equal(placeholderKey('Hero  Headline'), placeholderKey('hero headline'));
});

test('a malformed marker is a warning, and a well-formed one never is', () => {
  const { discoverPlaceholders } = require('../src/destinations/docPlaceholders');
  const para = (t) => ({ paragraph: { elements: [{ textRun: { content: t } }] } });
  const d = discoverPlaceholders({
    body: { content: [para('{{Hero Headline}} and {{Subhead}}'), para('{{Unclosed legal line')] },
  });
  // THE BUG THIS PINS. The first version scanned for `}}` over the raw text, so
  // the closing braces of every valid token were reported as unopened — seven
  // warnings for one real typo. Valid tokens are removed before the malformed
  // scan runs, so a clean document produces a clean report.
  assert.equal(d.counts.warnings, 1);
  assert.equal(d.warnings[0].kind, 'unclosed');
  assert.match(d.warnings[0].text, /^\{\{Unclosed legal line$/);
  assert.equal(discoverPlaceholders({ body: { content: [para('{{A}} {{B}} {{C}}')] } }).counts.warnings, 0);
});

test('a marker in a page header or footer is found and labelled as such', () => {
  const { discoverPlaceholders, describeLocation } = require('../src/destinations/docPlaceholders');
  const para = (t) => ({ paragraph: { elements: [{ textRun: { content: t } }] } });
  // Headers and footers are NOT in body.content — they are separate top-level
  // maps. A traversal that only walks the body silently loses them.
  const d = discoverPlaceholders({
    body: { content: [para('nothing here')] },
    headers: { h1: { content: [para('{{Campaign Name}} — internal')] } },
    footers: { f1: { content: [para('{{Page Label}}')] } },
  });
  assert.equal(d.counts.distinct, 2);
  assert.equal(d.counts.headers, 1);
  assert.equal(d.counts.footers, 1);
  assert.equal(describeLocation(d.occurrences[0].location), 'header · paragraph 1');
  assert.equal(describeLocation(d.occurrences[1].location), 'footer · paragraph 1');
});

test('the import is one call, and it is the call that triggers the converter', () => {
  const src = fs.readFileSync(
    path.join(__dirname, '..', 'src', 'destinations', 'docTemplateImport.js'),
    'utf8'
  );
  // The .docx goes in as the MEDIA mime; the Google Doc type goes in as the
  // REQUEST BODY mime. That exact pairing is what runs Drive's Word→Docs
  // converter — set only the media mime and Drive stores an opaque .docx.
  assert.match(src, /media: \{ mimeType: DOCX_MIME, body: stream \}/);
  assert.match(src, /mimeType: GDOC_MIME/);
  assert.match(src, /supportsAllDrives: true/);
  // Discovery runs over the CONVERTED document, read back from the Docs API —
  // so every marker reported is one that survived the import.
  assert.match(src, /clients\.docs\.documents\.get\(\{ documentId: docId \}\)/);
  assert.match(src, /discoverPlaceholders\(doc\.data\)/);
});

test('discovery is pure — no Drive, no Docs, no database, no Express', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'destinations', 'docPlaceholders.js'), 'utf8');
  // Deliberate: the risky question ("does the {{marker}} convention survive a
  // real tenant's document") has to be answerable with no credentials, and the
  // suite runs with none.
  assert.ok(!/require\(/.test(src), 'docPlaceholders requires nothing');
  // Comments stripped: the module's own header says the words "no Drive, no
  // Docs, no database, no Express", which is the claim, not a violation of it.
  const code = src.replace(/\/\/.*$/gm, '');
  assert.ok(!/googleapis|\bpool\b|express/i.test(code));
});

test('a template upload is session-scoped, size-capped and .docx only', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'routes', 'settings.js'), 'utf8');
  // Ends at the STEP TWO routes, which are a separate feature with their own
  // requireAuth gates — the old anchor (GET /api/settings/workspace) now
  // swallows them and would count their tenant reads as this one's.
  const region = src.slice(src.indexOf('--- Template documents'), src.indexOf('// POST /api/settings/templates/:id'));

  assert.match(region, /router\.get\(\s*'\/api\/settings\/templates',[\s\S]{0,120}requireAuth/);
  assert.match(region, /router\.post\(\s*'\/api\/settings\/templates',[\s\S]{0,120}requireAuth/);
  // Both are rate-limited: reads on the settings limiter, the upload on the
  // upload limiter, same as /api/upload.
  assert.match(region, /settingsReadLimiter/);
  assert.match(region, /uploadLimiter/);
  // The tenant is taken from the SESSION, never from the request body — the
  // same rule every other settings route follows.
  assert.ok(!/req\.body\.tenantId/.test(region));
  // requireAuth put the signed-in user on req.user; the tenant is read off that,
  // never off the multipart body, which carries the file and an optional name.
  assert.equal((region.match(/req\.user && req\.user\.tenant_id/g) || []).length, 2);
  // The write runs as the acting user, like every other Drive write.
  assert.match(region, /getClientsForTenant\(\{ tenantId, userId/);
  // The temp file multer wrote is removed whatever happens, including on throw.
  assert.match(region, /finally \{[\s\S]{0,200}fs\.unlink/);

  assert.match(src, /const TEMPLATE_MAX_BYTES = 10 \* 1024 \* 1024/);
  assert.match(src, /fileSize: TEMPLATE_MAX_BYTES, files: 1/);
  assert.match(src, /file\.mimetype === DOCX_MIME \|\| \/\\\.docx\$\/i\.test/);
});

test('step one stops at discovery — nothing maps, fills, or reaches the pipeline', () => {
  const root = path.join(__dirname, '..');
  const files = [
    'src/destinations/docPlaceholders.js',
    'src/destinations/docTemplateImport.js',
    'src/db/docTemplates.js',
  ];
  for (const f of files) {
    const src = fs.readFileSync(path.join(root, f), 'utf8');
    // The explicit out-of-scope list for this step. If a later step wires
    // templates into document building, it does it somewhere these three files
    // can be re-read against — not by quietly growing one of them.
    assert.ok(!/replaceAllText/.test(src), `${f} does not fill anything in`);
    assert.ok(!/document_types/.test(src), `${f} does not know about document types`);
    assert.ok(!/require\(.*core\/pipeline/.test(src), `${f} does not touch the pipeline`);
    assert.ok(!/getDestination/.test(src), `${f} does not touch the destination registry`);
    assert.ok(!/slack/i.test(src), `${f} has nothing to do with Slack`);
  }
  // And no route outside settings serves templates.
  const server = fs.readFileSync(path.join(root, 'src', 'server.js'), 'utf8');
  assert.ok(!/templates/.test(server));
});

test('the template store degrades rather than failing before its migration lands', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'docTemplates.js'), 'utf8');
  // Railway deploys main on merge, so this code runs against a database without
  // doc_templates for as long as it takes someone to run the migration. The
  // panel says "not available yet" in that window; it does not 500.
  // Anchored to the CALLS, not the words: both names appear in this file's
  // import line and in prose, so a bare /isUndefinedTable/ matched whether or
  // not anything used it.
  assert.match(src, /if \(isUndefinedTable\(err\)\) \{/);
  assert.match(src, /warnMissingSchema\('doc_templates', /);
  // Four accessors now: list, save, get one, rename. Every one of them degrades,
  // because a settings page that 500s before someone runs a migration is the
  // failure this contract exists to prevent.
  assert.equal((src.match(/isUndefinedTable\(/g) || []).length, 4, 'every accessor degrades');
  for (const fn of ['listDocTemplates', 'saveDocTemplate', 'getDocTemplate', 'renameDocTemplate']) {
    assert.ok(new RegExp(`warnMissingSchema\\('doc_templates', '${fn}'`).test(src), `${fn} degrades`);
  }
  // INSERT names its columns — no spread of caller input into SQL.
  assert.ok(!/\.\.\.template/.test(src));
});

test('the templates panel shows every marker with where it was found', () => {
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'settings.html'), 'utf8');
  assert.match(html, /data-tab="templates"/);
  assert.match(html, /id="panel-templates"/);
  assert.match(html, /id="tpl-file"[^>]*accept="\.docx"/);

  const js = html.slice(html.indexOf('--- Template documents'), html.indexOf('--- Markdown render'));
  // FormData with no Content-Type set by hand — the browser has to write the
  // multipart boundary itself or multer sees nothing.
  assert.match(js, /new FormData\(\)/);
  assert.ok(!/Content-Type': 'multipart/.test(js));
  // The location string is rendered SERVER-side (describeLocation) and printed,
  // so the page and the logs describe a cell the same way.
  assert.match(js, /\(m\.where \|\| \[\]\)\.forEach/);
  assert.match(js, /tpl-warn/);
  // An unclosed marker is surfaced to the tenant, not swallowed.
  assert.match(js, /tplRenderWarnings/);
});

test('summarizeStructure names each merge, so a lost one is identifiable', () => {
  const { summarizeStructure } = require('../src/destinations/docTemplateImport');
  const para = (t) => ({ paragraph: { elements: [{ textRun: { content: t } }] } });
  const s = summarizeStructure({
    body: {
      content: [
        {
          table: {
            columns: 3,
            tableRows: [
              { tableCells: [
                { content: [para('a')] },
                { content: [para('b')], tableCellStyle: { columnSpan: 2 } },
              ] },
              { tableCells: [
                { content: [para('c')], tableCellStyle: { rowSpan: 2 } },
                { content: [para('d')] },
                { content: [para('e')] },
              ] },
            ],
          },
        },
      ],
    },
  });
  // A COUNT can only say something is missing. The report has to say WHICH merge,
  // because "horizontal merges survive, vertical ones do not" is a rule a tenant
  // has to be told, and no total can express it.
  assert.equal(s.mergedCells, 2);
  assert.deepEqual(s.merges.map((m) => m.kind), ['horizontal', 'vertical']);
  assert.equal(s.merges[0].columnSpan, 2);
  assert.equal(s.merges[1].rowSpan, 2);
  assert.deepEqual(s.merges.map((m) => [m.table, m.row, m.column]), [[0, 0, 1], [0, 1, 0]]);
  // Short rows are reported, so whether a vertically covered cell is emitted at
  // all is read off the output rather than assumed.
  assert.deepEqual(s.tables[0].rowCellCounts, [2, 3]);
});

test('a merge that did not survive is reported LOST, not SURVIVED', () => {
  const { summarizeStructure } = require('../src/destinations/docTemplateImport');
  const para = (t) => ({ paragraph: { elements: [{ textRun: { content: t } }] } });
  // The converter flattened the vertical merge and kept the horizontal one.
  const s = summarizeStructure({
    body: { content: [{ table: { columns: 3, tableRows: [
      { tableCells: [{ content: [para('a')] }, { content: [para('b')], tableCellStyle: { columnSpan: 2 } }] },
      { tableCells: [{ content: [para('c')] }, { content: [para('d')] }, { content: [para('e')] }] },
    ] } }] },
  });
  // THE BUG THIS PINS. The probe compared this with `s.mergedCells >= 1` and
  // printed SURVIVED while a whole merge type was gone. One surviving merge is
  // not evidence that merges survive.
  assert.equal(s.mergedCells, 1);
  assert.ok(!s.merges.some((m) => m.kind === 'vertical'), 'the vertical merge is absent');
  assert.ok(s.mergedCells >= 1, 'the old check would still have passed — which is the point');
});

test('no fidelity check is a floor without a stated reason', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'scripts', 'probeDocxImport.js'), 'utf8');
  const code = src.replace(/\/\/.*$/gm, '');
  // A floor with no reason is a check that cannot fail, and three of them shipped:
  // merged cells, shaded cells and page headers were all `>= 1`. Comparisons now
  // go through exact() or atLeast(), and atLeast() THROWS without a reason — so a
  // future lenient check cannot be added silently.
  assert.ok(!/>= 1\b/.test(code), 'no bare >= 1 comparison survives');
  assert.match(src, /const exact = \(want, got\)/);
  assert.match(src, /a floor comparison must state why it is not exact/);
  // Every atLeast call site passes a third argument.
  const calls = code.match(/atLeast\([^)]*\)/g) || [];
  assert.ok(calls.length >= 1);
  for (const c of calls) assert.ok(c.split(',').length >= 3, `atLeast without a reason: ${c}`);
});

// --- Custom document types, step two: attach a template, map its markers ------

test('the attachment is INERT — the pipeline read cannot see it', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'assets.js'), 'utf8');
  // getTenantAssets is what the pipeline builds from. If it grew a
  // doc_template_id or a marker, an attached asset would stop rendering into the
  // copy doc the way it does today — which is exactly what step two must not do.
  const pipelineRead = src.slice(src.indexOf('async function getTenantAssets'), src.indexOf('// THE EDITOR READ'));
  // Comments stripped for the CODE checks — the block says the words
  // "NO doc_template_id AND NO template_marker HERE", which is the claim, not a
  // violation of it, and is asserted separately below.
  const pipelineCode = pipelineRead.replace(/\/\/.*$/gm, '');
  assert.ok(!/doc_template_id/.test(pipelineCode), 'no attachment on the pipeline read');
  assert.ok(!/template_marker/.test(pipelineCode), 'no marker on the pipeline read');
  assert.ok(/NO doc_template_id AND NO template_marker HERE/.test(pipelineRead), 'and it says why');

  // The editor read DOES carry both — that is the whole point of it being a
  // second reader.
  const editorRead = src.slice(src.indexOf('// THE EDITOR READ'), src.indexOf('// CREATE one tenant-authored'));
  assert.match(editorRead, /doc_template_id: t\.doc_template_id == null/);
  assert.match(editorRead, /template_marker_key: row\.template_marker_key/);

  // And nothing in the pipeline or the destinations reads either column.
  for (const f of ['src/core/pipeline.js', 'src/destinations/googleDocs.js', 'src/adapters/slackWorkflow.js']) {
    // Comments stripped. The rework's build path names `template_markers` when
    // it explains what a CONFIRMED template is; naming the new table in prose is
    // not reading the OLD asset attachment, which is what this guards.
    const other = fs.readFileSync(path.join(__dirname, '..', f), 'utf8').replace(/\/\/.*$/gm, '');
    // asset_types.doc_template_id is the dead attachment. projects.doc_template_id
    // is a DIFFERENT, live column — which template the matrix was copied from, so
    // the draft path can read its markers. Same word, opposite meaning, so the
    // guard names the asset-library reads rather than the bare column name.
    assert.ok(!/copy_fields\.template_marker|asset_types\.doc_template_id|getAssetTemplateBindings/.test(other),
      `${f} does not read the attachment`);
    assert.ok(!/a\.doc_template_id|at\.doc_template_id/.test(other), `${f} reads no asset's attachment`);
  }
});

// --- Custom document types, step three: build the second document ------------

test('createFromTemplate copies, then fills, and leaves unmapped markers alone', async () => {
  const gdocs = require('../src/destinations/googleDocs');
  const calls = [];
  const clients = {
    drive: { files: { copy: async (a) => {
      calls.push(['copy', a.fileId, a.requestBody.name, (a.requestBody.parents || [])[0]]);
      return { data: { id: 'NEW1', name: a.requestBody.name, webViewLink: 'https://d/NEW1' } };
    } } },
    docs: { documents: { batchUpdate: async (a) => { calls.push(['batchUpdate', a.requestBody.requests]); return { data: {} }; } } },
  };
  const out = await gdocs.createFromTemplate({
    sourceDocId: 'SRC',
    name: 'Spring — Matrix',
    folderId: 'FOLDER',
    values: new Map([['form headline', 'Book your seat']]),
    markers: [{ name: 'Form Headline', key: 'form headline' }, { name: 'Form ID', key: 'form id' }],
    clients,
  });

  assert.deepEqual(calls[0], ['copy', 'SRC', 'Spring — Matrix', 'FOLDER']);
  // ONE request, for the ONE marker that had copy. Nothing is sent for {{Form ID}}.
  const requests = calls[1][1];
  assert.equal(requests.length, 1);
  assert.deepEqual(requests[0].replaceAllText.containsText, { text: '{{Form Headline}}', matchCase: false });
  assert.equal(requests[0].replaceAllText.replaceText, 'Book your seat');
  assert.deepEqual(out.filled, ['Form Headline']);
  assert.deepEqual(out.unfilled, ['Form ID']);
  // The rule, stated as an assertion: no request ever replaces a marker with ''.
  assert.ok(!requests.some((r) => !String(r.replaceAllText.replaceText || '').trim()));
});

test('nothing is sent to Docs when a template has no copy at all', async () => {
  const gdocs = require('../src/destinations/googleDocs');
  let batched = 0;
  const clients = {
    drive: { files: { copy: async () => ({ data: { id: 'N', webViewLink: 'u' } }) } },
    docs: { documents: { batchUpdate: async () => { batched += 1; return { data: {} }; } } },
  };
  const out = await gdocs.createFromTemplate({
    sourceDocId: 'SRC', name: 'x', values: new Map(),
    markers: [{ name: 'A', key: 'a' }, { name: 'B', key: 'b' }], clients,
  });
  // A brief-time build has no drafted copy, so this is the ordinary case, not an
  // edge one — and an empty batchUpdate is an error from the Docs API.
  assert.equal(batched, 0);
  assert.deepEqual(out.unfilled, ['A', 'B']);
});

test('the template documents are built BEFORE the copy doc', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'core', 'pipeline.js'), 'utf8');
  const build = src.slice(src.indexOf('async function generateDoc'), src.indexOf('async function generateDraft'));
  // copyTemplateDocument, not buildTemplateDocument: at brief time the matrix is
  // STRUCTURE, exactly as the copy doc is. The draft half runs on the button.
  const tplAt = build.indexOf('await copyTemplateDocument({');
  const docAt = build.indexOf('createDocument({');
  assert.ok(tplAt > -1 && docAt > -1);
  // Set now so it does not have to be rearranged: the copy doc will carry a link
  // to these, and a link cannot be written to a document that does not exist.
  assert.ok(tplAt < docAt, 'the template document is built before the copy doc');
  // The copy doc gets every spec — there is no partition any more.
  assert.match(build, /assetSpecs: copyDocSpecs,/);
  assert.match(build, /const copyDocSpecs = assetSpecs;/);
  // A template failure never takes the brief down — the copy doc is primary.
  assert.match(build, /template document "\$\{group\.templateName\}" failed/);
  assert.match(build, /templateDocs\.push\(\{ templateId: group\.templateId, templateName: group\.templateName, error: err\.message \}\)/);
});

test('the pipeline reaches Google only through the destination', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'core', 'pipeline.js'), 'utf8');
  // BOTH build functions — generateDoc and buildTemplateDocument, which
  // generateDoc now calls. The slice ends at the step-three read-back block,
  // whose comments name the Google APIs it routes around.
  //
  // NOT the whole file, and that is not a loosening: pipeline.js DOES call Drive
  // directly outside the build path — reference ingestion (:64, :75, :83) and the
  // two best-effort metadata reads, countDocAssets (docs.documents.get) and
  // getFolderName (drive.files.get). CLAUDE.md's claim is about the DOCUMENT
  // BUILDING surface, which is what this slice covers.
  const build = src.slice(src.indexOf('async function generateDoc'), src.indexOf('// --- Step three: read a built template back'));
  // files.copy and batchUpdate live in googleDocs.js, behind createFromTemplate
  // and writeTemplateCells — the same contract createDocument and generateDraft
  // go through, so a second destination can implement it.
  //
  // Comments stripped: buildTemplateDocument's header sits inside this slice and
  // NAMES drive.files.copy when it explains which mechanism createFromTemplate
  // reuses. Naming an API in prose is the opposite of calling it.
  assert.ok(!/files\.copy|replaceAllText|batchUpdate/.test(build.replace(/\/\/.*$/gm, '')));
  assert.match(build, /getDestination\(\)\.createFromTemplate\(/);
  assert.match(build, /getDestination\(\)\.writeTemplateCells\(/);

  // AND fillTemplateMarkers IS GONE. It was the two-replacement re-sync trick:
  // offer replaceAllText both the {{marker}} and the copy written last time, and
  // whichever is present wins. It existed because a template was filled FROM the
  // copy doc, after drafting, over and over. A template's fields are its own now
  // and are written once by coordinate, so nothing needs a second handle.
  assert.ok(!/fillTemplateMarkers/.test(src), 'the re-sync trick is not referenced anywhere in the pipeline');
  const docs = fs.readFileSync(path.join(__dirname, '..', 'src', 'destinations', 'googleDocs.js'), 'utf8');
  assert.ok(!/fillTemplateMarkers/.test(docs), 'and the destination no longer implements it');
});

test('the project row records the template document without disturbing copy_doc_id', () => {
  const src = fs.readFileSync(path.join(__dirname, '..', 'src', 'db', 'projects.js'), 'utf8');
  // copy_doc_id still means the promo doc, and idempotency still keys on it.
  assert.match(src, /WHERE tenant_id = \$1 AND copy_doc_id = \$2 LIMIT 1/);
  assert.match(src, /template_doc_id = null,\n\s+template_doc_url = null,/);
  // EVERY COMBINATION of optional columns, not a priority order — a database
  // with template_doc_* but no created_by must not lose both. Generated rather
  // than hand-written, which is what let the FOURTH group (brief_raw) be one
  // array entry instead of doubling sixteen hand-kept lines.
  assert.match(src, /const GROUPS = \[CREATED_BY, TEMPLATE, DRAFT_LINK, BRIEF_RAW, FIELD_MANIFEST\]/);
  assert.match(src, /for \(let mask = \(1 << GROUPS\.length\) - 1; mask >= 0; mask--\)/);
  assert.match(src, /attempts\.sort\(\(a, b\) => b\.groups\.length - a\.groups\.length/, 'widest first');
  // brief_raw is its OWN group and not folded into DRAFT_LINK: they arrived in
  // different migrations, so a database can have one and not the other and the
  // set has to be able to drop exactly one of them.
  assert.match(src, /const BRIEF_RAW = \{ extra: \['brief_raw'\], values: \[brief_raw\] \}/);
  assert.match(src, /const DRAFT_LINK = \{\s*\n\s*extra: \['doc_template_id', 'brief_summary', 'brief_writer_prompt'\]/);
  // …and field_manifest is the FIFTH, on exactly the same terms — the payoff the
  // generated power set was built for. Stringified on the way in because the pg
  // driver sends a bare object as a composite rather than as jsonb, and NULL has
  // to stay NULL so the column reads UNKNOWN rather than the JSON text "null".
  assert.match(src, /const FIELD_MANIFEST = \{\s*\n\s*extra: \['field_manifest'\]/);
  assert.match(src, /field_manifest == null \? null : JSON\.stringify\(field_manifest\)/);
  // The generated set really does include the singletons and the empty one —
  // asserted by running the generator, not by matching lines that no longer
  // exist. Thirty-two subsets of five groups, widest first, ending with none.
  const GROUPS = ['CREATED_BY', 'TEMPLATE', 'DRAFT_LINK', 'BRIEF_RAW', 'FIELD_MANIFEST'];
  const gen = [];
  for (let mask = (1 << GROUPS.length) - 1; mask >= 0; mask--) {
    gen.push({ mask, groups: GROUPS.filter((_, i) => mask & (1 << i)) });
  }
  gen.sort((a, b) => b.groups.length - a.groups.length || b.mask - a.mask);
  assert.strictEqual(gen.length, 32);
  assert.deepStrictEqual(gen[0].groups, GROUPS, 'widest first');
  assert.deepStrictEqual(gen[31].groups, [], 'and the bare insert last');
  for (const g of GROUPS) assert.ok(gen.some((a) => a.groups.length === 1 && a.groups[0] === g), `${g} alone is tried`);
  // The pair that matters most: brief_raw present WITHOUT the older draft-link
  // columns, and vice versa. Neither can take the other down.
  assert.ok(gen.some((a) => a.groups.includes('BRIEF_RAW') && !a.groups.includes('DRAFT_LINK')));
  assert.ok(gen.some((a) => a.groups.includes('DRAFT_LINK') && !a.groups.includes('BRIEF_RAW')));
  // Same independence for the newest group, in both directions — a database that
  // has run the manifest migration but not brief_raw (or the reverse) must keep
  // whichever column it does have.
  assert.ok(gen.some((a) => a.groups.includes('FIELD_MANIFEST') && !a.groups.includes('BRIEF_RAW')));
  assert.ok(gen.some((a) => a.groups.includes('BRIEF_RAW') && !a.groups.includes('FIELD_MANIFEST')));
  assert.match(src, /isUndefinedColumn\(err\)/);
});

test('both surfaces show both documents, and the copy doc stays first', () => {
  const slack = fs.readFileSync(path.join(__dirname, '..', 'src', 'services', 'slack.js'), 'utf8');
  // Anchored on the CONFIRMATION comment, not on the phrase "Saved to <folder>"
  // — that appears in the file header too, 70 lines above, and slicing to it
  // yields an empty string that passes every indexOf comparison vacuously.
  const links = slack.slice(slack.indexOf('const links = [];'), slack.indexOf('confirmation, below the links'));
  assert.ok(links.length > 200, 'found the links block');
  // Copy doc pushed BEFORE the loop over templateDocs, so it is always first.
  assert.ok(links.indexOf('Copy doc>') < links.indexOf('for (const t of templateDocs'));
  assert.match(links, /t\.templateName \|\| 'Template document'/);
  // A template that failed to build says so — the writer is expecting a second
  // document and would otherwise just not find one.
  assert.match(links, /Couldn't build \$\{failed\.map/);

  // The web adapter carries them, and the Slack adapter hands them over.
  const web = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'web.js'), 'utf8');
  assert.match(web, /templateDocs: \(templateDocs \|\| \[\]\)\.map/);
  const sw = fs.readFileSync(path.join(__dirname, '..', 'src', 'adapters', 'slackWorkflow.js'), 'utf8');
  assert.match(sw, /templateDocs = \[\][\s\S]{0,40}\} = docResult/); // the destructure has grown; templateDocs is still in it

  // And the project view has a second button, hidden unless there is one.
  const html = fs.readFileSync(path.join(__dirname, '..', 'public', 'app.html'), 'utf8');
  assert.match(html, /id="project-template-btn"/);
  // The condition grew a second clause when the detail view gained its Documents
  // index: both Drive buttons are document-scoped, so they also stand down on the
  // index, where no document is in view. The claim here is unchanged — no button
  // for a document that does not exist.
  assert.match(html, /tplBtn\.classList\.toggle\('hidden', onIndex \|\| !p\.template_doc_url\)/);
  // "Open in Drive" is still the primary and still opens the copy doc.
  assert.match(html, /if \(p && p\.copy_doc_url\) openDocUrl\(p\.copy_doc_url\)/);
});

